/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140825-6","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"区民委員会","time":"午後１時００分～午後４時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区民芸術祭２０１４の開催","agenda":"品川区民芸術祭２０１４の開催","exchanges":[{"speaker":"井上委員","kind":"質問","question":"１つ、最後の協賛事業のところでお伺いをしたいのですけれども、パンフレットを持っていくと割引というようなお話があったのですが、具体的にはどういうことなのかと、あとそれをどういうふうに区民の方が知ることができるのか、その辺を教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"原美術館と久米美術館の協賛事業のことですが、これは文化振興事業団と連携しまして、今、まだパンフレットができ上がってございませんので、区民のほうには配布してございませんが、そこに持っていって提示すると１００円の割引をするです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"同じになりますが、パンフレットというのはどういったところに箱をつくるのか、パンフレットの存在がどこにあるか知らないとそれもできないのですけれども、どういうふうに配布をしたり、提供するような予定でお考えですか。","respondent":"安藤文化スポーツ振興課長","answer":"それとまた、区民につきましては、今資料にもあります２枚目の団体・サークルの活動の発表、この人たちも総勢で１,０００人ぐらいいらっしゃいます。その人たちを通じて、ＰＲをして周知をしていただくというように考えています。","voiceIndex":10,"id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"第５回目ということで、記念事業みたいな形で行われるのですけれども、ざっくりでいいのですが、来場者数ですね。どのような傾向になっているのか。だんだん盛り上がってきているのか。やはり企画によっても随分違うと思うのですけれども、見に来ていただく方の傾向ですね。こちらのほうを教えていただければと思います。","respondent":"安藤文化スポーツ振興課長","answer":"今回５回目ということで実施させていただきました。その間、１回目から紆余曲折をしながら、実行委員会も組織され、また、議会のほうからもご意見をいただきながらやってきました。","voiceIndex":12,"id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"１万人の方が参加をされるということで、非常に大きなイベントになってきていると思います。５回まで１つの区切りとして、それが第１０回とか、また次の区切りに向けて発展させていっていただければと、要望をしておいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"}]},{"id":"topic-02","title":"高齢者の消費者被害防止に向けた地域での見守り","agenda":"高齢者の消費者被害防止に向けた地域での見守り","exchanges":[{"speaker":"井上委員","kind":"質問","question":"高齢者の消費者被害防止に向けた地域での見守りというのは本当に重要なことで、続けなくてはいけないというふうに思うのですが、消費者センター所管が商業・観光課ということなのですけれども、高齢者の実態としてどういう、これは防犯のほうも入ると思うのですが、これをやるに当たって、毎年こうやって民生委員を通じてやりましたではなくて。","respondent":"米田商業・観光課長","answer":"当然、逆にそれぞれの高齢者にかかわる部署のほうから消費者センターへのご相談というのもありますので、そういうようなものがあれば、消費者被害の防止というような観点から速やかに対応しているものですが、とにかく情報として入らない限りは動きようもありませんので、その人。","voiceIndex":24,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"具体的にこの平成２５年の表で見ると、７０歳以上の方は相談の件数ということで被害の件数ではないのですけれども、その辺、被害者としてはどういう家族構成なのかというのは、もちろん生活安全担当課長のほうでも振り込め詐欺の件数とか増えているというような、毎回毎回パトロールをしていただいているのですが、そこで被害者としての対象家庭構成というのは。","respondent":"上垣外生活安全担当課長、米田商業・観光課長","answer":"したがいまして、そこを重点的に警察署と連携をして、防犯等の広報活動をしているところであります。こちらのほうも相談の事例を通じてですけれども、今回のこのパンフレットを民生委員の方にお願いする趣旨もそうでありますが、高齢者の方の、いわゆるご判断能力がやはり落ちるということ、それからあわせて。","voiceIndex":26,"id":"exchange-006"},{"speaker":"井上委員","kind":"意見","question":"民生委員さんたちの中でよくお話を聞くと、１回調査のときには回って、あとは気になる方を、そんなに全部の方を回るわけではないので、そういうときに特に説明をされて、これをお知らせするときに民生委員さんにもどういう、ただ一般的には今おっしゃられたようなケースということでお願いするのでしょうけれども。","respondent":"米田商業・観光課長","answer":"消費者センター、あるいは、もしくは関係機関につなげてほしいというようなことについては継続的に取り組んでいく必要があるだろうと、このように考えながら業務を行っているところです。","voiceIndex":29,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここに書いてある件数というのは相談件数ということなのですけれども、品川区内ですごく周りを見ても、何人も結構振り込め詐欺に引っかかって、何百万円と振り込んでしまったという人が何人もいるのですよね。多分警察のほうにも被害届という形で出されているのではないかと思いますけれども、その件数をまずちょっと教えてください。","respondent":"米田商業・観光課長、上垣外生活安全担当課長","answer":"それからあともう１点、自分は絶対に引っかからないというような形で、特に元気で判断能力もある方も、いざ実際自分の、例えばご親族等を名乗られて、相手がにせものであっても親族と信用すると、そこでこういう事件が起きた。これにつきましては、いわゆるオレオレ詐欺といった特殊詐欺につきましては、平成２６年６月末現在で、品川区内で３６件被害を認知しております。被害額につきましては約６,８００万円あまりという状況であります。","voiceIndex":31,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その３６件というのは、６月末というのはいつから、今年だけということでしょうか。そこのところ。","respondent":"上垣外生活安全担当課長","answer":"これは平成２６年１月１日から６月末までの数字です。","voiceIndex":34,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に今年の半年間だけでこれだけの被害、いろいろなところでこういう啓発がいろいろな機会を通じて、町会なり、いろいろなところでされていて、こういうふうな手口があるというふうなことがわかっていながらだまされてしまうという、そういう状況になっていると思うのですけれども、この間もちょっとテレビでも、詐欺をビジネスとしてやっていくという。","respondent":"上垣外生活安全担当課長","answer":"こういった具体的な取り扱い要領を書いた張り札を配って張ってもらうと。こういうような取り組みをしているものもあります。","voiceIndex":36,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひそういうところで、ビジネスとしてそういうふうにはびこってしまっているという社会のゆがみでもあると思いますので、その辺のところの摘発、それから高齢者側の啓発というところで、さらにこれが被害をなくす方向で、ぜひ取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-011"},{"speaker":"木村委員","kind":"意見","question":"３０代、４０代、そして７０代ということですが、この間の５０代、６０代というのは、なぜこのようにしてほかのものよりは低いのか。どこに原因があるのか。わかりますか。","respondent":"米田商業・観光課長","answer":"それから７０歳以上というのが、今のところちょっと７０歳以上という形で全部まとめていますので、この辺については確かに多いのですけれども、例えば７０歳と８０歳の区分けがされていないという部分では。","voiceIndex":43,"id":"exchange-012"},{"speaker":"木村委員","kind":"意見","question":"そうですね。いろいろとやっていることと思いますけれども、この民生委員の方々だけではなく、町会単位で若い方々のそれに対するアドバイスを受けるような、何かすぐ相談ができるような、そういう態勢というのはつくれないのかどうか。","respondent":"米田商業・観光課長","answer":"１人、２人で考えるよりも、たくさんの知恵があったほうが対処の方法もしやすい、それぞれの専門的知見からの対処の方法もしやすいということで、そのようなことについては、町会ということでは特に若い方に向けても、若い方は若い方での相談案件の特徴というものがありますので。","voiceIndex":45,"id":"exchange-013"},{"speaker":"木村委員","kind":"質問","question":"そういうことで、考えていることは多分同じようなことだと思うのですが、実際にそれを声を出して、本当にそういう若い人たち、その地域の方々、みこし、もしくは消防団、そういうふうな方々に対して、実際にそういうことが行われているのかどうか、まだ考えている最中なのかどうか。現在進行中なのかどうかということをお伺いします。","respondent":"米田商業・観光課長","answer":"紙面で送るというようなこともあろうかと思いますけれども、例えば区役所に来庁される方等に、いわゆるロビー等で若者向けの消費者被害というようなことのお知らせであったり、あるいは消費生活展も特に年代層を限っておりませんので。","voiceIndex":47,"id":"exchange-014"},{"speaker":"木村委員","kind":"質問・要望","question":"地域で町会長に連絡を回して、実際にそのような有志の方々を集めて、高齢者の方々に対しての見守り隊としての実際の行動をやはり起こさなければならない、このように思うのですけれども、機会があれば本当にそれはぜひやっていただきたいなと思います。これは要望であります。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"いろいろなケースがあるかと思うのですが、振り込め詐欺等特殊詐欺の場合、大体は電話がかかってくると思うのですけれども、その電話がかかってきたとき、被害にあったときの電話番号等、後で犯人を捜すときに役立てる方法として、そういうのに取り組んでいる自治体もあるそうなのですが、例えば非通知にしておけば電話がつながらないとか、何かその電話に対する取り組みとか、状況というのはどうなのですか。","respondent":"上垣外生活安全担当課長、米田商業・観光課長","answer":"警察署のほうでは、こういったものを防ぐために振り込め詐欺見張隊というような録音機器を無償貸与しておりまして、こういったものを使って被害の防止に努めているという対策もしているところです。現況のような警察の取り組みについては、消費者部門にも警察等より情報提供、あるいは生活安全のほうより情報提供があり、そちらの情報については共有しています。","voiceIndex":50,"id":"exchange-016"},{"speaker":"本多委員","kind":"意見","question":"そういう電話の後で犯人捜しまでたどり着けるケースもあるということだと思うのですけれども、それはそれでいいのですが、被害防止に向けた電話に関する、例えば電話がなければ被害もなくなるとか、何か抜本的なその先の防止につながる、さらに防止になるような発想というものがないものかなと思うのですけれども、まずそれをちょっと聞かせてください。","respondent":"上垣外生活安全担当課長、米田商業・観光課長","answer":"区としても新たな取り組みといたしまして、例えば区内を集配等で巡回する業者、その方たちにご協力をいただいて、その家庭の中で。こういうような警察の取り組みは、恐らく振り込め詐欺の人間がそういうところにたまたま電話をかけてとれば、ある程度、どちらかというと、そこに続けてだまそうというよりは、もう切ってしまおうというような形で。","voiceIndex":53,"id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"はちょっと確認なのですけれども、閣議決定で開業率・廃業率が、いわゆる米国・英国レベルの１０％台になっていますが、開業率が１０％台といいますのは高いというのがわかるのですけれども、廃業率も同時に上げていくということというのは、これどういう趣旨なのか、まず教えていただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"これ、ものづくりなり、中小企業白書などからも引用されている考えで、そうしたことが貫かれているのかなというふうに私のほうは捉えてあります。","voiceIndex":63,"id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"わかりました。それと創業支援の資金に関してなのですけれども、一般の融資に関しての数字が８０％と課長からおっしゃっていましたが、質問する前に、私としては区が、いわゆる融資あっ旋紹介をしたからには、限りなく１００％に近く金融機関からお金が出る、保証協会から保証されて金融機関からお金が出ることを目指すことがいいと考えていますので、それで区の権威があるわけですから。","respondent":"山崎ものづくり・経営支援課長","answer":"ですから必ずとめられるというものでもなくて、やはり信用保証協会のチェックが入りますので、それではそちらの窓口に一度行ってみてくださいよといって、やはり私の計画では、さらに区の支援員と同じようなことを言われたということでまた戻ってきたりとかというようなことが。","voiceIndex":65,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"創業支援の融資はあれですよね。普通の融資よりも何回も来ていただいて、相談員といろいろ煮詰めて、さあやっていこうとするわけではないですか。だから、そういう金融機関のプロの査定からすると通らないとなってしまうわけではないですか。半分以下しか通らないですよと。そして、通らなかったけれども起業したい、創業したいと思っている方をどうフォローしていくか、その辺についてはいかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"そういうことで、新しい施設も含め、これから融資も含め、相談のこともやっておりますけれども、よりここ品川の地で創業していただく人のための行政としての取り組みだとか、委員が言われたようなことを含めて、やはり検討してここのところは強化してまいりたいなというふうに。","voiceIndex":67,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"確実に通るという。それはわかっているのですけれども、そこで創業するに当たって、一か八かで出してあげる、出してみる、通るかもしれないねというのも大事なのですが、せっかく相談員というプロがいるわけですから、数字を上げろという意味ではなくて、そこでいろいろもみ込んでやっていって、ここでは通らないよ、これでは通らないよと。応援していってもらいたいという気持ちで言っているので。","respondent":"山崎ものづくり・経営支援課長","answer":"その中で相談員と連携をしながら、総合力で品川の地で創業する人たちの応援といいますか、そういったものを今後より強化しながら施策を、新施設も含めてやってまいりたいなというふうに考えてあります。","voiceIndex":69,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの創業の支援資金というところは創業支援の融資の件数が、先ほど１２５件相談があって６９件実行だということだったのですが、この融資ではなくて、実際に品川区内で創業されている件数というのが、１年間でどれぐらいの件数があって、その業種、業態はどんなものなのか、またそこでの新たな雇用の人数とか、そういうのがちょっとわかったら教えていただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"推測しますと、先ほど東京都に２００万の事業所があって、品川区では２万ほどの事業所がありますので、そうした比率から考えると、東京都下の数字４.６％ないしのこの数字と、品川区部も東京のその数字と、そんなに違いはないのではないのかなというようなことで。","voiceIndex":71,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、この創業支援センターの現状というふうなこともご報告いただいたのですが、例えば西大井でいえば創業支援スペースのところは入居期間が１年で２回更新、オフィススペースでは２年で４回更新ということなので、８年間いられるという状況になるのかなと思うのですけれども、それぞれありますが、ここのところの利用率というのは九十何％ということで書かれているのですけれども。","respondent":"山崎ものづくり・経営支援課長","answer":"本日、西大井につきましては、入居者のそういった動きといいますか、それから入居後の状況ですとか、この施設に行って目的に照らした成果の部分というところについてご説明をして、やりとりをしていただくようなこともありますので。","voiceIndex":73,"id":"exchange-023"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"井上委員","kind":"質問","question":"京都のところで、京都府中小企業応援条例というのが平成１９年につくられているということなのですけれども、品川区で、要綱とか何かでこれと同じようなものというのはあるのでしょうか。","respondent":"中川原地域振興事業部長","answer":"今年度に入っていろいろな条例ができてきていますが、うちの特色としてはあまりそういうものをつくってやるということはやってこなかった経緯があります。","voiceIndex":82,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":36979,"voices":87}},{"id":"h26-20140825-7","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"厚生委員会","time":"午後１時００分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２６年度高齢者福祉週間行事","agenda":"の平成２６年度高齢者福祉週間行事","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"毎年、こういった事業がされていると思うのですけれども、１００歳だったり、１０１歳だったりというのは、ご家族も一緒におられることだと思うのです。それから、在宅介護者、要介護認定を受けた方のご家族、そういった方々から何か声といいますか、こういったものを受け取る際の思いみたいなものは出てくるのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"私からは、お祝い事業の訪問の際に、ご家族の方からの声というご質問をいただきましたので、そちらのほうにお答えします。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういった在宅介護者のところなどでは、ここの事業ではないのですけれども、介護する方の交流会みたいなものもやられていると思うのですけれども、ここですね、交流会と書いてありますね、こういう集いの中では、苦労をいろいろ分かち合ったりとか、そういう場になっているということですかね。","respondent":"永尾高齢者福祉課長","answer":"交流会のほうは、昨年ですと、お昼御飯を食べながら、一定程度グループになって、在宅介護支援センターのケアマネジャーだとか区の職員なども一緒に入りながら、日ごろのいろいろな悩みや、またご相談なども、お話の中で解決できるところの糸口を見つけてあげたり。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"のサービス付き高齢者住宅ｃａｒｎａ（カルナ）五反田入居者の新規募集","agenda":"のサービス付き高齢者住宅ｃａｒｎａ（カルナ）五反田入居者の新規募集","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"４万円限度の助成は、区から助成されると思うのですけれども、その財源は、国とか、そういうのが入っているのかどうか、その辺のところを教えていただきたい。それから、サービス付き高齢者住宅かちょっとわからないのですけれども、原小学校跡が似たようなところなのかもしれないのですけれども、そことの違いがあれば、教えていただきたい。","respondent":"白鳥高齢者いきがい課長、大串福祉計画課長","answer":"それ以外の併設施設の認知症高齢者グループホーム、小規模多機能型居宅介護につきましては、福祉計画課長のほうからご説明いたします。４点目の、サービス付き高齢者住宅から併設の施設への入居に関して、私のほうからお答えします。結論から申し上げますと、特にそこでの優先ということはございません。","voiceIndex":14,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"そうすると、確認なのですけれども、先ほどのこうほうえんですとか、大井林町との違いというところで、今ある大井林町とかこうほうえんのほうは、要介護の方でも入られていると。そしてこちらのほうは、いわゆる自立している方という、そういう違いなのかという確認。その確認を２点、すみません、お願いします。","respondent":"白鳥高齢者いきがい課長、大串福祉計画課長","answer":"ただ、ここにつきましては、やはり併設している施設もあることから、安心して入居していただけるということでは、入居資格としましては、審査の段階でどのように受け入れられるかどうかというところを判定いたしますので、現時点では。当然、入居者の身体の状況に応じて、さまざまなサービスはご利用可能となっておりますので、併設されているこういった施設についてのご利用も可能という形で対応していきたいと考えています。","voiceIndex":17,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"２点ほどお聞かせください。結構大きな金額を投入しているのだけれども、それで、家賃をこれくらい出していただいて、家賃補助を出しているから、実際は下がることはわかるのですけれども、もともとの家賃設定の考え方というのは、建設費補助を入れて、しかも家賃補助まで入れて、この金額がどういう算出でされたのかということについて、品川区はどうお考えなのでしょうか、お伺いしたいのです。","respondent":"白鳥高齢者いきがい課長","answer":"２点ご質問があったかと思います。医療法人社団青葉会の概要ですけれども、これまで、青葉会のほうとは、いろいろな打ち合わせをしてきたところです。","voiceIndex":20,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"ということからすると、この家賃設定の仕組みを、今、高齢者いきがい課長としては、ほかの五反田地区のマンションの金額を調べたというのだけれども、例えば、これからのケースも含めて、同じようなケースがこれから展開していく中にあって、品川区ではない専門の業者の方々に調査してもらうなり、新しい形を構築していかないと、税金を投入した金額と、それから家賃補助をする金額と照らし合わせて。","respondent":"白鳥高齢者いきがい課長","answer":"ただいま、委員よりご指摘をいただきました、医療法人社団青葉会についての詳しい説明につきましては、これは９月１日からの募集ということにはなりますが、その後の入居説明会のときに、こちらの青葉会が出されているリーフレットも添え、あるいは説明会の導入部分の中で。","voiceIndex":22,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"すみません、１点だけ質問させてください。応募資格のところに、連体保証人、また身元引受人と書いてあるのですが、これに全て該当する方ということでありますけれども、今は結構お一人暮らしの方もいて、なかなか連体保証人がいなくて、金銭的にお金を使って連体保証人になるなどというのもあるのですが、ここはどういう考え方でしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"連体保証人のご質問ですけれども、このように複合的につくられている施設ですので、入居者にとってみれば、非常に安心して住み続けられるという、そういった環境をつくっているところではありますけれども、やはり緊急時の対応の中でも。","voiceIndex":25,"id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、そういう引受人、または保証人のいない人は、ここには当てはまらないと取ってよろしいですか。","respondent":"白鳥高齢者いきがい課長","answer":"はい、こちらにつきましては、リーフレットの２．入居申込み資格についての４．になりますが、ここでは連体保証人・身元引受人を選定できる方、ということで、選定できない場合につきましては、後見人が必要になりますということで謳わせていただいておりますので。","voiceIndex":27,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ちょっと幾つか伺いたいのですが、先ほど補助金という話もあったのですけれども、建設に対して、国、東京都、区からどのくらいの割合で入っているのか、わかれば教えていただきたい。４万円限度で助成が受けられるということなのですけれども、基本サービス料が４万１,０００円かかる。一応、区立の大井林町の資料を見たときに、基本サービス料が生活支援サービス費ということなのですが、単身者で１万円と。","respondent":"白鳥高齢者いきがい課長","answer":"こちらのリーフレットの５ページになりますが、４．提供するサービスについて、ということで、基本サービス、区立大井林町のほうと、1)生活支援サービスの中での生活相談、安否確認と、緊急対応、それから、2)フロントサービスは、大井林町でも行っているところです。","voiceIndex":29,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"基本サービスのところでは、区立のほうも同じ内容なのですよね。今後、こういったサービス付き高齢者住宅を、こういう状況なら、この違いを見て、私は本当に区立で建てていただきたいと思いました。今後、建設していく計画、検討、また、民営でも建設しようとしているところがあるとか、そういうものは今のところ、どうでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"民間事業者によるサービス付き高齢者向け住宅の開設支援ということは、プレス発表でもさせていただいたとおり、高齢者の住宅ですとか、介護・医療サービスなどの複合施設を整備していこうという、そういった法人事業者等がありましたら。","voiceIndex":31,"id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"体制のことを聞きたいのですけれども、運営は青葉会がやると。それで、生活相談、安否確認、要は基本サービスのところ、ここも青葉会ですよね、ここの体制を伺いたいのです。２４時間なので、どう回していくのかは、こちらでわかるのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"生活支援サービス、これは巡回、安否確認、緊急時の対応等々ですけれども、こちらにつきましては、１階の相談室、それから６階のスタッフステーションで対応するということで、ここでの人数は出ておりません、申し訳ございません。","voiceIndex":33,"id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"わかる範囲があると思うので、わかりました。やっぱり先ほども言いましたけれども、こういった高齢者住宅を求める声もあると思うのですが、それを利用しやすくしていかなければ意味がないと思うので、民間がこれから入ってくる、区でつくるのであれば大井林町の例があると思うのですけれども、これが民営の第一の例になってしまうと、本当にちょっと厳しいと感じます、今の高齢者の実態を見ると。","respondent":"白鳥高齢者いきがい課長","answer":"今回の事業者への支援という区の立場からいたしますと、今回、先行的にこういうサービス付き高齢者住宅の施設ということで、今後の推移を見守りながら、利用者の声にも耳を傾けながら、よりよい、利用しやすいこういうような施設を。","voiceIndex":35,"id":"exchange-012"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"ほかによろしいでしょうか。私から確認なんですが、Ａ３版の資料をつくっていただいたのは、概要でやったと思うのですが、その中で、先方の資料の中には選考方法が出ているのですが、こちらの中には選考方法を入れていないのは、一般的に、こういう場合は選考方法は入れないものなのか。区の広報に出した中でも入るのかどうか。その点を一つ。","respondent":"白鳥高齢者いきがい課長","answer":"基本的に、こちらの抽選方法につきましては、これまでの大井林町の例のように、審査会を経た中で、公開抽選ということで、このような決め方をさせていただき、入居者の待機者を登録ということになりますので、公開抽選という形を取らせていただけたらと考えています。","voiceIndex":37,"id":"exchange-013"}]},{"id":"topic-03","title":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","agenda":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","exchanges":[{"speaker":"向委員","kind":"確認","question":"２点確認なのですが、高齢者住宅、単身者用１２戸、障害者用２戸、法人寮２戸ということですが、区で借り上げしているのは、このうちの単身者用と障害者用のトータル１４戸ということでいいですか。","respondent":"白鳥高齢者いきがい課長","answer":"契約戸数につきましては、全体で１６戸の契約です。ただし、高齢者住宅としての契約につきましては、単身用１２戸と、障害者用２戸ということで、区として借り上げているのは１４戸です。","voiceIndex":50,"id":"exchange-014"},{"speaker":"向委員","kind":"質問","question":"法人寮２戸の部分の詳細というか、内訳を教えてください。それからもう一つ、三ツ星電器の所在地なのですが、基本的に実質、荏原一丁目にあるということなのですが、こういったときに、貸主の情報として書くとき、本社としての会社の情報を書くものではないかと、ちょっと思ったので、そのあたりのお考えをお願いします。","respondent":"永尾高齢者福祉課長、白鳥高齢者いきがい課長","answer":"法人寮の件につきましては、品川区民間社会福祉施設職員住宅提供事業ということで、高齢者福祉課のほうで、区内の社会福祉法人が設置・運営する障害者・高齢者施設に勤務をする常勤職員に対して貸し付けをしています。ただやはり、法人登記の本社につきましては大田区ですが、今現在、私のほうで、これから契約締結をする中では、荏原のほうと考えているところです。","voiceIndex":52,"id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問","question":"ここにあるとおり、３カ月くらいですよね、カーマトラストはわずかな期間ですよね。その辺で、理由で、貸主の都合により、というだけなのですけれども、この辺は、区としてはもう少し細かい内容をつかんだうえでのほうがいいような気がするのですけれども、その辺は、つかまれていたらもう少し詳しい内容を教えてもらえればと思います。","respondent":"白鳥高齢者いきがい課長","answer":"今回、三ツ星電器との契約の中で、これまで賃貸借契約を結んできておりますけれども、この契約書の内容に、一つ、事前通知というものを設ける予定で、今進めているところです。","voiceIndex":55,"id":"exchange-016"},{"speaker":"たけうち委員","kind":"意見","question":"そうすると、今後は事前通知ということでしたけれども、確かに所有者は民間の方なのですけれども、区が借り上げて高齢者住宅としている以上は、やっぱりその辺、どうしても不動産などは、営業的な部分にさらされてくるところもあると思うので、その辺を事前にある程度ルール化していかないと、今後何か安定しないことが起きるのかなと思いますので、その辺をしっかりお願いしたいということで。","respondent":"白鳥高齢者いきがい課長","answer":"委員ご指摘いただきました今後の高齢者住宅の運営にあたりましては、それぞれの貸主側の事情というものがありますし、区としましても強制できるものではございませんが、やはりそこはこれまでどおり高齢者住宅を運営していく、そういった福祉的要素の高い住宅でもありますから。","voiceIndex":57,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"１点だけですけれども、平成２６年３月３１日、１０年２カ月の賃貸借契約の締結はしたわけですよね。その当時は、カーマトラストと。確認したいのが、平成２６年４月１日から８月３１日まで、その間の家賃はどこに入って、それから、どういう精算をされたかということについては、まだ品川区がタッチしないのですよね。わずか数カ月の間ですけれども、品川区とは契約はしていないわけでしょう。","respondent":"白鳥高齢者いきがい課長","answer":"今回、三ツ星電器になる場合、これから契約締結ということになりますけれども、これからのものにつきましては９月以降ということになりますので、これについては８月２０日ごろまでということでありますけれども、それがかないませんので、８月分、９月分合わせまして。","voiceIndex":59,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"要するに民間の不動産業のようなことが出てくる可能性があるわけです、こういうときに。こういうケースが、これからも当然考えられるわけであって、そのときに、品川区の内部規約なり、それから、品川区としての一定の方向性はあるのですか。それとも、これから検討していくのでしょうか、お聞かせください。","respondent":"白鳥高齢者いきがい課長","answer":"これから、品川区が高齢者住宅を福祉施策の位置づけの中で進めていくためには、今回、個人オーナーから会社のほうへ譲渡されたわけですけれども、こういう事態は今後考えられますし、その辺につきましては、区としましても、入居者にご迷惑がかからないような仕組みづくりなり。","voiceIndex":61,"id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、皆さんからいろいろ質問がありましたけれども、住まれている方、居住者全員、こういう状況はもう知られているのでしょうか。入居者に迷惑がかからないようにとおっしゃっていましたけれども、第三者から見ていても、このようにころころと変わると、あまりいい感じで見られないのですよね、客観的に。居住者の方からの声などは、何か出ているものはないでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"今回のグレースマンションにつきましては、貸主が変更になったということにつきましては、もちろん、グレースマンションの管理人が変わりましたので、そのときには緊急時の連絡先、お困り事の相談ということにつきましては管理人にということで、掲示はしています。","voiceIndex":63,"id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"確かに管理人ではないということですけれども、貸主が変わっていく、では次はどうなってしまうのかと、住んでいると不安にもなっていくかなとも思うのです。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-021"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"昨年の厚生委員会で、体組成のほうはやりました。一つ、資料２と資料３のあまりにも細かさの違いにちょっとびっくりました。そういうものを一つの成果としてＰＲしていくようなことはやられているのかどうか、教えてください。","respondent":"川島健康課長","answer":"先ほど、延べ利用件数が５,４９４件、４,８５３件という説明をさせていただきましたが、平成２５年度でいきますと、実際は、４,８５３件のうちの測定者、何人が測定したかということでいきますと、２,００７人ということで、皆様複数回測定して。","voiceIndex":73,"id":"exchange-022"},{"speaker":"たけうち委員","kind":"意見","question":"そういう真面目に定期的に取り組まれた方が、何カ月後にはこれだけの改善ができたというようなデータは、多分集約すればできるのではないかと思うので、それをどうＰＲするかは、またいろいろあると思うのですけれども、そうすると、一定の効果がこれだけあるということの裏付けとして、そういうデータの管理等をやられたうえで、それを活用するようなことは何か考えているのか。","respondent":"川島健康課長","answer":"すみません、今のお答えの前に、先ほどの骨硬度測定器の話ですが、医療機器であります骨密度測定とはちょっと違いまして、医師が常駐するような施設でないと、骨密度測定はできないということで、簡易な健康機器になってしまうという説明が漏れました、申し訳ございませんでした。","voiceIndex":75,"id":"exchange-023"},{"speaker":"たけうち委員","kind":"意見","question":"後段のほうで、やはりこれから、いろいろな介護予防までいくかどうか、健康づくり等で健康増進していこうということで取り組むのであれば、やっぱりそれはデータとして持っていて、個人情報とかとは別として、全体として健康センターを軸に健康づくりに取り組んでいるとすれば、そこでやっている事業が、こういうことをやることによって、これだけの結果が出ているということは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろん、こういう女性の方々にやるなというわけではなくて、この方々にももちろんやっていただきたいのだけれども、実は、もっと運動をしてほしいような年齢の方々、私たちの年齢の５０歳代、４０歳代前後の男性であるとか、そういう方々向けに特化したようなプログラムはあるでしょうけれども、こういう募集を検討していくなり。","respondent":"川島健康課長","answer":"こちらのほうも、今日の所管事務調査の議題ではございませんが、健康づくりプランの中でも、今までその辺をターゲットにしたことはあまりないかなというところですので、男女問わず働き盛りの方をどうするのかということも踏まえて、健康センターの活用もありますが。","voiceIndex":78,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、もっと入り口のところで、ここをうまく活用することができれば、区民の方々はそういう制度のお世話になる可能性が低くなるわけですから、これはもしかすると大きな視点で考えなければいけないのかもしれないけれども、せっかく健康センターがあって、それに近い事業を展開しているのであるならば、これからできる限り区民の方々が健康で。","respondent":"榎本健康福祉事業部長","answer":"ただし介護になっても、介護予防ができますし、なるべく介護が重度化しないような形での進め方というのはできると思いますので、そういうのを含めながら、総合的にいろいろと工夫を重ねていきたいと思います。","voiceIndex":80,"id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"一つは、延べ利用件数ですけれども、具体的に年間５,４９４件云々とありますけれども、大体年代別の数がわかれば教えてほしいと思います。それから、これは全然違う話なのですけれども、品川健康センターって、上のほうが会場ではないですか。","respondent":"川島健康課長","answer":"例えば、それぞれ企業にとっても、その企業の売り込みだとか、ＰＲになるということで、いろいろな媒体を提供していただいたり、いろいろな支援をしていただくという健康づくりに関する取り組みをしている企業があると思いますので。","voiceIndex":82,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほどチラシの工夫などもありましたけれども、他の委員からもありましたが、モニタリングではないですけれども、一つの例で、ビフォーアフターではないですけれども、こうやるとこうなるというのがわかると、へえっと思えると思うので、そういった工夫をして、さらにこういったものに参加してもらうとか、今、参加できていない方々に対してのアプローチは、どう考えていらっしゃるのでしょうか。","respondent":"川島健康課長","answer":"こちらのＢｏｃａにつきましては、メカの話ですが、全国のスポーツジムの１０％くらいには置いてあるということだそうですが、まだそんなに普及しているわけではなくて、品川区内ですと、もう１カ所スポーツジムにある、だから２台あるだけという現状だそうですので。","voiceIndex":84,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やっぱり人は、自分の体を知っていくというのはすごく大事だと思うのです。健康センターではないところでも、ほかでもいろいろ保健指導、健康指導などをされていると思うのですけれども、そういったところで、自分の体を知ったうえで、こういうことが必要だと、それで、健康センターでもこういうことをやっているというのは、ほかの事業の場で、健康センターのＰＲなどはされたりしていないのですか。","respondent":"川島健康課長","answer":"健康センターをもっと使っていただくというような形で、直接的な周知みたいなことは、今まで行っていないのですが、これからもっともっと健康づくりにこの健康センターを使っていただくためには、もう少し工夫して、こういったいいものがあるのだということを。","voiceIndex":86,"id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、１枚目の裏のところの運動指導士というのはどういう資格ですか。管理栄養士は国家資格ですけれども、運動指導士というのはあまり聞いたことがない資格なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-030"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"テレビや新聞のニュースで、ちょっと日にちは忘れたのですけれども、区内、都内でも何人か熱中症でお亡くなりになったという中で、品川区でも１名という報道があったのです。今、東京都から情報が来るということなのですけれども、亡くなられたとか、そういう情報もつかんでいらっしゃるということですか。","respondent":"高山品川区保健所生活衛生課長","answer":"現状、先ほど申し上げました８０名の中には、幸いにして初診時で死亡という方はいらっしゃらなかったのですが、入院を要する方が３７名ということで、この８０名の中で大体４６％ほどの方がいたということで、軽症でそのままお帰りになった方が４３名、５３％くらいということで。","voiceIndex":97,"id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"おぴったと、健康男子プロジェクトと、あつべつ箱ものプロジェクトと、それからともにアート・ギャラリーというのは、それぞれこういう特色があって、こういうことを中心に視察したほうがいいのではないかというのは一つのまとまりというか、自分なりにまとめはできるのですけれども、最後の千歳市こども通園センターというのは、これは一体何が特徴で、どういう点が非常に。","respondent":"榎本健康福祉事業部長","answer":"縦横というのは、国全体の中で言っているものなのですけれども、その中にどういうふうに位置づけるかという形で、ここはこども通園センターなので、就学前の子どもの部分なのですが。","voiceIndex":106,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問・要望","question":"当然出てくると思うのですけれども、企業とどのように連携しているのかという部分のご説明を、当日、要望したいということ。それから、最後ですけれども、障害者のともにアート・ギャラリー、いただいた資料とか、いろいろパソコンで見ている限りでも、市というか、行政がどれくらいこれに対しての距離感というのですか、バックアップしているのか、もしくは、まだそこまでは、ということなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"意見","question":"私は小児科なので、出ていないのでわからないのですけれども、最近、時々といいますか、定期的にやるような動きがあるのですよね。","respondent":"榎本健康福祉事業部長","answer":"何回かやってきて、顔が少しずつ見えるようにはなっているのですが、それでもまだまだ電話一本で事が進むという話にはならないので、そういう連携名簿みたいなものをつくったりとか、情報をどういうふうに共有しようかというところも検討していかなければいけないところです。","voiceIndex":113,"id":"exchange-034"},{"speaker":"向委員","kind":"意見","question":"この資料の３ページに、心筋梗塞で死亡した人数が出ているのですけれども、救急医療の体制とか、例えば季節的に、旭川市は冬はすごく寒くて、雪も多いところなので、いざというときに、都内だと割と救急車もすぐにきてくれますが、そこまでになると、もうやっぱり救急搬送にすごく時間がかかる傾向があるのかどうか、ちょっとそのあたりを、都内の環境と見比べてみたいという思いがあるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":46361,"voices":118}},{"id":"h26-20140825-8","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"建設委員会","time":"午後１時００分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、区民住宅（あき家）入居予定者登録募集","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今、ファミーユの三つを合わせて６３０戸ということなんですが、大体年間にあく部屋がどのぐらいあるのか教えていただきたいのと、結局あきがあった場合に順次、抽選の順番からということですけれども、この９月に登録募集をして、今後、抽選に当たった方、登録された方がどういう手続をするのか教えてください。","respondent":"矢木住宅担当課長","answer":"あき家の数ということですが、これはなかなかどの時点でというふうに切らないと、出られたり入られたりするので難しいところなんですが、直近で押さえている数字といたしましては、８月２１日現在で１５戸ほどとなっています。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"品川区空き家等実態調査中間報告","agenda":"品川区空き家等実態調査中間報告","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"最初にいただいた条例案制定までの作業スケジュールにのっとって、本委員会への報告、ありがとうあります。拝見させていただいて、幾つかお尋ねしたいところがあります。それと、品川区における空き家数の推移とありますけれども、住宅増加率以上に空き家戸数が年々増加しているという理由について、世間一般にいろいろな理由が言われていますけれども、ここのところの分析を教えてください。","respondent":"矢木住宅担当課長","answer":"空き家の定義ですが、なかなか、何カ月以上誰も住んでいなかったら空き家なのかというのはすごく難しい問題でございまして、少なくとも国の法案に沿って居住その他の使用がなされていないことが常態である建築物は、広く空き家と考えて調査をしていく趣旨です。","voiceIndex":14,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"それで、条例案についてはまた後で聞きたいと思うんですけれども、ちょっと踏み込んで、途中で申しわけないんですが、条例案のほうのスケジュールのことについても伺いたいんですが、５月に庁内各課への意見照会を行って、７月に２回、関係各課との検討会というのが行われていると思いますけれども、まず「ふれあい」という庁内雑誌を見たりすると……、ごめんなさい。","respondent":"矢木住宅担当課長","answer":"ただし、今回中間報告をまとめるという中で、いろいろ議論はあったんですが、なかなか、いろいろな状況が想定されて、もしかしたらトラブルになるかもしれないというような状況があったので、まず空き家のほうを先行させていただいて、ある程度調査の手法ですとか。","voiceIndex":16,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"「ふれあい」という庁内雑誌の中では、ごみ屋敷について地域活動課が出動しました、チームが発動しましたというような記事を拝見させていただいたんですけれども、今、どこと調整をされていらっしゃるのか、例えば町会からの要望の中に、高齢者の居場所づくりなどにつながるというような利活用のご提案も既にされているところがありますけれども、この辺について。","respondent":"矢木住宅担当課長","answer":"庁内での組織の構成メンバーということで理解しますと、まず当然のことながら地域活動課、品川区保健所、高齢者福祉課、あとは私ども都市環境事業部の建築課、環境課、私どもという、おおよそ空き家対策およびいわゆるごみ屋敷の両方に今後関係してくると想定されるところは。","voiceIndex":18,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"今、福祉関係も入っているということでしたけれども、確認ですが、障害者福祉課は入っているのかということと、あと今後調査をして、条例をつくって、今回の条例案の骨子の中には利活用というのが条例案に入っているんですけれども、例えば福祉部門等の考え方も必要になっていると思うんですが、まずはこういう調査をして、こういう利活用ができますよというところを住宅担当のほうで。","respondent":"矢木住宅担当課長","answer":"なぜかというと、高齢者福祉課が庶務担当課になりますので、そこを含めて大きな枠で検討した後に、当然のことながら個々の事象に応じて、プロジェクトチームと申しましょうか、実際に問題の解決をしていくためには……、まことに申しわけありません。","voiceIndex":20,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"高齢者福祉課が庶務担当課であるということで、福祉の視点はもちろん入っているということは理解いたしました。最後なんですけれども、法案の関係で国のほうの動きも注視されていると思うんですが、いわゆる品川区の考え方としては、この法案に先行させて条例案を上程していくという考えなのか、それともその対応をどういうふうに見られているのか、最後にお聞きしたいと思います。","respondent":"矢木住宅担当課長","answer":"品川区といたしましては、前回答弁申し上げたように法案の成立を注視しながら、さりとて法案がいつできるかというのが確実視できない中では、慎重に時期等を見きわめながら成立に向けて準備をしています。","voiceIndex":22,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。非常に難しい、多分各自治体が悩ましいところであると思いますので、よろしくお願いいたします。今回、行政視察もありますけれども、しっかり我々も勉強して、いろいろ情報交換をしながら、よいものをつくっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"大沢委員","kind":"意見","question":"今の課長のご答弁の中で、国の流れの中で時期等を見きわめながらということですけれども、実際に空き家というのはもうずっと前から発生しているわけでありまして、とりわけ密集した中の空き家というのは危険性をはらんでいるわけで、このところで法律の流れ、条例の流れを見てもやはりその時間のいとまを考えることではなくて、すぐに対処すべき問題だとこれは思うんですけれども。","respondent":"矢木住宅担当課長","answer":"その件につきましては、条例の成立以外に現段階で現行法上取り組むことは、先ほど申し上げた各課から構成されたチームで実際に動いてあります。条例案につきましても、法律が制定されないからそこまで待つというような方向性ではございません。","voiceIndex":25,"id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"空き家自体が管理不全ということで周辺の環境に影響が懸念されると、やはり区民の懸念されている事項を取り除くのが役所の役割だと思うんですけれども、今おっしゃっていたように決まり、法律、条例の流れの中でやっていたら、そこのところの懸念されるものがすぐに対処できないようなおそれもあると思うんですけれども、あくまでも私有の財産なのでいじりづらいことはわかるんですけれども。","respondent":"藤田都市環境事業部長","answer":"例えば、空き家あるいはごみ屋敷の中で、ごみを片づけさえすればそれで解決するのかというと、必ずしもそういうことではなく、そこにお住まいの方々をいろいろな形でケアすることが最終的な解決になるというふうに考えてありますので、そういった意識は常に持ちながら、今。","voiceIndex":27,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、部長がおっしゃったように区が横断的に対処していただいているということなんですけれど、ちょっとここのところを見て、来春ですか、３月に最終報告が出るということなんですけれども、先ほど問題解決というお話も出てきたんですけれども、最終的に利活用を含めてということで課長からもご答弁があったんですけれども、ここのところの落としどころ、空き家をどのようにしたいのか。","respondent":"藤田都市環境事業部長","answer":"ただ、そうはいってもなかなかそういう形にならない、地域の方々で何か活用してくれないかということであれば、利用をするというような形の検討も一つあるかと思ってあります。","voiceIndex":29,"id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"ですから区の行政としてどこまで、今の段階で結構なのでどこまでをというふうにお考えになっているか、まずお聞きしたいと思います。","respondent":"矢木住宅担当課長","answer":"利活用のほうですが、やはりご存じのとおり私どもで所有者を探して、その方にいかがでしょうかと、今後どうなさいますかということをお聞きして、もし仮に利活用したいということであれば何らかの組織体、それは先ほど委員がおっしゃったような視点で、私ども内部だけではなく。","voiceIndex":31,"id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"私は大沢委員と同じように条例化が先なのではないかという見解を持っているんですけれども、あくまでももう一歩踏み込んで、先ほどモーゲージ、抵当権の話も出ましたけれども、信託不動産とか品川区は進んでいますけれども、ちょっと意味合いというか活用が、今までこの件とは違うような展開で使われているケースが非常に多いので、もう一回確認させていただきたいんですけれども。","respondent":"矢木住宅担当課長、藤田都市環境事業部長","answer":"残念ながら、固定資産税につきましては都税事務所のほうの管轄になりますので、直接どうこうという検討ではございませんが、当然のことながらできる協力はするということで、都税事務所のほうの所管の課長とも話をしております。ちょっと補足しますが、国のほうでは、逆に適正な管理がなされていない住宅については、税の優遇的な措置をやめてしまうことを検討しているというようなことも聞いてありますので、その辺の策と合わせながら。","voiceIndex":33,"id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"品川区の中でもやはり、本当の意味での所有権が戦後において確定していないような部分、すごくグレーな部分がある物件というか、民間のものもあるようなこともちらほらとお聞きしますので、全体的に整理をしたときもう一度、先ほどの委託をかけているというところと区自体で行うところ、課長のご説明でも区自体でいずれグループというかチーム。","respondent":"矢木住宅担当課長","answer":"区自体でどこまでやっていくのかという問題、これは所管もいろいろございまして、入り口も多々ある中で、ただ、どこが聞かれても同じように対応ができるようにという横断的な組織をつくりつつあるところです。","voiceIndex":36,"id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"とにかく早いうちに、早い時期に条例化を進めていただきたいというお願いと、もう一つは、やはりこれは意外と、すごく細かく苦労がある、これが行政なんだよという、やることなのかもわかりませんけれども、一つずつ丁寧に積み上げていかないと、本当に全部一つずつ違っていると思いますので、その辺をお願いしておきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"初めのほうから、基本的なことをお伺いしたいんですが、１ページ目のところの「品川区においては住宅総数」、これは総務省の住宅・土地統計調査による数だと思うんですが、この数というのは一戸建てはもちろんそうなんですが、共同住宅というのは、戸数を合わせて全部はめ込んで出ている数字なのか、そこが一つと、その下の行の「区市町村の人口規模に応じ一定割合で抽出されたものであるため」という。","respondent":"矢木住宅担当課長","answer":"三つご質問をいただいたと思います。一つ目の２万４,８９０戸が空き家というのは、委員ご指摘のとおりでございまして、マンションの空き戸数も含めたものです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"マンションがどんどん建っているので、マンションの空室率が高いのか。その辺の分析があったら、推移的に一戸建ても増えているのかどうかというところがわかったら教えてください。","respondent":"矢木住宅担当課長","answer":"空き家数の推移ですが、共同住宅のほうもやはり空き家率は、全体からいきますと微増しているのかなという感じなんですが、一軒家のほうが大幅に空き家が増えていると、そういう状況です。","voiceIndex":41,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後のところに未提出、先ほど４４町会はまだ出ていないと受けとめたんですけれども、５ページのところでカーネル関数というので図が出ていまして、一番後ろのところに今後重点調査で緑の点線が入っていますけれど、この辺は調査が入っていないところがこの辺だったという捉え方でいいのか、まだ出ていなくてやっていないところが。","respondent":"矢木住宅担当課長","answer":"ちょっとスケジュール的な関係でなかなかパブリックコメント等までいけるかどうか、ちょっと難しいところがあると思うんですが、できるだけ皆様のご意見、ご要望を反映して制度全体を、条例のみならず規則等でつくってまいりたいと思いますので、よろしくお願いいたします。","voiceIndex":43,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどのほかの方のご質疑の中で、地域への支援のチームもできているし、なかなかいろいろ困難な問題を抱えているので、いろいろなところでかかわってくださっていると思うので、実働的な部分はもう既に、難しくてもやられているというところを踏まえると、条例は枠組みということですけれど、そんなに急いで、並行はしていてもいいですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-018"}]},{"id":"topic-03","title":"の東品川四丁目地区のまちづくり","agenda":"の東品川四丁目地区のまちづくり","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"確認なんですけれど、現状ってここはサッカー場みたいなものができているところだったと思うんですが、これを運営しているのが、今の事業者がそれまではそういう形にして、この案件とは直接関係ないかもしれませんが、そういう認識でよろしいですか。","respondent":"溝口都市開発課長","answer":"現在、Ｃ街区につきましてはサッカー場と時間貸しの駐車場になっていると思います。こちらにつきましてはあくまでも暫定利用ということで、事業者３社が共同で実施しているです。","voiceIndex":51,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この街区の中身があまりよくわからなくて、過去の建設委員会も検索したんですがなかなか出てこなくて、最後にこの報告をしたのがいつだったのかということと、あと、まだ残っているところがＤ地区で幾つか残っているのですか。ここは共同住宅で８２０戸となっていますけれども、ここの地域全体で住宅がどのぐらい増えたのか、増えるのかを教えてください。","respondent":"溝口都市開発課長","answer":"ここが平成２２年６月に地区計画の変更をしているのが一番最新になりますが、このときにあわせての報告が多分一番最後、直近の委員会等での報告になると思います。","voiceIndex":53,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということは、住宅等はＵＲのその賃貸の２棟と、今回の８２０戸、ほかはオフィスとか営業関係、ホテルもありますけれどもそういう状況なのか、ちょっとその辺の全体がどういう地域なのかを教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"従前、準工業地域の指定になっているものを商業に変えて、容積率の最高限度としては地区計画のまだ現在の段階で、今後説明会等で詳しく説明するようになりますが、５９０％まで容積率を上げる形で、今、検討しています。","voiceIndex":55,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"当初、ここは何か民間の事業で、補助金は入らないみたいなことを前に聞いたような気がするんですけれども、実際、公開空地とバーターでということとか、あと保育所が入っていますよね、これはどういう保育所かちょっとわからないですけれど、この辺で補助金が入っているということでしょうか。もしそうだったら、どのぐらい入る見込みなのかも教えていただきたい。","respondent":"溝口都市開発課長","answer":"保育施設につきましては、今後所管と十分調整しながらどういった形のものをつくっていくのかというのを検討していきますので、今の段階で認可保育所をつくることで補助が入るとか、そういったものがどういう形になるかというのは。","voiceIndex":57,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"航空制限で１００メートルぐらいなんですか。６０メートル以上を高層建築物と言っていますけれども、品川区はトータルで今、高層建築は何棟になったのかというのと、こういった建物の耐用年数、どのぐらいもつのかというのと、将来的なことをどう考えているのかもあわせて教えてください。こういう建物がいっぱい建つことについて。","respondent":"溝口都市開発課長","answer":"当地区につきましても、冒頭説明したとおり品川シーサイド駅の開業に合わせて、その駅にふさわしい植樹、バランスのとれたまちづくりを進めていくという計画に基づいて、これまで進められてきた地区、イオン等はできておりますが、やっとＣ街区においても地域にふさわしい形。","voiceIndex":59,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会の開催ということですけれども、(3)対象区域で、２倍の範囲というのはいつもそうなんですが、「および地区計画区域内」の対象というのはどこなのか教えていただきたいのと、この説明会の周知は既にどういうふうにされていたのか、教えてください。","respondent":"溝口都市開発課長","answer":"周知につきましては、基本的に２Ｈの範囲についてはポスティング、また地区内につきましてはそれぞれ代表者、特にＵＲとかおりますので、そういったところには直接訪問して、今回の説明会を、また地区内にＵＲの賃貸マンションがありますので。","voiceIndex":61,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと聞き漏らしてしまいましたが、地区計画区域内というのは、この地図で言うとどこなんですか。Ａ街区の真ん中ぐらいまでと言っていましたが。","respondent":"溝口都市開発課長","answer":"ただ、北側のほう、Ａ３の資料の位置図をごらんいただきたいんですが、上のほうになりますとＡ街区の真ん中ぐらいまでが２Ｈの範囲になりますので、本来であれば２Ｈの範囲外になるんですが、これまでのまちづくりの経緯がありますので。","voiceIndex":63,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は本当に、特に問われている問題だと思うんですね。地域からそういうことをどんどん声を出していかなくてはいけないと思っているんですが、その大きなところでの捉え方でぜひ研究していっていただきたいんですけれども、いかがでしょうか。","respondent":"藤田都市環境事業部長","answer":"この間のいろいろな調査の中では、ＣＯ２で考えると、先進国が排出する量が約４割程度、次に今頑張っていろいろまちづくりを進めているような国が６割ぐらいのＣＯ２の排出をするというふうに、ある報告ではされております。","voiceIndex":65,"id":"exchange-026"}]},{"id":"topic-04","title":"の中延駅放置禁止区域の変更","agenda":"の中延駅放置禁止区域の変更","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今朝もこの地区を通って見てきたんですけれども、この赤い地域は本当に、あれは通勤ですかね、どういう方が置いていらしたかわからないですが、とても狭くて、車が通って、人が東急と地下鉄と両方の人でかなり混み合う地域で、ばらばらに置かれているという感じでとても危険なので、放置禁止区域に指定するのは本当にいいことだと思うんですけれども、これは禁止区域を広げていくことで解決するのでしょうか。","respondent":"田口交通安全担当課長","answer":"この辺も、ＴＳＵＴＡＹＡ等と連絡を図りながら、啓発活動を行っていきたいと考えております。","voiceIndex":72,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろお話をしてくださっているということにおいては、駐輪場の利用台数が８割ということで、置き方にもよるし、やはり通勤というよりも駅周辺の利用の仕方、ＴＳＵＴＡＹＡの利用の仕方とかもかなりかかわっていると思うので、ぜひＴＳＵＴＡＹＡには、誘導員を置くと地域の方に約束をしたということなので、ぜひ実施して、ソフト面でやれるところもしっかりやっていただきたいし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"}]},{"id":"topic-05","title":"の品川区災害対策基本条例概要版","agenda":"の品川区災害対策基本条例概要版","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意見をぜひ真摯に受けとめて、改善すべきところはどんどんいいものに変えていっていただきたいと思うのが一点です。地域の皆さんや個人がするのを、運営の補助など支援を行いますというところと、中のページの区のところでは予防対策のところの公助、「都市基盤の整備等災害に強い総合的なまちづくりの推進」、この１行半しかないんですよね。２点です。","respondent":"鈴木防災課長","answer":"ただし区民の皆さんに取り組んでいただける対策というのは、災害を防ぐ部分ではなくて減少させるということで、この挨拶文では減少のほうの説明をさせていただいているものです。","voiceIndex":80,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"今の配布の状況からすると、全体でどのぐらいつくるんですか。全戸ではないんですよね。私、何となくこちらと一緒かなと思っていたので、その規模かなと思ったんですけれど、何部つくるのか教えてください。","respondent":"鈴木防災課長","answer":"それでマンションの管理組合の防災対策等の検討交流会のような場で活用してまいりましたが、最近お問い合わせが増えてきたことから、少し地区の訓練であったり、そういうマンションの管理組合の会合等で配っていただけるようにということで、今回２万部ほど増刷を検討中ですので。","voiceIndex":82,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひ、あまり特定のところを通してというよりも、せっかく条例ですから、区の基本姿勢を示すというあたりでは、この防災地図と同じぐらいに配布してもよろしいのではないかと思うのと、あとちょっと地図を広げてしまったので、浸水ハザードマップのところに土砂災害危険箇所というのが出ていて、ちょっと見たんですが、品川区も幾つか危険箇所があるんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"ごめんなさい、広げちゃったら目に入ってしまったものですから。","respondent":"鈴木防災課長","answer":"このハザードマップですが、基本になりますのは東京都のほうでつくったハザードマップに、区のほうで新しい情報を追加してこの１枚の地図にしたというものです。この危険区域の場所につきましても、新しい情報が出たものを追加して載せたものです。","voiceIndex":86,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、広島の被災地の方々の映像を見ていると、ハザードマップは聞いたことはあるけれども、自分の住んでいる地域がその区域内であったというのを知らなかったという方が結構いらしたという意味においては、自分の住んでいるところ、個人の財産を守るという意味でも必要ですけれども、新しい情報ということで伝わっていると思うんですが、いろいろな機会で周知をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけです。もうちょっと激しい感じのデザインであれば、もっと入りやすいのかなという考えも一つあると思うんですけれど、かなり優しい感じのデザインになっている、このコンセプトをちょっと教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"ただ、やはり区民の方にまずは手に取って見ていただくこと、それから、ただ災害を恐れるのではなくて、恐れることはもう十分皆さんいろいろな情報を得てご存じですので、その中でただ怖がるのではなくて、落ち着いてしっかりとした取り組みをするというところで。","voiceIndex":89,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"一定の理解はしますが、この葉っぱは何をイメージしたんでしょうか。","respondent":"鈴木防災課長","answer":"これは、ご覧いただきますように若い色の葉っぱですので、これから成長したり、命の象徴というイメージというところでございまして、特別な意味を持ったものではございません。","voiceIndex":91,"id":"exchange-035"}]},{"id":"topic-06","title":"の平成２６年度地区総合防災訓練","agenda":"の平成２６年度地区総合防災訓練","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"下の米印のところに「児童センターが地区総合防災訓練に参加する予定」とありますけれども、ほかの部署の方々で参加をされるところはないんでしょうか。この児童センターだけなんでしょうか。","respondent":"加藤防災安全担当課長","answer":"大使館や領事館あるいは広報誌等を通じてお声がけはしているんですけれども、外国人の住まわれている地区もある程度、多くの方が住まわれているのは、大崎とか品川、大井という認識ではありますけれども。","voiceIndex":98,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"児童センターは、職員でなくて子どもたちを呼ぶということですか。協議会の中での話し合いで決まったと、この児童センターは全地域ですか。そこが一つ。協議会のところでいろいろ毎回検討されて、実施をされているわけですけれども、いろいろなご意見が上がってくると思うんですね。特に各地域で共通した問題点とか出たとき、上がってきたご意見をどう具体化されていくのか、その点を教えてください。","respondent":"加藤防災安全担当課長","answer":"あるいはまた各地区の協力が必要であれば、またその動きの中で対応していくというような状況です。","voiceIndex":100,"id":"exchange-037"}]},{"id":"topic-07","title":"では、行政視察","agenda":"では、行政視察","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"思いつきで申しわけないんですけれども、名古屋市の空き家の条例ですけれども、品川区ではいわゆるごみ屋敷も条例案の中に含んでいくというようなお考えがあるということなので、もし先方に前もってお伝えするとすれば、そこの考え方をどういうふうにされたのかというところを、入れていないと思うんですけれども、それともどこかで包含しているのかとか、それとも別にごみの条例を考えているとか。","respondent":"松代防災まちづくり事業部長","answer":"以前、職員の政策課題研修等で、やはり少し課題が出されました。そういうところをちょっと項目的にピックアップしまして、事務局を通してあらかじめ、このようなことで質問にお答えいただければというようなことも、効率的な説明になるのかなと思うんですが、いかがでしょうか。","voiceIndex":110,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":37283,"voices":112}},{"id":"h26-20140825-9","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"文教委員会","time":"午後１時００分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２７年度品川区立小・中学校使用教科用図書の採択","agenda":"の平成２７年度品川区立小・中学校使用教科用図書の採択","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"新聞報道なのですけれども、高校の部分なのですけれども、神奈川県で県立の高校教科書の採択において、校長のほうからそれぞれの学校でいろいろ発言があって、複数の学校の教諭が校長の指示で覆されたと、そういう記事があったのですけれども、こういう状況についての教育委員会の見解というのはどういうことか教えていただきたいと思っています。","respondent":"渋谷指導課長","answer":"他県の状況はよく把握しておりませんけれども、品川区の採択の状況、今ご説明しました方法では、そういった形の恣意的なことは関与する余地はございませんので、全くそれについてはコメントを差し控えさせていただきたいと思います。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"品川区がないというのは今の説明の中でもわかりましたし、あったら大変なことだと思っていますし、これからもないように、研究会と検討会でのそれぞれの調査研究を尊重するというふうにして、そういうベースを大事にしていただきたいと思っているのですけれども、他県のことだからといってコメントをしないというのではなくて、一般論として、採択制度のあり方で。","respondent":"田村教育次長","answer":"地教行法上、校長に権限があるわけではないので、教育委員に、委員の中で教科書採択を決めると教育委員会の専権事項になっていますので、だから、私も今、南委員のおっしゃった学校長が教員に何かと、学校長に権限が下りているわけでは全くないので、学校が決めるわけでも。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"教科書採択は子どもたちの教育の重要な教本ということで、そして、こういう教科書採択制度になったのは、いろいろな意味があってつくられたことだと考えていますし、また一方で、いろいろな流れがある中で、やっぱりきちんと採択制度を守っていくというか、そして子どもの将来にわたって平和な国際関係をつくる、国際的な立場からも、そういう教育をするという確度での教育が大事だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。先ほど、ご説明の中で検討委員会といいますか、地域の方も含めたところでいろいろ検討されるというお話があったのですが、その人選は基本的にどういう流れで行われるものなのですか。","respondent":"渋谷指導課長","answer":"ＰＴＡ等地域の方については、ＰＴＡ連合会の会長であるとか、そういった方をお願いしていると。ただ、細かい中身については、８月末まで時限秘ですので、そちらについてはご説明は差し控えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"高橋委員","kind":"質問","question":"そこでの委員のほうからの質問とか、客観的な研究と選定委員会のほうでお話しされたということを認識していますので、そこでの変わることについての議論というか、そういうものがどんな形であったのかということを、もしこの段階でお話しすることができるならば伺いたいと思います。","respondent":"渋谷指導課長","answer":"今ご説明申し上げたとおり、教育委員会、採択に関しては８月末まで時限秘になっておりますので、審議の内容等々につきましては、９月になってから教育委員会のホームページのほうでアップロードしますので、そちらをご確認いただければと思います。","voiceIndex":14,"id":"exchange-005"}]},{"id":"topic-02","title":"の全国学力・学習状況調査の結果の取り扱い","agenda":"の全国学力・学習状況調査の結果の取り扱い","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。品川区のところで、教科の国語から理科までずらっと出ていますけれども、いわゆる英語、外国語の教科によって、東京都でのテストの中では外国語、中学２年生が行われているのですが、この辺は、品川区は小学校からいろいろ英語に力を入れていただいてやられているので、その辺の考えというのは教育委員会としてどういうふうに思っているのか教えてください。","respondent":"渋谷指導課長","answer":"そんな課題を踏まえて、今年度から全９年生を対象に、話す、聞く、読む、書くの４技能全てを見ることができる調査、ＧＴＥＣというものを導入して実施するという形で取り組むような形をとらせていただきます。","voiceIndex":20,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"指導というのは、だから、７年生の結果を受けてですから、５年生と６年生の時期に何をどういうふうにすれば身につくかという、そういう具体的な内容とプロセスをどうしようかということなのだろうというふうに理解するのですけれども、そういう検討した、あるいは指導しているその結果、日常の教育活動あるいは子どもたちの学力の定着、そういうものについて一定の効果が出ているという。","respondent":"渋谷指導課長","answer":"２点目につきましては、すみません、説明が十分でなかったようですが、２月末に実施した調査については、５月に４年生部分の分析をして、４年生部分の改善策等々の態度表明を行うということが第一弾として行っているです。","voiceIndex":23,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"国がやっていることで十分その目的は果たせていけると思っているのですけれども、まさかそういう事実は、調査しない中で言っていることをお許しいただきながら、ないということは大前提にしたいと思っているのですけれども、その辺の見解、それから子どもに及ぼす影響、そして先生方の多忙を解消することに、解消しなくてはいけない状況なのだけれども。","respondent":"渋谷指導課長","answer":"４年生という実施時期についてですが、品川区、当初は６年生、一番最初は中学校１年生にやっておりまして、その次は６年生で実施をして、小中一貫教育が始まって、４年生、７年生の実施というふうな変遷をしてきております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"大事なことは、子どもに負担をかけないで、学ぶことが楽しいと思っていただけるような、そういう教育のあり方を本当に教育委員会としては追求していただきたいと思っているので、繰り返し質問し、同じような答弁なので、これ以上は言いませんけれども、そこのところはしっかりと大事にしていただきたいということをお願いにとどめておきたいと思いますけれども、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その前提で伺いますが、まず、３番目の結果の公表、これは学校別等が全国的には話題になる中で、自分自身、あるいは我が会派でも、結論には当然意見としてはありません。その辺の難しさ、あるいは現状、校長先生はじめ学校それぞれ評価を求められることは多いと思うのです。その辺は地域性というものは教育委員会がどう考慮していたり、考えているのかをまず１点伺いたいと思います。","respondent":"渋谷指導課長","answer":"先ほども申し上げたとおり、そもそもこの学力調査は、子どもがどんな学びがきちんとできているかどうかですので、それぞれの地域、その実態に応じてきちんと学力の定着状況に応じた対応をしていくということが大事ですので。","voiceIndex":28,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"地域性はそういうことで、今、最後の個人内評価のところ、これは現状のことを伺いたいのですが、まさしく個人という名のとおり、家庭にどう伝えるかというところで、恐らくいろいろな面談等の方法論はあるかと思います。これは現状、数値になってしまうのか、背景も含めてなのか、現状どうなっているのか、あるいは、今後これを生かす余地があるかどうか、ちょっと関心があるので伺えればと思いました。","respondent":"渋谷指導課長","answer":"その部分については、基本的には所見等で、数字にあらわすのではなくて、しっかり検出をして、いいところを見つけて、子どものよさ、伸びた部分についてきちんと評価をして、達成感、成就感をしっかりと確認して、次の学習の学びの意欲につなげていこう。","voiceIndex":30,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"総論的になってしまうのですが、今、個別のものは、今年度といいますか、現状ではこうだと、そこも検討の余地は、僕も含めて十分あると思っています。いかし方のところで、特色ある学校づくりの中で、今、さまざまな学校の発信があるかと思います。ここまでは打ち出していい、ここまでは控えたほうがいいとか、表現の仕方も含めて、その辺、現状どうなっているのか教えてください。","respondent":"渋谷指導課長","answer":"基本的には、国の学習指導要領、それから品川区の小中一貫教育要領は、最低基準という考え方ですので、その最低基準の部分をしっかり押さえていただくというところを前提に、プラスアルファいくつか積み上げたりとか、どうするとか、その工夫については、各学校。","voiceIndex":32,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問","question":"最低ラインのところはわかりました。例えば、ある学校はそれを売りにしたい、特色にしたいとあったときも含めて、現状そういう傾向だとか、あるいは、具体的にそれを発信している学校はあるのかどうか。それに対して教育委員会は推奨する立場なのかどうか、その辺を伺おうと思いました。","respondent":"渋谷指導課長","answer":"学力だからいいとか悪いとかということではなく、学校がその実情に応じて、この部分を特色として打ち出したいとかということについては、基本的にプラン２１の予算等々で教育委員会としては応援していくです。","voiceIndex":34,"id":"exchange-013"}]},{"id":"topic-03","title":"のビーチバレー体験ワークショップの実施","agenda":"のビーチバレー体験ワークショップの実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この小学生１００組なのですが、学年はビーチバレーなので高学年かなと思うのですけれども、何年生ということが書いていなかったので、学年、何年生でもいいのかどうかも含めて教えていただきたいのと、中学生のボランティアというのは、人数はどのくらいの方々を考えているのかということと、それから、多目的広場の芝生の上でということだったので、ちょっとそれはいいです。","respondent":"伊崎子育て支援課長","answer":"中学生のボランティアは、こちらが小さいコートを８面ほど張る予定ですので、そのコートに何人か、数人つけるような形でと考えておりまして、２０名から３０名来ていただけるとうれしいなと思っているところです。予算額につきましては、申しわけございません。","voiceIndex":40,"id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問","question":"説明の中で中学生のボランティアをバレーボールの経験者というようなお話があったのですが、バレーボールを経験しないと、このボランティアは参加できないのかということを１点、まず教えてください。","respondent":"伊崎子育て支援課長","answer":"こちらは中学生の方のボランティアとしましては、小学生のバレーボールの補助とか、あと、審判ということで考えていますので、中学生の方はバレーボール経験者がこちらとしては望ましいということでお願いをしています。","voiceIndex":42,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問","question":"確かに小学生のバレーボールの補助となると、ある程度、知識がなければできないけれども、例えば、周りの整列とかをさせるとかという部分に関しては、それは知識がなくてもできることであるので、告知がどのようにされるのか、小学生の参加のほうの告知はここにあるのですけれども、ボランティアの告知というのは一切ないので。","respondent":"伊崎子育て支援課長","answer":"その方たちの集まり具合にもよりますが、通常、児童センター事業でも中学生ボランティア、中・高生のボランティアという形でご参加していただいている方もいらっしゃいますので、そういう方からのボランティアの希望がございましたら、それは役割を限定することにはなりますが。","voiceIndex":44,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"やっぱりそうですよね。その辺はどうでしょうか。","respondent":"伊崎子育て支援課長","answer":"当体験ワークショップを検討するに当たりましては、バレーボールとビーチバレーの違いというところに着目いたしまして、砂の上で、もともとはビーチですけれども、砂場で行うということが１つの要素であるというふうには考えました。","voiceIndex":48,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"すると、恐らくこれを見ていると、児童センターの主導で企画がされていると思いますが、まずそもそもビーチバレーの普及という中では、全国での選手登録が、ビーチバレー自体はたしか少し前までかなり少ない数百人、実際はバレーボールとの関係、ビーチバレー自体は、たしか全国の選手登録が正式には８００人だと。ボールはどういうふうなことを、当日、区分があるのかどうか教えてください。","respondent":"伊崎子育て支援課長","answer":"申しわけございませんが、私、子育て支援という視点での捉え方からお答えをするというところで、十分スポーツ連盟との関係にはお答えできないかと考えております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"渡辺委員","kind":"意見","question":"そうすると、バレーボールにつながるように、ソフトバレーは最近また高齢者のスポーツの中でも格段に普及していますので、いろいろな窓口につながるかなという思いがありましたので、今年を契機に、今後も子育て支援の枠組み以外でも、これをやったノウハウというのはどの部署にもつながっていくかと思うのでやられるべきだと思いますが、何かご意見を承れればと思います。","respondent":"伊崎子育て支援課長、金子子ども未来事業部長","answer":"今回のビーチバレーボールワークショップは、ワークショップとしては大きな初めての試みですので、これを実施の結果を見まして、オリンピック・パラリンピックの担当と、あるいは、スポーツ担当の主幹課のほうには報告をし。ビーチバレーというものを、当然、区内でこの競技が行われるわけですけれども、いかに区民の、特に小・中学生に普及していくか、啓発していくかというような観点から、今回、ワークショップを実施していくものです。","voiceIndex":52,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"いろいろ質疑を伺っていたら、ちょっと疑問に思ったのですけれども、一番最初の説明では、会場のところには、人工芝で靴を履いてやるということだったのですが、私はそれを聞いたときに、なぜ砂ではないのか、足元が小学生ですから危ないから砂を用いないで人工芝上を靴を履いてということなのかなと思ったのですが、ボールもやわらかいソフトバレーボールを使うということもあるのですけれども、そうなると。","respondent":"伊崎子育て支援課長","answer":"先ほどもご説明をいたしましたが、こちらの体験ワークショップを通じて、子どもたちにまずビーチバレーというものを知ってもらう、そのためにビーチバレーボールのルールをきちんと伝え、日本を代表するような選手の方々に４人来ていただき。","voiceIndex":55,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"もう少し、ビーチバレーと名前を冠するのであれば、できるだけ環境をそれに近いように整えてやるべきだと思うのです。ですから、そういう点で、今の説明を伺っても、そうですか、わかりましたというふうには私はなりません。ぜひ環境をしっかり、ビーチバレーボールらしい環境、設備をしてやっていただきたいというふうに思います。そのために必要な予算は、やっぱりつけるべきですよ、それは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひそういうふうに言ってください。文教委員会としての総意だということで区に求めたらいいのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"私はやっぱりオリンピックに対する捉え方というものが、全庁的にしっかり機能していないのではないかという、そういう感じをこのビーチバレーの企画を伺って実感したのですけれども、あそこでのエキシビションについては、だいぶ前の企画で、今度は別枠でビーチバレーというふうに子どもたち対象になったわけですけれども、全庁的にどういうふうにオリンピックに対する捉え方を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"},{"speaker":"須藤副委員長","kind":"質問","question":"すばらしいことをやろうとしたんだけれども、これは基本的には東京オリンピックのビーチバレーが品川で開催できるよということだから、「歓迎東京オリンピック品川区開催」というふうにポンと頭にうたって、体験がビーチバレーだよということになれば、今度こういう順序だよということが来るんだけれども、あんまりビーチバレーを出してしまうから、砂ではないからいけないとか。","respondent":"伊崎子育て支援課長","answer":"この事業が品川区と東京都の共催であればそれはいいよということだったのですけれども、品川区の事業としては、そこは許可できないというご指摘をいただきまして、このような形での開催となっております。","voiceIndex":64,"id":"exchange-024"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"だから、そのあたりもしっかり連携を組んで、どうせやるなら、オリンピックというものを区民の皆さんに、あるいは子どもたちにしっかり知らしめて、そしてやること自体も本当に砂地を使ってどうのという、それは費用がかかれば東京都と折半するというやり方が出てくると思うので、一生懸命やろうとした努力は認めるけれども、せっかくやるなら、もう少し区民の。","respondent":"こんの委員長、今井制度改革・待機児童対策担当課長","answer":"ご発言がないようですので、これで本件を終了いたします。私から、子ども・子育て支援新制度「区民説明会」の開催につきましてご報告申し上げます。子ども・子育て支援新制度は、平成２７年４月から本格施行予定で準備を進めているところです。","voiceIndex":66,"id":"exchange-025"}]},{"id":"topic-04","title":"の子ども・子育て支援新制度「区民説明会」の開催","agenda":"の子ども・子育て支援新制度「区民説明会」の開催","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、今入園していらっしゃる保護者の方、あるいはこれから利用されようとする保護者の方と、区民と言ってもいろいろいるわけですから、その辺の仕分けはどういうふうに考えているのかなということと、あと、これから入ろうとしている方もそうですけれども、既に入っている方は、今の受けている保育のサービスが、来年度以降どういうふうに変化するのか、全く同じなのか、あるいは。","respondent":"今井制度改革・待機児童対策担当課長","answer":"保育料等につきましては、第３回定例会で議案が上程予定であるということは既にご案内していると思いますけれども、私どもも、この説明会では、保育料等のご説明は上程前ですのでできない、しないというふうな予定でおります。","voiceIndex":71,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、この２回にわたる説明会は、保育ママや認証保育を利用しておられる保護者を対象にということ、あるいは、これから利用したいというふうに考えている、そういう方たちを対象にしているということなのかをもう１回確認したいのと、いずれにしても、現実的に保育園や幼稚園を利用されている方が対象ということであれば、こういう時間設定で説明会においでになるのが可能なのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"個々の保育園、幼稚園における説明ですが、まずは区民一般への説明があるとともに、私ども、今、こちらのほうの説明会の内容について詰めておりますので、これからあります区内の幼稚園、保育園に対する会議、それぞれの私立幼稚園連合会なり、私立保育園連合会がありますので。","voiceIndex":73,"id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、お子さんと一緒に参加できる、お子さんをお持ちの方が対象に多くなられるのかなと思いますので、ぜひ工夫をしていただいて、例えば、どこまでやるのか、先ほどベビーカーをというような話もありましたけれども、ベビーカー置場だったり、お子さんと一緒だと、泣いてしまったりとかでしっかり聞けないからという方も出てくるのかなというふうに思いますので、託児の施設を設置するのかどうかも含めて。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに、定員設定ですけれども、先着順とこちらでは書きましたけれども、人数のほうが、スクエア荏原は、今、全面押さえておりますので、最大２００名から３００名はお入りいただけると思うのですが、私ども、実際にこれまでこういうふうな説明会の開催を見ていますと。","voiceIndex":75,"id":"exchange-028"}]},{"id":"topic-05","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"指導時間数なのですけれども、武道とダンス、２時間から６時間、ちょっと開きがある。５時間から１０時間、開きがあるのですけれども、もう少し詳しいところを教えていただきたいのですが、どうなっているのでしょうか。","respondent":"村尾学校支援担当課長","answer":"学校の実情とか、さまざまな講師の対応で、２時間連続で中学校に行って武道場で練習をして、それを２時間を武道としてカウントするという学校と、また、６時間は、もう少し長めにそれぞれのわざを取り入れるということで、少しこの開きがあるのは、実際の学校の現状です。","voiceIndex":81,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"小学校または中学校と指導者の、小学校は外部の方がいらして、中学校は体育科の教師の先生がいらっしゃる。その辺のところも、中学校は体育科の教師の先生だけであるのですけれども、小学校みたいにほかの先生、外部の方が入ることはないのですか。その辺をお聞きしたいと思います。","respondent":"村尾学校支援担当課長","answer":"２点目、指導者の件ですが、中学校は基本的には体育の教員が教え、小学校については、柔道について全く知識とか経験がない教員も多いので、それについては、それぞれ外部講師の人に来ていただくか、または小・中で連携している中学校のほうに小学校の子どもたちが出向いて。","voiceIndex":83,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"今最後にお聞きした連携をとるということ、とてもいいお話だなと思うのです。そういう連携をとれる学校ととれない学校があるかもしれないのですけれども、その辺、やはり子どもたちが同じように指導を受けて、また同じような経験ができるような体制をとっていっていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"このダンスにおいては、外部の人材を活用されていないのか、それが１点。ダンスのところの内容で、男子と女子が分かれていて、女子のところを足すと１６校になるのですが、これは１校で２つをやっているという認識の資料か、ほかは全部数字が、小学校と中学校の合計数が合うのですけれども、ここだけ１６校になってしまうので、そこを教えていただきたいと思います。よろしくお願いします。","respondent":"村尾学校支援担当課長","answer":"委員ご指摘のとおり、本当にこれは特色ある教育かと言われると、当たり前のことだろうということもあるのですが、それでも各学校においては、当たり前なのですけれども、なかなかできないという、すごく課題意識を持っている学校がやっぱり多いかなというところで。","voiceIndex":86,"id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。特に教師に対して負担もどうしても出てきてしまうので、人材の活用をどこまで予算をつけてやるのかとかということもあるかもしれないですが、若い子でダンスをやっていて、子どもたちに教えたいという子は、実はいっぱいいるのですね。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"武道の関係なのですけれども、柔道、剣道、相撲ということで、それぞれ選択なのですけれども、私は八潮に住んでいますので、八潮の学校は武道場も整備されているのはわかるのですが、小学校もそうですけれども、とりわけ中学校で、そういう武道を練習する、授業を受ける、そういう場所はどのくらい整備されているのか、そのあたりをこれが出てきたときに伺いたいなということが１つです。女子も習うのですか。","respondent":"村尾学校支援担当課長、田村教育次長","answer":"１点目、場所なのですが、全ての学校に武道場が設定されているというよりも、体育館に畳を敷いて……。失礼しました。２番目ですね。女子も柔道を行っております。新しく改築したりした学校は、武道場がきちんと設置基準の中で必要なので、武道が必修化になりますから設けています。ただ，それ以外の、まだ改築前の学校は、体育館に畳を敷いたり、体育館を利用してやっている。","voiceIndex":89,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"一緒に対戦ということはないのかもしれないけれども、同時に受けてやっているという、必修だからやるようになったということなのですか。小学校のほうは、近隣の中学校に行って選択科目としてやっているということなのですが、それとてスペース的に、あるいは、その学校との授業との関係で、やりくりが大変かなと思ったりするのですが、そのあたりの現状というのはどうなっているのでしょうか。","respondent":"村尾学校支援担当課長","answer":"２点目、小学校から中学校にというところもあるのですが、実際に連携している中学校ですので、何時間目のここをということで、１年間の予定を見た上で、中学校に負担というか、無理がない日を設定して入れている。","voiceIndex":92,"id":"exchange-035"},{"speaker":"南委員","kind":"意見","question":"今年度のこの文教委員会の所管事務調査でもありますので、環境も含めて知りたいと思っているので、今でなくていいのですけれども、この委員会でぜひご報告をしていただけるようにお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問・要望","question":"各学校ごとなのか、教育委員会経由なのかの確認です。それが１つ。それと、謝礼があるとしたら、いくらかの話です、校長先生なり学校が頼みやすい予算どりがあるのかどうか、これをまず武道のところで伺いたいのと、ダンスのところも同じです。今、教員だけでいいものなのか、導入から２年目に入って、どういうものが現場から声として改善点で要望も含めてあるのかどうか教えてください。","respondent":"村尾学校支援担当課長","answer":"３点目、ダンスにつきましては、現場の先生たちからの声として、専門的なというところもあるかなとは思うのですが、実際、私が知っている範囲では、そんなにダンスで専門的なすごいレベルの高いものをやるというよりも、楽しんでリズムに合わせるというのがメーンなので。","voiceIndex":95,"id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問・要望","question":"もう細かいことはいいとして、もともと武道、ダンスの必修化の背景には、期待も含めて大きな意味合いがあったと思っています。単にダンスの技術指導だとか、武道もそうですが、そういうものでは決してないと思います。そこに単に任意のボランティア、善意も大事ですが、せっかくの武道、ダンスという必要性、その意味合いとして質を求めてもいいのではないかと。ダンスもしかりです。","respondent":"村尾学校支援担当課長","answer":"言われるように、質の向上も含めて、それぞれ、基本的に型から入ってしまうということもあるのですが、その中で、今後、武道であれば、当然礼儀の部分という形のほうから、そしてダンスについては表現力も含めて、子どもたちの持っているものを発散できるようなものとしては。","voiceIndex":97,"id":"exchange-038"},{"speaker":"つる委員","kind":"意見","question":"参考までに今のダンスのところで、現代的なリズムのダンスについてのところなのですが、把握している範疇でいいのですが、どういう曲を使っているかというのは押さえていますか。","respondent":"村尾学校支援担当課長","answer":"具体的な曲までは、ちょっと今ここではわかりません。","voiceIndex":99,"id":"exchange-039"},{"speaker":"つる委員","kind":"確認","question":"ここで括弧の中でヒップホップとありますね。環境音楽とかそういうものはいろいろありますけれども、音楽が曲調によって与える影響だとか、そういったところもあるし、表現の仕方もいろいろ出てくると思うので、その辺をきちんと確認しておいたほうがいいのではないかと思いますけれども、この辺はどうでしょうか。","respondent":"村尾学校支援担当課長","answer":"私のほうも、もう１回学校のほうを確認して、それぞれどのような曲を使って、またどのような目的を持ってやっているかということを確認させていただきたいと思います。","voiceIndex":101,"id":"exchange-040"},{"speaker":"つる委員","kind":"確認","question":"多分いろいろな曲が使って、全然いいと思うのです。そうしたところも若干確認をしながら、その中で自由な表現方法としてある部分というところでやっていく必要性がある。私も経験上いろいろなジャンルの曲を把握する中で、それはそれでいろいろあるなというふうに思っていますので、その辺も今後参考にしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-041"},{"speaker":"高橋委員","kind":"質問・要望","question":"いろいろな面も整備をしていただきたいと思うわけですが、武道のほうで１つお尋ねしたいのは、体育用実技の教材というか、柔道やら剣道というものもかなり費用がかかると思うのですけれども、そこの点について、たしか就学援助の対象になっていたのではないかと思うのですけれども、まずそこの確認と、それとも、この費用は個人負担になるということから、例えば、２時間か６時間。","respondent":"村尾学校支援担当課長、野呂瀬学務課長","answer":"武道のほうなのてすが、基本的に柔道着については学校で購入をして生徒に貸与しているという形で、４校のみ個人で柔道着を買っているという現状です。就学援助の関係ですけれども、就学援助は体育実技用具費ということで、これは限度額がありまして、柔道ですと７,３００円、剣道ですと５万円を限度額として、その学校でどこでどのぐらいまでということが決まっている。","voiceIndex":104,"id":"exchange-042"},{"speaker":"高橋委員","kind":"質問・要望","question":"武道のほうの用具については、柔道についてはわかったのですけれども、剣道は、これもやっぱり学校で貸与という形になるのでしょうか。購入か購入でないというのは学校の判断になるのですね。そこも確認です。","respondent":"村尾学校支援担当課長","answer":"剣道につきましては、学校が購入して生徒に貸与しているという形です。２点目の研修につきましては、外部人材を含めて本当に検討を進めていきたいというふうに思っております。","voiceIndex":107,"id":"exchange-043"},{"speaker":"須藤副委員長","kind":"質問","question":"武道の中で伝統的な行動というと、先輩から言われたら「はい」、上下関係でたてついてはいけないよみたいな、それが伝統なのか、間違ったことは先輩でも間違っていますと言えるような仕組みになっているのか、この「伝統的な行動の仕方を守る」というのは何かなというのが、そのあたりがどういうふうになっているのかということが１点と、それから、さっきの正しい姿勢に関する取り組みで、小学校１９校。","respondent":"村尾学校支援担当課長","answer":"２点目、姿勢についてなのですが、やっている学校とやっていない学校の差と言われると、なかなか表面的なものは特に数値で出ているというわけではないのですが、ただ、この取り組んでいる学校に伺ったときとかは。","voiceIndex":109,"id":"exchange-044"},{"speaker":"須藤副委員長","kind":"質問","question":"そうではなくて、やはり興味を持たせるというのは、その指導者がしっかりとしたものがあって、子どもたちに内容が伝わってくると、理解ができると思うので、先ほど来、いろいろな委員が心配して外部の指導者というお話もあったりしているのですが、やはり指導者のありようによって育てられるほうは随分変わってくると思うので、今後とも、今日いろいろお話が出た中の、多少費用がかかっても。","respondent":"村尾学校支援担当課長","answer":"委員おっしゃるとおり、やはり指導者の姿勢というのは、子どもたちの教育上とても大切だと思います。特に外部人材の人たちの協力を得て、子どもたちの学習を広げていくというのは、先ほど来、申し上げたとおり、教育委員会としても進めていこうというふうに考えているところです。","voiceIndex":111,"id":"exchange-045"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"今お話ししたように、ですから、今後とも指導者については、いろいろなご意見があったように、外部から入れろということも参考にしながら、品川はやっぱり武道をやっても、ダンスをやっても、姿勢もすばらしいよと、今、学力についてはすばらしいよと言われてきているけれども、同じようにそのこと自体も本物を取り入れているよという仕組みをぜひつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":48248,"voices":124}},{"id":"h26-20140825-5","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"総務委員会","time":"午後１時００分～午後５時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の都区財政調整制度の概要及び平成２６年度財政調整交付金当初算定結果","agenda":"の都区財政調整制度の概要及び平成２６年度財政調整交付金当初算定結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"まとめて、もう１点ですけども、先ほどの説明の中で、標準区、資料で言うと、資料１の６ページになりますけども、標準区の設定の中で、道路面積がありますけれども、ここで言う道路面積は品川区ではいわゆる何平米になるのか、この道路面積の標準区のどれぐらい上回っているのか、下回っているのか、また道路面積が標準区の、いわゆる大きい単位というのですか、そのところは何なのか。","respondent":"本城企画財政課長","answer":"今回で申しますと、１０ページで言えば、どれが特徴というわけではありませんけれども、例えば、９ページ、１０ページの一覧で申し上げますと、今回新規算定としては全部で８項目あります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"初めに、特徴だけ伺ったのですけど、大きくはいわゆる防災も木密地域の関係と、一つは施設の規模やそこにかかる経費のお話がありましたけど、木密地域にかかるところは、例えば木造住宅の耐震化は対象になっているのか、いわゆる不燃化１０年プロジェクトが具体的にはそれを指すのか、幅広い事業だと思いますので、そこを伺いたいと思います。","respondent":"本城企画財政課長","answer":"それとそこも含めてですが、財調の中で協議ということで、東京都と特別区の間でもろもろな協議をしていくわけですが、その中で、特別区側の基本的なスタンスといたしましては、先ほどの８ページのところで、財調協議の流れということでご説明させていただきましたが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に妊婦健診についてはどういう経過があるのか、前回言ったのは、２階に上げてはしごをとるようなものだという例え話を言ったのですけども、区民の暮らしにとって必要なものは、都にも求めていくし、区も実施していくというスタンスなのか、具体的に伺いたいと思います。ここともかかわるのですけど、先ほど標準区の道路面積を伺いましたけれども、２３２m2で、品川区は２０７m2だということですよ。","respondent":"本城企画財政課長","answer":"実際、仮に外れたとしても、それぞれの区が主体的な判断をする中で、改めて共通な事業として各区で実施されるような関係になれば、基準財政需要額にもまた反映してくるとか、そういう関係というふうに理解しているものです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"その算定の中身によって、金額が張る中身を算定項目に持っていけば、それはそこの区としては算定の中身の額が多いのだから、いただける財調の金額も多くなるというような感じになるのですか。これは各区が算定を充実させる云々でこれだけ出ていますけど、全然各区の事情というのは違うではないですか。そうすると、それによって、いっぱいもらえる、もらえないということになるのでしょうか。","respondent":"本城企画財政課長","answer":"繰り返しになってしまうかもしれませんが、あくまでも実際交付金自体は基準財政需要額と収入額の差によって求められるということなので、今基準財政需要額を説明しましたので、一方では基準財政収入額との差です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"算定の項目に対して都区で調整はするのでしょうけど、そのとき、結局都のほうで、いや、これは余り出せないとか、いや、これはちょっと外したいとかという意向が仮に政策的に、政治的に強くなってしまったら、そこで全体と言ったらおかしいのですけど、財調の金額も減ってきてしまうのかと、単純にそう思ってしまうので、そんなことを、でもしようがないのかもしれないけど、最初が５５％という金額。","respondent":"本城企画財政課長","answer":"あくまでも特別区の、先ほどの８ページの流れの中でご説明させていただきましたが、決算分析ワーキンググループとか、実際どれだけのものが経費としてかかっているかというので、具体的に証明して、何区でこれだけのものをやっているとか。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今年の算定ですけど、最終的に再算定になるのだろうけれども、２２９億円というのは、不足額というか、残ったわけですよね、算定した後、これは残し過ぎではないのかとちょっと思っていて、ここら辺の協議というのは、１９０億円とか２２０億円とか、結局、それで３００億円になるのか、３６０億円になるのかは別として、冒頭から２２９億円という数字をどう捉えられているのかというのを教えていただきたい。","respondent":"本城企画財政課長","answer":"ただ、結果として、当初想定していたような大きな制度改革は、この何年か財調に反映させる形では見合ったものはないというような認識の中で、４５％と５５％で推移していると、そのような状況であると理解しているものです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点答弁で後で教えてほしいのは、区が算定されたもので、実際使っているもの、例えば道路でもいいのだけど、それにあい差が生まれているのか、実際、区はもっとかかってしまっているのか。そういう議論というのは、１年に１回でもそういうことを財調協議の中で持てないのですかというのを聞きたいのです。４５％に対するチェックを入れるという協議ができるのかどうかというのを教えてほしい。","respondent":"本城企画財政課長","answer":"かなり規模が大きいものであれば、大きい需要を見込んだり、細かなところは小さいものを積み上げたりして、そのもろもろの結果、再算定の残は基本的にはなくなるような形で全額交付されるような形になっているものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"しっかり各区でやっていきましょうという権限移譲の問題も含めてやっていこうとされているときに、それは大きな制度改正なのか、それは算定をしてくると、再算定なり、算定残なりがあると、今の金額ぐらいの中ではやれるのではないのというと、５５対４５は変わらない可能性がなきにしもあらずなのかと。５５％の中でやれよと。ちょっとそこら辺の区の考え方をちょっと教えてほしい。","respondent":"桑村企画部長","answer":"それについては必ず区に来るべきではないかと、これは毎年主張しているわけですが、これは決着済みというのでなかなか応じてもらえませんけど、そういう主張すべきところは主張していますけども、財調本体については今そういう考えですので、余り４５％云々というのについては。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認をさせてください。協議会整理項目の中で、充実というところと、それから見直しというふうになっているのですが、この見直しという点はどういう根拠による見直しなのか、充実はプラス・アルファという意味合いで書いてありますけれども、この見直しという事業の項目というのは、これはどういう意味で見直しを図ってということでされているのか、その点だけ確認したいと思います。","respondent":"本城企画財政課長","answer":"その次に並んでいる算定方法の改善等というのは、方法自体の見直しということで、繰り返しになりますが、事業費の見直しなどのときには額を少なくする方向での見直し、結果として額が少なくなっているものを集めたものが１７項目あるというものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"そうなってくると、かなり基礎自治体、２３区の考え方というか、これからやろうということに対して、国との絡みがどういう形でこの見直しに入ってきてしまうのか、それとも入ってこないのか、その辺はいかがでしょうか。","respondent":"本城企画財政課長","answer":"見直しということで、額を少なくする方向でとはちょっと申し上げたのですが、ただ、その額が少なくなる方向というのは、決算分析をやった結果、実態に合わせるという意味なので、計画は１７項目が挙がっていますが、算定上はこれだけになっているけれども、決算を見ると。","voiceIndex":23,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"そうすると、実際は算定の、実際とずれが生じたので見直しを図ったものというのがこの１７項目という理解でよろしいのでしょうか。なので、そのものの事業を、見直しを図るというか、縮小という意味ではなくて、実際の算定、実績に合わせた形で見直しを図るという１７項目でよろしいのでしょうか。","respondent":"本城企画財政課長","answer":"基本的にはそのような形で表記しているものです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"例えば５ページの配置図、駐輪場は確かに荏原文化センターの裏側ですけど、実際はこの右側のほうに自転車をとめている利用者が多いですから工夫の範囲というのはいろいろ必要なのかとは思いますけども、そういうのも含めて、今度これは工事の対象ではないと思うのであれですけど、今の配置や姿と工事後は変わるものがあるのか、内装以外で、配置とか形とか、機能は変わらないと思う。","respondent":"小林施設整備課長","answer":"ただ、お便所の改修がありますので、そちらのほうの間取りとか、そういうのは若干変わってくると思います。については、ほぼ今委員がおっしゃったとおり、内装改修の仕上げの改修なものですから、配置等については変更ございません。","voiceIndex":31,"id":"exchange-012"}]},{"id":"topic-02","title":"北品川三丁目外下水道管再構築および老朽化対策工事請負契約","agenda":"北品川三丁目外下水道管再構築および老朽化対策工事請負契約","exchanges":[{"speaker":"西本委員","kind":"質問","question":"辞退というのが３社ありますが、この経過はどういうことでしょうか。","respondent":"立川経理課長","answer":"４社にとりあえず申し込みいただきまして、実際は辞退が３社だったですが、こちらはいわゆる申し込みをいただいた後に内部で検討した結果、配置する管理技術者が配置困難であるとか、また区で示した予定価格と事業者の見積もり金額が異なる。","voiceIndex":37,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"辞退というのは、会社側から取り下げるという意味でしょうか、その経緯をお願いします。","respondent":"立川経理課長","answer":"一度お申し込みいただいて、その後に工事設計書等を入手してもらいまして、そこで初めて工事内容について精査してもらうということになります。そういった意味で実際の札は入れなかったです。","voiceIndex":39,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のにもかかわるのですけど、４社が申し込んで、３社が辞退だと、残り１社が落札となると、競争はどう働くのかという単純な疑問が湧くのですね。おそらく今までもこういうことが何回かあって、そのたびに説明があったとは思いますけども、そうは言っても、４社が申し込んで、３社が辞退だと競争にならないのではないかと疑問に思いますので、ご説明をいただきたい。","respondent":"立川経理課長","answer":"この入札案件につきましては、電子上でやっておりますので、どちらが申し込まれたか、どの業者が幾らで入札するのかしないかということは、開札があるまでは公表されない内容ですので、実際開札した結果１社だけが入札していたということなので。","voiceIndex":41,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"確認","question":"一つ確認したいのは、この予定価格、これは見積もりをある程度業者からとって予定価格を決めたのか、区のほうでしっかり査定をして決めたのか、どうしてそういうことを言うかというと、これで１社だと、次も１社だけど、辞退、辞退というと、不調を招く可能性が出てくる。例えば、１回やって、２回不調というときも、よく今新聞に各自治体で出てくる。","respondent":"立川経理課長","answer":"２点ご質問いただきました。１点目の予定価格の算出です。","voiceIndex":43,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこで、予算があるではないですか。例えば今４社なら４社から聞くと、これはとてもではないけど、この１ではだめだ。１.２ぐらいにしてくれないとだめだみたいな話を聞くと、その１.２にするときに、補正予算を組むのか、ある程度の流用枠があって、それなら流用できるみたいなときというのはあると思いますけど、そこら辺の兼ね合いというのは、どういうふうにされているのかというのを教えてほしい。","respondent":"本城企画財政課長","answer":"財源の確保の関係では、当初予算の執行状況を見て、財源として確保できるものがあれば、時期的なものを含めて流用として対応できるかどうか、それも検討した上で円滑な執行を目指していくというのが基本的な考えです。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-03","title":"東品川三丁目付近下水道管耐震化工事請負契約","agenda":"東品川三丁目付近下水道管耐震化工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"どういうときに限られているのか、そこの仕組みを伺いたいというのと、あとは１６ページにイメージ図がありますけど、要するに液状化したときの対応だと思いますけども、何cmなのか、何ｍなのか、どれぐらいの移動に耐え得るように設計がされているのか、あと、図だと下水道のほうが動くことになっているけど、マンホールのほうが動くのかと思うので、これはイメージ図であって、実際は下水道だろうが。","respondent":"立川経理課長","answer":"２のいわゆる被害想定ですけれども、こちらにつきましては、東京都のほうでいわゆる直下型大地震の被害想定という、ちょっと詳しい資料は載っていないですけど、いわゆる東京都のほうの被害想定で耐え得る工事内容というふうに聞いているところです。","voiceIndex":51,"id":"exchange-018"}]},{"id":"topic-04","title":"の順番では行政視察についてでありますが、本件では９月の上旬に予定しております視察のための事前の勉強会を行うことから","agenda":"の順番では行政視察についてでありますが、本件では９月の上旬に予定しております視察のための事前の勉強会を行うことから","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"もしわかれば教えてほしいのですけど、高知とかは誰からお話を聞くのですか、先方は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":41341,"voices":68}},{"id":"h26-20140826-14","meetingId":"h26-cm08","date":"2014年8月26日","dateIso":"2014-08-26","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時３２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今まで職員宿舎になっていたので住宅、区の職員の住宅だけではなくて、例えば区営住宅とか区民住宅とかを含めてそういう住宅は可能なのかと思いますけれども、そういうことで可能なものというのはどういうものを考えればいいのかというところと、情報が来て１月ぐらいたっているわけですから、一定の検討はされているのではないかと思うので、これだけだと全く何もわからないので。","respondent":"柏原行財政改革担当課長","answer":"この路地状敷地に関して、この形状のままであるとそういった建物は建ててはいけませんということで東京都の安全条例で言っておりますので、それ以外の建物となりますと、余り人が集まらないような建物になりますので。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"一番上の、この品川第二寮のところのちょっと確認ですけれども、要するに、今までは宿舎として使っていたから、いわゆる共同住宅というふうに概念として入るかどうかはあれだけども、住宅として使っていっていた。","respondent":"柏原行財政改革担当課長","answer":"すみません、ちょっと説明が粗かったようですけれども。","voiceIndex":8,"id":"exchange-002"},{"speaker":"あべ委員","kind":"質問","question":"この品川第二寮についてお伺いしたいのですが、一番の問題は接道が悪いということだと思いますけれども、以前からも話が出て、でも難しいということになっていた、この入り口近くの建物ですね。そういったところと地権者の協力を得てみたいな働きかけというのは今はどうなっているのでしょうか。これ、都営アパート、都と一体の敷地にしてしまうとかそういう話も全くないのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"もちろん目の前に都営住宅がありますので、一体で考えたというようなことも検討の俎上にはのせていますので、ただ一つは、まず人様の土地だというところがありますので、そこの部分にどう時間をかけられるかかけられないかというところがあります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれありがとうございました。そうすると、全く交渉しない、あるいは接触しないというのもないのではないかと私は思っております。限られた時間ではありますけれども、ぜひここの可能性というのも探っていただきたいと思いますので、お考えを教えてください。この中を今さら密集地にしたくないという思いはありますが、それについてお考えを教えてください。この件については、ぜひ答弁をお願いします。","respondent":"柏原行財政改革担当課長","answer":"仮にですけれども、見送ってしまって民間のということになった場合には、我々としてもここがいわゆる建て売りみたいな形で小さな住宅ができてしまうというのは余りいい状況ではないとは思ってありますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"区ではそこら辺の仕分けといいますか、精査は今後していかれるということなのでしょうか。それとも、都から特にないと言われたので、このままこういうことで終わるのかということが１点。ここに載っているリストというのは都の全ての部局のものではなくて、ここに出ていないものもあるということだったと思いますが、それがどこどこかというのをもう一度教えてください。","respondent":"桑村企画部長、柏原行財政改革担当課長","answer":"ちょっとこちらのほう、４ｍのあれで、非常に余り大きな活用はできませんけれども、例えば何かうまい手法がないかとかそういうことを少し検討させていただいて、また次回の委員会でご報告させていただければと思います。ただし、先ほどの東京都のこちらの検討チームのほうが出しているものが、都営住宅等の創出用地の活用というのが出ていますので、場合によるとこういった物件から、土地から物が出てくる可能性もあるというのはありますので。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"これについては、すみません、どういう話になっているかこの機会にちょっと伺っておきたいのと、これをもし、これも９０％で借りるとかそういう対象になっているのか、ちょっとその辺のくくりがわからなかったので教えていただければと思います。品川区内にもまとまった土地があるかという印象なのですが、これ、なぜ出さないのかというようなこととか説明あるいは背景というのはあるのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"本体部分といいますか、土地の部分については２０年という縛りもありますけれども、やる仕事が決まると、用地指定の期間ということで清掃作業でしか使えないという縛りもあり、無償で譲渡を受けている状態です。ですので、土地建物は一応品川区のものになっています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、国も東京都も恐らく、あくまで想像だけれども、自分たちのさまざまな事業目的を展開する中で、どちらかといったら手に余るようなものを外に出そうではないか、そういう感が非常に見えてくるわけであって、それを何でもすぐ飛びつくというのは、逆に品川区の税金を投入することを考えたらそれは慎重に考えなくてはいけないし、だから、そういう一つの、何ていうか。","respondent":"桑村企画部長","answer":"ただ、先ほどの土地は、まだ都営住宅ですとか一定何か交渉できるような余地があるのかということもありますので、もう少し検討させていただきたいというのが今のところであります。","voiceIndex":21,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"冒頭、行革担当課長にこの資料が来るのが遅れたという話もあったではないですか。意図的なものを感じるのがあるのですよ、国が一体本当に本気でこのことをやっているか、この件については。だから、そういうことをずっと考えていくと、国が件数も全てあらわしているかどうか、特にこういう問題に関してはね。それが品川区としては一つの考えをしっかり持って対処してください。そのことはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"ここの土地、今伊藤委員がお話を、質問をした部分を引き継いだ上で、費用対効果というここのところをどのように分析をされて、今後厳しいが検討をするということでここに書いてありますけれども、このところ、費用と効果についてどのようにお考えになっているのか、端的に教えてください。","respondent":"柏原行財政改革担当課長","answer":"先ほど来のお話ですけれども、こちら、土地の面積からしますと２,３００平米ということでなかなか区としては出てこない土地の広さで、こういったところがもし有効的に活用できるのであればぜひともという部分はありますけれども、費用の部分と。","voiceIndex":24,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"民間同士、企業ならば隣の品川税経会館ですか、品川青色申告会等々ありますけれども、いずれは建て直し、またどこかいいところに入れればということは当然頭の中にも入っているだろうし考えていると思う。都営南品川アパートのほうもそうですけど、耐震基準等を考えたら、いずれは何とかしなくてはいけない。別に質問ではなくて、それだけ伝えたかった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"これは昨年の６月から試行してみて、区としてはどのような制度運用実態の印象を持っていらっしゃるかということをまず教えてください。それから、改めて２３区の状況を見る中で、品川の場合はたしか設備を対象にしていなかったと思いますけれども、これってどういう背景、理由があったのかちょっと確認させてというか教えていただければと思います。とりあえず、その２点をお願いします。","respondent":"立川経理課長","answer":"そうしたところを考えますと、仮に８０％という数字を最低とした場合に、これまでいわゆる材料費プラス労務費、それから会社の利益、それで積算して入札しても、結局失格になってしまうような業者も中にはいらっしゃるということなので。","voiceIndex":31,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"適用価格の基準ですけれども、これ、改めてみると１,０００万円以上となっているのはごく少数派のようで、これが実態に合っているかどうかというのもなかなか比較だけで見るわけにはいかないと思いますけれども、この数字についてはどのように区としては考えるのでしょうか。","respondent":"立川経理課長","answer":"予定価格を公表することによって、また最低制限価格というのがはっきりわかるというか、実際は１０分の８から３分の２の範囲ですけれども、実際積算すると１０分の８を超えてしまう場合も結構ありますので。","voiceIndex":33,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"区内業者がやりやすい仕組みというのを取り入れていってもらいたいと思いますが、約１年試行してもらっていい状況であるならば、できるだけ早く本実施に入っていってもらいたいと思うのだけれども、そのあたりのお考えはいかがですか。","respondent":"立川経理課長","answer":"国のほうとしましても、今回法律の改正等もございまして、そういった中で公共工事の品質の確保促進に関する法律、また、いわゆる公共工事の入札契約の適正化もですけれども、その２点において、より以上のこれからの工事品質の確保ということと。","voiceIndex":36,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"ですから、いろいろな意味で区内業者を育てるということで、こういった最低制限価格制度を取り入れろという話をずっとしてきて試行してもらったので、私どもとすれば、今言ったように、１３０万円という一つの数字というものが目安になると思います。１,０００万円ということを切らないで、いろいろな意味で区内業者が育っていくような仕組みというものを考えていってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"いろいろありがとうあります。最低制限価格制度が始まって、約１年。本来であれば、これもこの一覧表を見ると一目瞭然ですけれども、建築・土木に加えて、設備・電気についても同時にスタートするというのが、私は本来あるべき最低制限価格のあり方というふうに思って、各会派の方々もそういうふうな思いで発言をされていたというふうに僕は記憶しております。","respondent":"立川経理課長","answer":"そうすると、提出するほうも、また審査するほうも結構事務負担があるというところで、品川区ではこの制度についてはこれまで実施していなかったのですけれども。今後は、やはり併用している自治体も多いということなので、十分研究していくというような考えでいるところです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。どんな制度を導入するにしても、メリット、デメリットはありますので、しっかり区内事業者の人材確保等、区民に喜んでいただける施設の整備等について、引き続きといいますか早急に設定事業者の見直しと、あと他の２部門についての導入も見直しと早期に進めていただきたいと希望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"確認","question":"ありがとうございました。今、各会派からもいろいろありました。その上で今拝見をして、一点だけまず最初に確認したいのですけれども、品川のところで建築、土木が対象になっていて、電気・設備は除かれているというのは、これはわざわざこういうふうに記載がありますけれども、そういうことをやっているのは２３区中品川区だけということでよろしいのでしょうか。","respondent":"立川経理課長","answer":"その辺のバランスを考えながら、案件によっては最低制限価格を適用しないという運用をしている自治体も幾つかあります。","voiceIndex":42,"id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"わかりました。それは行政としてはより効率的な税金の使い方というところですね。その中に根絶であるとかいろんなものがあって、それを地方自治体に対して、こういうのは最低制限価格に関係していることなので申し上げるのですけれども、これをいろいろ意見を聴取をするということになっておりますけれども、品川区は意見を上げられるのか、またそういう依頼が来ているのかどうか、確認させてください。","respondent":"立川経理課長","answer":"いわゆる品確法の今回改正がありまして、その第２２条に発注関係事務の運用に関する指針を設けるというところがありまして、これについては、国は地方公共団体、学識経験者、民間事業者その他の関係者の意見を聞いて運用指針を定めるというふうに規定されております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"照会が何で経理課に来ないのかはよくわからないのですけれども、道路課のほうに行っているということですけれども。最後に一つだけ。これは今後また総合評価方式を１２月にやるという予定に本委員会ではなっていますけれども、総合評価方式の最低制限価格、また低価格調査ですか、入ってくると思うのですが、そこの関係についてどのように区は考えられているのか、そこだけをお伺いしたいと思います。","respondent":"立川経理課長","answer":"どちらもやはり工事品質を確保するという意味では、最低制限価格の運用というのは一定の歯止めになるというのが工事品質の向上に資する部分がありますので。","voiceIndex":46,"id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ありがとうございました。そこで、最低制限価格と低入札価格調査制度が非常に重要になってくると思いますので、効果のある、何度も言っていますけれども、効果的な総合評価方式の実施に向けて調査も、この研究もぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、仕入れ業者がメーカーから何％、５割で入れるよとか、おたくは取引が少ないから６割、おたくは７割でないと売れない。そうすると５割で入れたところは絶対に値段が安くなりますよね。そこに仕事を回したら、作業員はどこから来るのですか、群馬から来ます、栃木から来ます、埼玉から来ます。そうすると、区内業者がそれで残っていけるのかという。意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"確認ですけれども、ここは今の委員会の趣旨からすると、委員間で議論をするという意味ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"品川区は持っていますので、改めてこれを品川区が今持っているものと、それから２つの基金、品川区の条例を引っ張れば運用益を歳入に繰り入れということが書いてあるので、どれぐらいの運用益があったのかということについての確認。これがどういうふうに使われているかということと、あと同じ趣旨ではないのかもしれないけれども、もう一個の平和基金の利子は６０万円。","respondent":"本城企画財政課長","answer":"同じく公共料金の支払基金については、電気、ガス、水道、電話等の料金について、同じく一括して基金から支出することによって効率的に事務を進めていくという、そのような趣旨で設けている、設置趣旨としてはそのようなもので持っているものです。","voiceIndex":56,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"説明はありがとうあります。私たち自民党としてお伺いしたかったのは、例えば地球環境基金から見れば３０億円かな、３０億円です。基金の保管内訳の債券が２９億円余。それで普通預金が９９万円余があって、当然利子だって差が出るわけです。それをどういうふうに品川区は運用する目的で公益を積んでいるのですかということをお伺いしたいと思って、そのことをぜひ答弁をお願いします。","respondent":"本城企画財政課長","answer":"それと、あと用品基金に関しましては、一括して購買することによりまして、大量に購買することによって相対的に低い価格で購入できるということになりますので、毎年度の基金の運用状況の報告という中で整理していますが、例えば平成２４年度の決算で見ますと。","voiceIndex":58,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どうもありがとうあります。このお金をどういうふうに、品川区が具体的に使っていくことを前提として基金の運用益を考えているのだろうから、その目的はなんなのですかということです。だったら、その目的は何ですかということについて確認したいというのが私たちの求める答えなので、改めて、わかる範囲で結構ですから、答弁をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"私たちの意見の中では、こういうふうに一つの基金をずっと勉強していくと、これがこういうふうな利子が出てきたけれどもどういうふうに活用されているかとか、それが行政目的にどう合致していくかということについても勉強すべきでないかということで質問させていただきましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"今、部長からお話があったように、基金は区の施策の方向性を見せるものの意味もあると思うのですよね。これは前から私は言っているけれども、文化振興・スポーツ、いわゆる文化・スポーツ振興基金という、そういうものをつくったらどうですかというようなお話もさせてもらっているので、これは前からこの委員会の中で整理をしたらどうですかと。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"幾つか申し上げます。前回も言いましたけれども、地球環境基金３０億円、これはそろそろ見直してもいいころではないかと考えています。いろいろなその時々、１０年単位のものを考えていっても、行政の中で目指したいものというのが少しずつ変わっていくと思いますので、ちょっと地球環境はどうだろう。ちょっと最後のところだけ、区の考え方をお伺いしたいのですけれども、いかがでしょうか。","respondent":"本城企画財政課長","answer":"今後、具体的な額については、今のように幾らになるかについては今のような年度年度で見ていかなければいけない部分がウエートとしては高いところにはなりますので、それをきちんとしつつ。","voiceIndex":66,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"さっきるる申し上げましたけれども、私はいろいろ余り基金を増やし過ぎるのは、今慎重な考え方ではありますけれども、逆にこの委員会のほかの委員の方々というのは、この点についてはどういう感覚をお持ちなのかと、逆に伺ってみたいところであります。もちろん、テーマを私が決めるわけではないのですが、お任せしますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"その基金の多い少ない云々というのは、数ありきではなくて、先ほど部長がおっしゃったような、要は事業、目的を遂行するための目的達成のためのあらわれとして基金というものは出てくるわけですから、数ありきではなくてあくまでも事業、区がどれだけ積極的に区民サービスの向上に向けて事業を行っているかという部分で、内容を重視したものが第一だと考えるので、多い少ないというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-030"},{"speaker":"あべ委員","kind":"意見","question":"数ありきというか、質かどうかと言われると数ありきなのですよ。だから、大切なものを全部基金にしてたら１００個でも２００個でも大切なものが区の中にたくさん出てくるので、どうしても増えると思うのです。でも、どっちでもいいやという考え方ももちろんあると思いますし、いや、多いほうが積極的に見えていいやというのもあるし、いや、数だといろいろあっていいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-031"},{"speaker":"南委員","kind":"提案","question":"ですから、そういうので１,８００万円の果実を全部使っているのかちょっとその中身はわからないですけれども、お金の出どころが一般会計からか全部果実でやっているのかはちょっとそこを教えていただきたいと思っているのですが、そういうこのお金のパーセンテージというところを見ると、今、何ていうのでしょうか、お金がないために就学できないとか。","respondent":"本城企画財政課長","answer":"これからもいろいろな形で充実させていかなければいけないと考えています。","voiceIndex":72,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"区民のために使うというところは、くどいですけれども、しっかり堅持をしていただきたいということをちょっとお願いしておきたいと思いますし、私たちもそういう立場で基金問題を捉えていく必要があるかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"先ほどから基金の話ですが、我々は基金に関しては一本化して、基金を一本化して品川未来基金という名前、名称でもいいから１つにして、いつでもすぐ使える、どんな事業にも使える縛りのない、普通にすぐに使えるものを創設し、いちいち使い道をどうのこうのではなくて、そういう縛りのない、そういうことを、やはりそういう考え方が私は必要ではないかというふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-034"},{"speaker":"須藤委員","kind":"意見","question":"今の意見は全然私は違うと思うので。先ほど部長が言ったように、この仕事をするということを区民の皆様にしっかり示して行政の方向性はこうだというものをするということが基金のあり方の一つなので、何にもないから区民のために何でもやるというのは、何でもという仕方というのはおかしいと思うので、今の発言の中では、意見ですというけれども、それに対しては私は否という発言をしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"今、お言葉をいただいたのですが、中にはただ運用だけで済ましている基金もあるわけです。本来なら基金というのは、それを創設したらそれなりに事業の目的に充てて使うというのが私は本来の基金のあり方だと思います。だから、その辺をもっと総合的に考えて、基金のあり方を私はきちんと議論していく、皆さんで考えていくことは大事だと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-036"},{"speaker":"松澤委員","kind":"提案","question":"今、うちの須藤委員のほうからスポーツ振興基金をつくりたい、八潮に駅をつくりたい、基金をつくりたいという話もありましたけれども、せっかくこう自由討議をしてやりましょうというのですから、私たちの提案をこの場で議論していただいて、まだ半年以上ありますから、この行革委員会の中でしっかりとこれをつくるという提言をして理事者にぶつけていきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問・要望","question":"自由討議、もう平成２６年３月末現在で基金額が７２９億円余ぐらいあります。これで、これはいいのだけれども、利子収入等の合計額が約４,５８２万円ですよ。だから、こういう見方も一部あるということも、これは特にため込みとおっしゃっている方についてはご理解していただきたいのだけれども、４,５８２万円という評価は品川区はどう見ているのですかということ、これだけお伺いしたいと思います。","respondent":"本城企画財政課長","answer":"確かに、今利子の状況がこの間ずっと低い利子が続いているところですので、そのような中でかなり１０年、２０年さかのぼったものと比較して、基金から生じる運用益としての収益が相対的に少なくなっている現実はあると思います。","voiceIndex":81,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問・要望","question":"というところで、今あると感じているということで、この委員会の中で討議をしていただいて、これだけの原資が今あるわけですから、それをいかにして合理的に増やしていくかということについても、大きなこの行革のテーマだと私は思うので、それをぜひこれからの中で検討課題にしていっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-039"},{"speaker":"若林委員","kind":"提案","question":"いわゆる全額寄付になっているはずですので、こういうものも活用というのですか、いわゆる区民の寄付との協働という意味でも、そこにしっかり区の施策のアピールも含めた新たなドッキングをさせるというのか、整理整頓をするというのか、有効活用するというのか、そういう基金で運用益をもっと幅を持たせてそういう地域福祉なり見守りネットワークなり。","respondent":"本城企画財政課長","answer":"こちらの基金については、今委員ご指摘のように、果実運用型として設置されたところです。ただ、一つは今のような形になっているのはリーマン・ショックの後の影響で、ペイオフの対策として定期預金から移行した形で今は利息がつかないところに確保しているものです。","voiceIndex":85,"id":"exchange-040"},{"speaker":"あべ委員","kind":"意見","question":"奨学金制度ですけれども、奨学金基金について語ろうと思うと奨学金制度の話になってしまうと思うのですよね。基金だけで考えるわけにはいかないと思うので。即答されなくても構わないのですけれども、ちょっとそれについて正副にお任せしますので。","respondent":"中塚委員長","answer":"よく検討させていただきたい。","voiceIndex":87,"id":"exchange-041"},{"speaker":"南委員","kind":"提案","question":"自民党から、あるいは公明党からも文化・スポーツ基金ということで提案があったのですけれども、議会としてこれから正副でこの問題をどういうふうに扱うかの提案があるのだろうと思いますけれども、しっかりと私たちも必要性も含めて検討した方がいいのか、しないのかも含めて、吟味をこの委員会としてもしっかりしてから決めると。そういうことで取り扱っていただきたいというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":46849,"voices":94}},{"id":"h26-20140827-18","meetingId":"h26-cm08","date":"2014年8月27日","dateIso":"2014-08-27","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"案を示していただいて、この間、私どもも会派の中でさまざまな議論を重ねさせていただきました。それが、要約としてしっかり全て網羅されてまとめられている案文であると考えておりますので、私どもとしましては、もうこの原案のとおりでよろしいかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これの受け取り方なんですが、この障害者スポーツというのはそういう方も含めたという解釈でよろしいかどうか、そこだけちょっと確認を。比較的重度の難聴者というのですか、耳が悪い方というのは、何気にスポーツ的には外されているケースが地域でもあるので、障害者の位置づけというのを、確認も含めて明確にしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"会場の周辺ですね、交通や会場周辺の駅のホームドア化、点字ブロック、音響信号、エスコートゾーンなど、バリアフリー化を進めてほしいという要望・意見を出させていただいたんですが、ここの中には残念ながら入っていないというところで、上の文章にも「やさしいまちづくり」とあるのであれば、この下のところに、しっかり東京都にやはり進めていただきたいところですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"津波に対して、あそこは会場が観客席が１万２,０００人でしたか、そういう中で、じゃあ、１万２,０００人の方々をどこにどう収容できるのかというところは、明らかにされていないと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"安全でやさしいまちづくりということで、一番初めのところにも、安全というのは、品川区内でやるときに、そこら辺のところを、ここの委員会がつくられて会場のことをみんなで議論していたのに、そこのところが一体どうなっていたのということにならないためにも、私はこれは求めておくことがとても大事なことなのではないかと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"しかも、その競技場の安全対策というのは、競技場そのものの安全対策という意味からも、競技場の整備そのものにかかわることだと思うので、そして、今、都議会のほうでもこのオリンピック・パラリンピック、同じような形というか、向こうは実際に行うほうですから、実際にやる側としてもっとさまざま議会の中で委員会がされていると思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう安全対策というのは、全ての会場で東京都がもちろんやらなければいけないことだろうという前提であるために、ここには個別の問題ということでは入れなかったんだという解釈ということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それであれば、またそういうところをこれからも明らかにしていくということは、前回の委員会の中でも委員長もおっしゃっていましたね。そういうところで、この対策がどういう対策をとられるのかということを、東京都のほうにきちんと明らかにさせていく。そしてまたそこの時点で、それが十分でないということであれば、改めてこの委員会としても要望を出していくということで捉えてよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあとは、そういうことであれば「安全で」というのをこの大もとのところに、この具体的なところはそういうことで全ての会場に関わるし、具体的なところが出てきた段階で、必要であれば要望していくということであれば、私はここの前文のところには「安全で」という文言を、「安全でやさしいまちづくりを進める」というところで一言入れていただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと何点か、この表現がよくわからないところを教えていただきたいのがあるんですけれども、３番の「スポーツ環境の一層の整備を企図し、ホッケーのみならず多目的な利用に適う構造とされたい」とあるんですけれども、これがどういうことを言っているのかをお聞きしたいのと、それから、４番の「潮風公園については」ということで、「しおかぜ橋の復旧を進め。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"「やさしいまちづくり」というのは、私たち共産党としてはずっとこれを取り上げて、ぜひ議論もしてほしいといったことで要望してきましたので、それを汲んでいただいて入れていただいたということだったんですが、私たちが要望しているのは、もちろん障害者にやさしいまちづくりとともに安全でというこの二本なんですけれども、それは安全でということを入れたから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、先ほどの議論の中で、あて先が局長であるし、それを進めているところであるし、前文の中にその意味の野球場の利用に関してとかということが書かれているので、その中から現状の利用ニーズというところで、既存の施設のことですという意味合いを含んでいるかなと、今のほかの議論の中で理解したんですが、例えば「既存の施設の代替施設」という表現のほうがもっとすっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"研修会について質問なんですけれども、品川区でスポーツで活躍している方々が集まって、講演会等もやっていただけるような話なんですが、ここにやはりメダリストの方とかが入って、現状の本当のやっている方が、例えばちょっとお話をしていただけるような機会があったらどうなのかなと思うんですけれども、その辺はいかがなものでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、もう話の中身では、私もそこには参加していましたけれども、そういうメダリストだとかアスリートを呼んでというお話もあったことはありました。","voiceIndex":32,"id":"exchange-013","title":"議員研修会の内容と所要時間"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。たまたま私は盲目の金メダリストのパラリンピックの河合純一さんとお話ししたことがありまして、そのときに盲目なのにどうやって前に進むのという単純なご質問をさせていただいたときに、コースロープを触りながらいくんだよと。でも、内容的には理解させていただいたので、この先、広げていただけるようなことがあれば、呼んでいただけたらどうかなと思いますので、その辺は要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"障害者スポーツを進めていくということで、普及啓発ということで書かれているんですけれども、１点、先ほど私が前段で質問したのにも多少かぶるのですが、この水泳教室とかいろいろやられているというのは重々承知しております。もしお答えできるのであれば、小学校３年生というのが何でこの学年で切ったのかというのを教えていただきたい。","respondent":"安藤文化スポーツ振興課長","answer":"第１・第３土曜日に学校があるので、わざわざこの第２・第４土曜日にしたわけなんですけれども、非常にいろいろな事業があったり行事があったりということで、参加もちょっとままならないということが現状です。","voiceIndex":35,"id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"いろいろ参加人数も含めてですけれども、昭和５７年からずっと変わっていないという話ですが、あれから３０年経っておりますので、ぜひ前向きにいろいろ幅広い年代で、もちろんさまざまな指導の仕方とかがいろいろ関わってくるかもしれないんですが、この２番の下に※のところにも書いてありますが、聴覚障害、ろうの方の指導は非常に難しいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"質問といいますか要望になるんですけれども、ぜひ荒井監督のお話、すごくいいお話が聞けると思いますし、僕もお話ししたときに、ああ、そういうものなんだというようなことがありました。例えばそのような機会というのは、これから設けていくお考え、そのような形で、いわゆる一般区民への障害者スポーツ、パラリンピックへの関心を持たせるような活動というのは何かとれないでしょうかというところです。","respondent":"安藤文化スポーツ振興課長","answer":"非常にためになって、子どもたちが非常に感激していたと僕は思います。そういうものも、実際にこれから２０２０年までの間に、品川区にある日立ソリューションズの方々に対して、そういうお話を区民の方に聞かせるような機会を設けていきたいと考えています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"障害者スポーツの普及ということで、こういったいろいろなプログラムをやられているということですけれども、この参加人数のところなんですが、それぞれ人数が書かれていますけれども、これはいろいろこういうのをやっていますよということで、対象の方に周知された上でこういう人数の方が参加されているのかなと思ったんですが、これは定員というわけではなくて、参加したい方が全員参加できる状況なのか。","respondent":"安藤文化スポーツ振興課長","answer":"周知・応募については、広報しながわだとかホームページを通じてお願いをしたり、必ず障害者７団体の代表の方、会長にはお話をさせていただいて、来ていただくようにご紹介しています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"今この水泳教室とかスポーツ教室とかということで、障害者７団体の方から意見、話を必ずお伝えして周知をしていますというお話でしたけれども、この障害者スポーツ教室については、意見を聞いてこういう形を今年やりますということですけれども、その７団体に限らなくてもいいですけれども、障害者の方からこういう意見や要望を聞いて。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で取り組まれたのが、実際には旗の台でスポレクの皆さんと地域で協力してつくり上げていったのが、この旗の台のものでもあるということです。ここら辺のところでいろいろ調査をしたり、７団体の方にもご協力をいただいた事実はあります。","voiceIndex":44,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう中でいろいろなことをやっていく中で、いろいろな方がもっと参加しやすいように、協力者、ボランティアとか、いろいろな方の協力を求める体制は、障害者福祉課などとの連携もあるかもしれませんけれども、どのような形でとられているのか。文化スポーツ振興課だけで、今、やられているような現状なのか、その辺のことをちょっとお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、スポーツ推進委員も先ほどこの裏面のこういう活動を独自にやっていますけれども、ここの３番、それから４番等で実際に指導していただいている人もスポーツ推進委員です。","voiceIndex":46,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。より多くの方々が本当にいつでも誰でもというその理念のとおりに現実が近づくように、そういったスポーツ推進委員を中心として、支援体制、実施の手厚い体制というのを今後とも充実させていただけるように要望させていただいて、以上で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、この資料をいただいても、障害のある方に広くスポーツをやっていただくということで、それは十分理解しました。逆に、品川区の中にある程度チームとしてやっているようなところというのは、何か区とつながりがあるんですか。そういうチームが逆に品川区に登録がされているのかどうか、その辺もちょっと教えてもらいたい。","respondent":"安藤文化スポーツ振興課長","answer":"個々には、今、言ったグラウンドゴルフですとか、ボッチャも種目ですので、個人的にやっている人はいるということは確信しますけれども。","voiceIndex":49,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、見ていて気づいたんですけれども、知的障害者スポーツ教室というのは、これはスペシャルオリンピックス関係という感じなんですか。知的障害者のスポーツというのは。","respondent":"安藤文化スポーツ振興課長","answer":"ただ、３年ほど前ですけれども、品川区の総合体育館で、都のスペシャルオリンピックスをやった経緯はあると。そこにたまたま品川区の水泳教室にいた方が参加したという事実はあります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何年か前、七、八年前かな、長野で１回冬のスケートなんかをやったのがあったんですね。何か品川区としてもその辺つながりがとれればそういうこともやっていってほしいと、今、これを見ながら思ったんですが、今後チャンスがあったら、その辺もつないでもらいたいと思いますが、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そうですね。今後あらゆるチャンネルを我々も持ちまして、障害者スポーツの普及・啓発に努めていきたいと考えています。","voiceIndex":53,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これをもっと回数を増やしてほしいだとか、そういう要望はどうなのかをお聞かせいただきたいです。この参加人数というところは、水泳教室は募集をして４５名という定員になると思うんですが、抽選に漏れるということもあるともお聞きしたんですけれども、そこら辺の希望とこの実態というのがどんな状況になっているのか、その実態について、まずお聞かせいただきたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"水泳教室も、いろいろな健常者の水泳教室もやってあります。それで、荏原文化センターでもどこでもやっていますけれども、１つは回数を決めて毎週１回、５回のコースだとか、１０回のコースだとか、そういうのが健常者は多いんですね。","voiceIndex":55,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この水泳のところでは、これは区が企画をしている水泳教室ということだと思うんですが、それ以外のところでも、民間でも障害の子どもたちの水泳教室だったりとか、民間でもやっている部分というのがあると思うんですけれども、先ほどは鈴木真澄委員のほうからもありましたけれども、区として。","respondent":"安藤文化スポーツ振興課長","answer":"水泳に限っても、民間のほうで障害者を対象に水泳教室をやっているだとか、どの程度本数があるかというのはつかんでございません。","voiceIndex":57,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしましたら、先ほど課長のほうから、実は平成７年にということで、プログラムをこれだけの冊子としてつくられていたというところでのご尽力があったんだろうなと私は思うんですけれども、平成７年というともう２０年近く前になりますので、改めてこのパラリンピックを機会として、障害者スポーツを品川区としてどう充実していくかというビジョンというかプログラムを。","respondent":"安藤文化スポーツ振興課長","answer":"それで、ここにも書いてありますけれども、やはり私ども小さな現場の最前線の自治体というのは、競技もそれは重要かと思いますけれども、とにかく健常者、障害者関係なく、地域でもっていつでもどこでも誰でもできるという社会を目指しましょうという理念のもとに。","voiceIndex":59,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、私は改めて、せっかくこのスポーツ振興ビジョンという形でつくられているわけですから、この中にもぜひそこら辺のところは位置づけていただいて、その平成７年に障害者スポーツプログラムをつくられて、そしてそれを実現させていくためにずっとさまざま努力をされてきた、そのさらに上に立ったところで、今の時点で、このパラリンピックを契機に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ご案内ありがとうあります。何が言いたいかというと、逆に紹介しないでいいよと言いたい。開会式は議員が行くためにやるのではないのだし、出席していただいた方に、議員が例えばこれだけ行って、これだけ長い時間紹介したってしようがないと自分はそう思っているもので、その辺よく考えておいてもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろな委員会のご案内をいただいても、例えば福祉施設だとか何かのオープニングがあっても、そんなにこだわっていないというと変だけれども、行くのは行きます。だけど、あまり議員として紹介する必要はないのではないかというのが自分の考えなので、統一していない意見なので、ちょっとそこら辺だけ頭に入れておいていただきたいと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28578,"voices":75}},{"id":"h26-20140916-6","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"区民委員会","time":"午後１時００分～午後４時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":2871,"voices":11}},{"id":"h26-20140916-7","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"厚生委員会","time":"午後１時００分～午後３時１４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の品川児童学園の改築","agenda":"の品川児童学園の改築","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"このサービスは、例えば東京都の事業であるとか、国の事業だということが当然あります。だから、そういうことに対して、行政はどう対応していくのかということが、せっかく施設をつくっていくわけだから、立派なものをつくっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"こういったことを組み合わせながら、子どものダウン症ならではの特性で、療育まではいかないかもしれませんが、必要な専門的な相談と、その機能を高める工夫、そういったものにつきましては、新しく改築したこの場所でも、そういった専門相談を活用しながら。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"今、お話があったところで、個々具体的なことになると、いろいろなケースに分かれるので簡単には言えないけれども、ただ私たちのところには、やはりケアマネジメント体制が十分ではないということが聞こえてきますので、せっかく改築していくのであるならば、その中で、いろいろな団体のご意見を聞きながら、例えば、新しい制度を構築する必要があるかもしれない。","respondent":"中山障害者福祉課長","answer":"今年、療育支援ネットワークは、このまま継続して行っていきますので、いただいた北海道千歳市のモデルなども参考にさせていただきたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"意見","question":"さまざまな医学の発展で、障害が早く見つかる可能性が相当高くなってきたのです。だけれども、それを行政がどうサポート、バックアップしていくのか。私たちの思いとしては、せっかくこれをつくっていくのであれば、今言った、お話もさせていただいた課題も含めて、いろいろな観点で物事を見つめていっていただいて、中身は充実したものをつくっていただきますようにお願いします、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"何点か伺いたいと思います。それから、障害児なのですけれども、今想定しているとすれば、何歳から何歳くらいが対象になるのか。それが３点目。それから、４点目ですけれども、Ａ３版の２．事業内容およびコンセプトの下に図があるのですけれども、これで２階のところの就労継続支援Ａとあるので、いわゆる就労継続のＡ型と捉えていいのかどうか、それを教えてください。","respondent":"中山障害者福祉課長","answer":"(2)の高齢化・重度化に対応した支援というところでの年齢、あるいは対象者ということになりますが、年齢につきましては、大人の施設ということで、逆に１８歳以上の方であればどなたでもということになってまいります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"(1)は対象の年齢はわかりました。そうすると、精神も含めて、あらゆる対象となっているものは２のほうの相談支援センター・訪問系サービス、それから地域活動支援センター、それからショートステイはどうなのか、ちょっとその辺がわかりづらいところもあるので、もう１回教えていただきたい。","respondent":"中山障害者福祉課長","answer":"ほかの方と混ざっての、例えば趣味活動ですとか、いろいろな講座への参加ということが難しいようであれば、やはりたいむのほうの機能で行っていくことがいい支援につながるのかと考えております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。そうなると、小学校に上がってから、中学校、高等学校と、その間のところだけが、どうしてもここと切り離されてしまうような形になると思うので、先ほど伊藤委員からもありましたけれども、今、いろいろやっていらっしゃると思うので、そこをスムーズに連携をとってやっていくことが非常に大事になると思いますので、またその辺は動きがありましたら、教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"４．運営方法のところで、指定管理者制度により運営ということで、今のまま継続させるのではなくて、新たにまた業者を選定していくということですけれども、障害者の団体の方や親御さんたちから、直営に戻してほしいという声を、今伺っています。そういった声は、区のほうにも直接きているのでしょうか。それを知ったうえでどうお考えか、お聞かせください。","respondent":"中山障害者福祉課長","answer":"私のほうにも、直営で運営しないのかというお声は届いております。ただやはり、これだけの大きな施設を直営でというのは、なかなか現実的に難しいところもありますし、支援の中身というところで、法人の人材の活用ということも必要になってくると考えています。","voiceIndex":15,"id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、ぜひとも考えていただきたいと、私は思います。これは要望です。それから、先ほど児童には、計画を立てる、計画支援員をつける仕組みはないような話に聞こえたのですけれども、子どもには、計画を策定する支援員はいないのですか。","respondent":"中山障害者福祉課長","answer":"来年度に向けまして、このままでいいとは思っておりませんので、子どもの長い将来を考えたときにも、継続的に支援がつながっていくような計画相談の導入につきましては、引き続き努力をしていきたいと思っているところです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"計画を立てる計画支援員が、どこの地域を見ても足りないというのが、全国的にあると思うのですけれども、先ほどもほかの委員からありましたけれども、追いついていかないのではないかと思うのです。それを上回る相談があるから仕方ないではなくて、そこに合わせて支援員をさらに増やしていくためには、どう考えているのか、もう一度お聞きしたいです。","respondent":"中山障害者福祉課長","answer":"研修なども行いながら、支援力を高めて、その計画相談に着手できるような準備を進めてまいりたいと考えております。","voiceIndex":19,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"子どももそうですし、大人の部分も、今まだ足りないという状況なので、本当に足りないと思っているので、ここをスピードアップさせて、一人ひとりに本当にその人に合った計画がしっかり立てられるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"ショートステイのところで、介護力の変化など緊急への対応力強化とありますが、やはりここら辺ももう少し具体的に、これからをどうしていくのか。とても大きな建物ができ上がるので、かなり皆さん期待をしているのではないかと思うのですが、その辺を教えていただきたいということ。その三つを教えてください。","respondent":"中山障害者福祉課長","answer":"実際には、小さな子どもたちになりますので、通園の部門で言えば、送迎バスがきて、その後、指導員と一緒にエレベーターを使って３階まで上がっていくような形にはなろうかと思いますが、八潮こみゅにてぃぷらざに仮移転をするときには、あちらの地域への説明。","voiceIndex":22,"id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"こみゅにてぃぷらざに関しては、単独ではない分だけ、本当にいろいろなご苦労があるかと思いますけれども、その辺は上手にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"すみません、２点ほどお願いしたいのですが、一つは、先ほどの児童発達支援センターの通所定員のところなのですけれども、小学生までが対象ということですけれども、八潮にピッコロがありますよね、あそこに通っているような方で、あそこが足りないときに、ここは使えるのかどうかということが一つ。","respondent":"中山障害者福祉課長","answer":"その方の状態によってはなかなか、例えば介護サービスでいうところのデイサービスのほうにスムーズに移行できるかどうか、そういったことはあろうかと思いますが、原則的には、そういったことも意識しつつ、ここに在宅介護支援センターも入りますので。","voiceIndex":25,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"ここのところで、例えば障害児のハンドブックといったらいいのか、さまざまなサービスの提供、本当に入り口のものをつくっていただいて、ここに置いてさえいただければ、それがどんなに年数が変わったとしても、品川区はこういうサービスがあります、しかも、品川児童学園が改築された後は、相談支援センターが多分中心になっていくと思われるから、そこにそういうしおりがあれば、より有効的に活用されて。","respondent":"中山障害者福祉課長","answer":"障害児向けのサービスのハンドブックをつくるかどうかというところは、ひとつ課題として受けとめさせていただきまして、最初の赤ちゃんの相談というのが、保健センターからスタートしますので、保健センターとも相談しながら。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"の水痘、高齢者肺炎球菌ワクチンの定期予防接種化","agenda":"の水痘、高齢者肺炎球菌ワクチンの定期予防接種化","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"一つ教えてほしいのですけれども、高齢者肺炎球菌ワクチンですけれども、定期予防接種化というと、何か無料のイメージがありまして、えっ、４,０００円なのかという感じがいたしました。それからもう１点、先ほど、１月から３月の対象外の方云々とおっしゃっていましたが、この方たちは、一応６５歳の人と見なして、自己負担４,０００円で受けられるということなのでしょうか。この三つを教えてください。","respondent":"佐藤保健予防課長","answer":"最後の、１月から３月の方ですが、これは本当に今回特出しということで、従来のご説明で待っていただいた方がありますので、特別な対応としています。","voiceIndex":38,"id":"exchange-015"},{"speaker":"山元委員","kind":"質問","question":"一応２３区統一というお話がありました。仮に６６歳から７０歳まで待って、それを受けて、自己負担４,０００円で受けるということで、これは品川区独自ではなく、これもやはり２３区統一というか、皆さん、各区もそういう対応をしているのですか。","respondent":"佐藤保健予防課長","answer":"実際には、まだ１０月の制度なので、はっきりは聞いておりませんが、一部任意予防接種を残すという話も、区の課長会の中では聞いておりますが、多くの区は、定期予防接種になりますので、国の制度で５年ずつ接種するというような形で実施されると聞いております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この間、いろいろ医師会の人などからお話を伺うと、やはり５年くらいワクチンの効果があると。国は定期接種なので１回となっていますけれども、そういう中で、区として、補助するとかしないとか関係なく、そういういわゆるお問い合わせがあったときには、どういうお答えをしていくのかと思うのですけれども、その点をお聞かせください。","respondent":"佐藤保健予防課長","answer":"ただ、この５年間、ここに書いてありますように、３１年目以降は、今後の状況を見てということになっておりますが、この５年間をかけて、国の部会のほうで審議すると聞いておりますので、そちらの結論を待って、２回目接種についても。","voiceIndex":42,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"高齢者肺炎球菌ワクチンのほうで、今、年齢のこともありましたけれども、国の方針で５歳刻みとは、またかと私は思ったのです。今回始まるというところでは、６６歳とか、これから打ちたいと思っている方は、希望者は接種できるようにしたらいいのではないかと思いました。この間、平成２５年度でもいいのですけれども、接種を受けた方というのは、どれくらいいらっしゃるかわかりますか。","respondent":"佐藤保健予防課長","answer":"実施ですけれども、今年度のデータは、すみません、持ってきていなくて申し訳ないですが、昨年度の実績を申しますと、平成２５年度２,２３８件というのが、１年間の実績です。","voiceIndex":44,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"流通量とか、ワクチンには量があるからということも、そうなのでしょうけれども、定期にしたところで、どれくらい増えるかというところはあると思うのですけれども、そんなに足りないもののですか、ワクチンというのは。","respondent":"佐藤保健予防課長","answer":"ただ、一時的に大量に増やした場合、生産ラインを一気に増やすことになりますので、５年間分だけ、この一、二年の間に生産量を増やした結果、その後また少なくなってしまいますので、また生産ラインを下げることになりますと、ほかの予防接種の生産量との兼ね合いもありますので。","voiceIndex":46,"id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"半年経ったら終わってしまうのです。それがまず一つ。それから第４点目として、先ほどからワクチンが足りなくなるとたびたび言及されているのですが、今、プレベナー１３という１３価の肺炎球菌ワクチンが、高齢者にも使っていいということが承認されたのですが、この前も聞いたのですが、ちょっとはっきりしなかったのですけれども、それの位置づけはどうなっているのでしょうか。その点、お願いします。","respondent":"佐藤保健予防課長","answer":"個別の通知についてですが、３歳、４歳の方に限らず、１歳から４歳の方全てについて、対象者には個別で予診票を送って通知をいたします。その中で特別、５歳に近い方につきましては、任意予防接種の方もご通知しながら、個別にお知らせをする予定にしております。","voiceIndex":51,"id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それから４番目なのですけれども、１３価のプレベナー１３が承認はされたわけですから、こういうワクチンもあるということで、今後、品川区の高齢者の肺炎球菌ワクチンに対する戦略というか、ストラテジーの中でどうやって位置づけていくかということを聞いているのです。今現在、入っていないということは承知しているのです。","respondent":"佐藤保健予防課長","answer":"１番と２番については、そのとおりです。同時接種につきましては、特段こちらとしてお知らせを配るというような予定はございません。","voiceIndex":53,"id":"exchange-021"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"平成２７年４月を目指して、予定どおり猶予を持たずにやっていくというお話で、それは一定程度理解できるのですけれども、そのうえで、利用者負担の軽減とあわせて、運営事業者の安定的な経営の部分も、というお話なのですけれども、なかなか両立できるかという中で、まだこれからなのでわからないのですけれども、利用者が今までと同じサービスを受けるには。","respondent":"永尾高齢者福祉課長","answer":"図の点線の部分です。申し訳ありません、説明しなかったのですけれども、この点線は、区のほうで振った点線です。","voiceIndex":60,"id":"exchange-022"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。それから、平成２７年４月に向けてこれをやっていく中で、区のもうちょっと細かい計画は、いつくらいをスケジュール的には目指していらっしゃるのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"そのお話の中で、今、案を固めているところです。９月以降に、訪問介護事業所連絡会、通所介護事業所連絡会、居宅支援事業所連絡会と、９月から１０月にかけて行っていく予定になっています。１０月３０日には、介護保険の事業計画の策定委員会が予定されております。","voiceIndex":62,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"確認","question":"何点か、お聞かせください。そうなれば、これから新しいサービスを提供しているわけですから、財源の手当は何かつくのでしょうか。そのことをまずお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"急増する高齢者に対応するということですけれども、やはり全国で見ると、全国一律の介護報酬でやると、いろいろ差が出てきてしまうということで、ロスがかなりあるというところから、国としては自治体の状態に合った介護報酬の額を決めるべきというところで、今回。","voiceIndex":64,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"お伺いしたいのは、訪問型サービスＡ、Ｂ、Ｃ、緩和した基準によるサービス、住民主体による支援、短期集中予防サービス、という新しいものが入ってきたことについての簡単な品川区のご説明をいただきたい。訪問型サービスＡ、Ｂ、Ｃ、通所型サービスＡ、Ｂ、Ｃと、それから生活支援サービスの内容を、かいつまんでで結構ですから教えていただければと思います。","respondent":"永尾高齢者福祉課長","answer":"こちらは、要支援者と非該当者を対象にして、基本チェックリストで基本チェックを実施したうえで、訪問介護を行っております。週１回で利用者負担が１,２００円、週２回で利用者負担２,５００円ということで、現状も行っているところです。","voiceIndex":66,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、今、ある程度展開されている福祉の事業の裏付けとして、介護保険制度改正の内容を適用していくという考え方でいいのですか、その確認が一つ。それから、どうしても新しい事業が入ってきていますよね。そうすれば、いわゆる介護保険料の改正も少なくて済む可能性があると思うのですが、いかがでしょうか、お答えください。","respondent":"永尾高齢者福祉課長","answer":"そこをうまく、例えば、いろいろなお教室があったときに、募集の時期が決まっていたりとか、今はチェックリストをやらないでやっていたりとか、いろいろさまざまになっていますので、そのあたりを、来年度調整をしながら。","voiceIndex":68,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これから、一時的にずっと高齢者が増えていくわけですから、サービスの提供自体は増加する一方である。ただ、これから将来にわたって、やはりその他の生活支援サービスにあるように、住民ボランティア等が行う見守りとか、どうしてもやはり地域に人材を求めていかないと、全ての福祉施策が支え切れない時代が必ず来ると、私たちは思っているのです。たしか、新聞配達員と品川区が協働しましたよね。","respondent":"永尾高齢者福祉課長","answer":"品川区は品川区のこれまでやってきた蓄積をうまく生かしながら、この制度への対応をしていき、最終的にはやはり区民の方々が安心して住めるところを目標としていきたいと思いますので、よろしくお願いいたします。","voiceIndex":70,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"新たな総合事業になっていくと、私たちはずっと国会でも反対をし、議論もしているのです。平成２７年度に移行させていくというのは、先ほどほかの委員からもありましたけれども、なかなか大変なことですよね、大きく変えていく問題ですから。それに踏み出す自治体というのは、２３区で見て、どれくらいあるのか、わかりますか。","respondent":"永尾高齢者福祉課長","answer":"直近で、品川区で電話調査したところ、２３区ではっきりやると言ったところは、品川区だけです。ただ、検討しているところは２区くらいあるように聞いているところです。","voiceIndex":72,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"品川区のみと、それで検討されている区が２区と、何でなかなかほかの区は移行していかないのか。そして、何で品川区は、たった１区ですけれども、移行していこうと思ったのか、お伺いしたい。","respondent":"永尾高齢者福祉課長","answer":"実際にこれを１年早くやれば、その分介護報酬、少し端数を調整しようかと今思っているのですけれども、それによって、逆に介護保険料のほうは多少安くなると見込んでおります。","voiceIndex":74,"id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、品川区の介護保険の中に、全く同じ名前の介護予防・日常生活支援総合事業の利用の流れというのはもう書いてあるのですけれども、ではここにほとんど入ってくる、ここの以外の新たなものというのは、この表でいうとどこになるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今、確実に考えているのは、予防給付の訪問介護と通所介護を全部地域支援事業に移すということは、確実にやろうと考えています。","voiceIndex":76,"id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それとも、今までどおり、専門家によるサービスになっていくのかは、どうでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、その方の状態と要求されている内容によって、訪問介護と訪問型サービスＡに振り分けていくということ、それから時間数、そういうところから振り分けようということで、今はまだ事業者とも検討している最中ですので、まだ確定したことは言えませんけれども。","voiceIndex":78,"id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、区としては、どういったものがボランティアなり、ＮＰＯなりになっていくものかと見立てていらっしゃるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、住民主体による支援というのを、この後、検討していくのですけれども、これにつきましては、ボランティアという形になるかと思います。","voiceIndex":80,"id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"利用者は安くて済むかもしれないのですけれども、事業者は、これから要支援になる方がみんなこちらのサービスになっていくと、本当にやっていけないという不安の声がもう今から出ているのですけれども、そういったところにはどのように応えていくのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"現在、９カ所で実施しているところです。経営上のことで、特にご相談とかは、今のところは聞いておりません。事業者は、いろいろな情報が先に走っていて、非常に不安になっているところもあるかと見受けられます。","voiceIndex":82,"id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはり、そうは言っても、仕組み自体が事業者になかなか利益が生まれない仕組みになっていますよね。ですので、どうしても、先ほどもパーセントを抑えると言われていたと思うのですけれども、そういうふうに抑えていけば、事業所は採算が取れないという状況に陥るようなことが、仕組み上、あるのではないかと思うのです。そこら辺があっても、対応していけるというものがあるのでしょうか、品川区独自で。","respondent":"永尾高齢者福祉課長","answer":"高齢者の人口はどんどん伸びていくわけですので、基本、現状維持プラスアルファ、約３％ということであれば、現在の事業者自体は、お客様がいなくなるということはないのかと思います。","voiceIndex":84,"id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"これから高齢者が増えていくというのは事実だと思うのですけれども、そこに専門的な担い手を増やしていくことが、一番安心して進める方向ではないかと思うのです。品川区には介護福祉専門学校がありますけれども、それ以上に、高齢者は増えていくわけですから、これから若者が希望を持って介護職に就けるようにしていくことを、国に求めていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"人材確保は、非常に重要な問題として、国のほうも検討はしているところであるかと思います。区の立場としては、品川区にいい人材が、きちんと担保できるということが一番大事であると考えています。人材確保ということで、品川区の社会福祉法人は、離職率が非常に少ないです。","voiceIndex":86,"id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今やられている介護予防・日常生活支援総合事業には、どれくらい予算が組まれていたのでしたか。それが、今、ご説明があったように、通所と訪問が、またこういうほうに流れてくるにあたって、同じ予算内でやるのか、もちろん上がっていくのでしょうか。それがどれくらいで、進めていこうとしているのか。","respondent":"永尾高齢者福祉課長","answer":"ここについては、今、検討している段階で、予算要求等はこれからという段階ですので、この制度改正のこともにらみながら考えていきたいと考えています。","voiceIndex":88,"id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"築き上げた経験とか、信頼関係とか、そういったところで、軽度でもさらに重度化しないためのＳＯＳに気付くというのが専門職の目線だと思うので、これを、簡単だから掃除や洗濯ならボランティアでできるかということで回していくというのは、やはり重度化を招いていくことになっていくのではないかと思うので、品川区は先駆けて進めている区で、しかもたった１区で先行して移行していくということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-037"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"実際にデング熱かどうかということは、今、代々木公園近くに行ったかどうかということを問診しているのですが、例えばデング熱の場合、白血球が減って、血小板が３日目から４日目に減るとかという報告があるのですけれども、区内の医療機関が、デング熱ではないかと思われる患者がいるときの対応は、保健予防課としてはどのようにしたらいいとお考えなのでしょうか。","respondent":"佐藤保健予防課長","answer":"現在、区も東京都と連携をして対応をとっておりまして、現在の対応ですが、代々木公園周辺にしばられずに、外堀公園ですとか、新宿中央公園等を含めました地点で、そこに行った方、それから、それらの場所で蚊に刺されたかという。","voiceIndex":99,"id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、熱が続いていて元気がないとかという場合は、血小板が少ないという症状を疑うような出血斑だとか何かがあった場合は、保健所へ連絡すればいいということなのですか。例えば、具体的に熱が何日間か続いて、患者からデング熱が心配だと言われた場合は、保健所としてはどのように対応したらいいとお考えなのでしょうか。","respondent":"佐藤保健予防課長","answer":"したがいまして、これ以上の、３７度５分ですかと、３６度８分ですとか、そういうような発熱の方々がデング熱であったかどうかということについては、現在の段階では、恐らく東京都のほうは検査は受けないと思いますので、個別の症例で個別の対応をしますが。","voiceIndex":101,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":43061,"voices":107}},{"id":"h26-20140916-8","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"建設委員会","time":"午後１時００分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２「報告事項」を聴取いたします。 初めに、(1)の広町一丁目周辺地区地区計画","agenda":"の２「報告事項」を聴取いたします。 初めに、(1)の広町一丁目周辺地区地区計画","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"広町一丁目周辺地区地区計画区域、１７.２haとなっていますけれども、今回の提案はＣ地区のことですね。こちらはまだ何にもという話だったので、どの程度説明を行っているのか、その辺を教えてください。","respondent":"溝口都市開発課長","answer":"そういった中で、まちづくり説明会、または都市計画法に基づく説明会をやっていきますので、十分内容等には、また戸別訪問する際にもただポスティングするだけではなく、個別にお話をする中でご理解いただきながらこれまで進めてきたというのが現状です。","voiceIndex":11,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"Ｃ地区はまだまだ先で、具体化していませんというような中身で、第一三共のあの地域と、道路を広くしてほしいとか、そういう話はあったのですけれどもということだったので、どのくらい伝わっているのかなととても疑問に思ったのですけれども、Ｃ地区は線路のこちら側とこちら側、日本ペイントのほうと二つに分かれていますけれども、権利者の数とか別々に教えてほしいのですけれども。","respondent":"溝口都市開発課長","answer":"そのうち、住宅としては七つになっておりまして、それ以外は戸建て住宅としては住宅で使っているのが１２軒、集合住宅としては１軒あるような形の土地利用になっているものです。","voiceIndex":13,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"いま一つわからないのが、日本ペイントのほうの境がどの辺なのかなと。この図からなかなかわかりにくいのですけれども、ここはほとんど日本ペイントの工場、建物と考えていいのですか。共同住宅とかがあるのか、ないのか。","respondent":"溝口都市開発課長","answer":"日本ペイントの敷地につきましては、この図でいきますと２枚目のＡ３の「地区現況」という図を見ていただければ一番わかると思うのですが、東側に、右側ですね、こちらに１本、目黒川を渡る通りがあります。","voiceIndex":17,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"確認","question":"ということは、Ｃ地区のところだけ広い部分の中に先ほどあった住宅７とか、戸建て住宅１２軒とか、集合が１軒ということで理解はよろしいですね。そこを確認したいのと、ここの方たちの今後の権利というか、暮らしが、新しい地区の整備計画の中でどう変わっていくのか、どう守られていくのかというあたりを具体的に教えてください。","respondent":"溝口都市開発課長","answer":"集合住宅の１軒につきましては、集合住宅というか寄宿舎として使われておりまして、これは第一三共がお持ちになっております。事前に、地区計画をかけるに当たってこれは不適格になりますので、今後同じようなものができないような形になります。","voiceIndex":19,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"今までの経緯のところで、２５年１１月１８日品川事業協会、関係事業者との意見交換、ここの、前にも伺ったかもしれないですが、品川事業協会、関係事業者というのがどういう方なのか、ここでどのような意見交換がされたのか、あと、１２月１２日のまちづくりの説明会には参加者はどのような状況だったのかと、あとＣ地区の策定に向けての意向把握とあるので、この中身がどのような中身なのか、あと。","respondent":"溝口都市開発課長","answer":"続きまして、今年５月８日に開催させていただきましたが、都市計画原案の説明会につきましては、これも午前、午後の２回開催いたしまして、合計１０名の方が参加しておりまして、Ｃ地区に対する質疑というのはありませんでした。","voiceIndex":21,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３回の説明会でそれぞれ１０名程度の方が参加ということですけれども、内容的にはご理解をいただいているというご説明だったのですけれども、冒頭お話ししましたけれども、地域の方でこの地区計画を変更するということについてご存じなかった方が複数いらっしゃったので、ぜひ私は、説明会３回をやったので終了ということではなく、これから公告、縦覧がありますけれども。","respondent":"溝口都市開発課長","answer":"今回、地区計画、まして制限をかける内容になっていますので、これまでもまちづくり説明会または１６条の説明会、いずれも戸別にうちの職員が訪問して、一軒一軒内容を説明しながら説明会等を開催してきているという経緯がありますので。","voiceIndex":23,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど土地、建物３９名地権者の方、建物１名で４０軒ということですが、では、４０軒の方、全てにきちんと伝わっているという理解でよろしいのでしょうか。","respondent":"溝口都市開発課長","answer":"繰り返しになりますが、４０軒の方たちに、地区外に住まわれている方もいますのでその人たちには説明会の資料を事前に郵送して、何かあればお問い合わせくださいという形で郵送しておりますし、地区内に住まわれている方については全てお会いしてご説明しておりますので。","voiceIndex":25,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"公告、縦覧と、あと広報があると思うのですけれども、どのようにされていくのか教えてください。","respondent":"溝口都市開発課長","answer":"そちらの中でしっかり周知を図っていきたいと思いますので、改めて、これまで十分、内容が内容なだけに区としてもできる限り住民の方たちに周知する方法を考えてやってきておりますので、改めて説明会等の開催というのとは考えておりません。","voiceIndex":27,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にします。広報紙、９月１９日に公告、縦覧が始まるのですが、いつの広報か教えていただきたいのと、記事の大きさがどの程度か教えてください。","respondent":"溝口都市開発課長","answer":"都市計画のほうで一括でやって、たしか９月１１日か１日の広報には、事前には必ず周知しております。広報記事については、当然紙面の関係もありますし、お知らせ記事なのでそんなに大きくはとっていないとは思いますが、１日に載せていると思います。","voiceIndex":29,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１日。最後に２点だけですけれども。広報紙に載っているのは本当に数行です。意見をきちんと聞くという姿勢をいつでも、どこでも持っていただきたいのです。ぜひそういうところも今後に活かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"Ａ３の裏側のところでお聞きしたいのですけれども、(1)のところで制限を強化するということですが、その理由として工場の操業環境を脅かされる可能性があるということで、これを希望している、制限を希望するというのは区ということなのですか、それとも地域の工場を営んでいる皆さん、工場というか企業の皆さんからそういう要望があったのか、そういうことなのか。","respondent":"溝口都市開発課長","answer":"工場等の操業を守るための用途制限の考え方です。一つは、大きくは品川区のまちづくりマスタープランの中でも内陸部に残る唯一の工業専用地域の用途指定がされてきて、これまで工場の操業環境を維持、保全してきた地域。","voiceIndex":32,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"経過のところを、Ａ３の裏ですけれども、こういう理解でいいのかというところで、平成２３年１２月１９日に都市計画の決定があって、Ａ地区とＢ地区は住宅地というのは多分ないところであるからすんなり行って、Ｃ地区に関しては４０軒の権利を持っている方たちがいて、だから引き続き検討というところになったと思うのですけれども、当時から現在にかけて例えば業者による共同住宅へのアプローチ。","respondent":"溝口都市開発課長","answer":"ただ、１番は、ＪＲの敷地が線路沿いに広くあります。その辺が売られるのではないかといった話が危惧されて、うちに何か情報はないのかというので地区の方からご相談を受けたことはありますが、実情としては特にそういった動きが目立ってあったというわけではありません。","voiceIndex":34,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特に具体的な動きがあって、都市計画という話ではないということはわかりました。先ほどほかの委員からもありましたけれども、制限がかかることによってまさに自分の権利が、地権者の方は権利が制限されることになると思いますので、そこのところの説明についてはまたしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"}]},{"id":"topic-02","title":"の大崎駅西口地区および周辺地域におけるまちづくり","agenda":"の大崎駅西口地区および周辺地域におけるまちづくり","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"点線のエリア、都市再生緊急整備地域のエリアの面積をお知らせいただきたいのと、大崎三丁目地区と大崎西口駅前地区の進捗状況、今どういう状態にあるのか。先ほど少し説明があったのですが、もう少し詳しく教えていただきたいのと、整備地域からはみ出してというか、新たに広がっている地域の地権者、組合員数を改めてそれぞれの地域で教えてください。","respondent":"溝口都市開発課長","answer":"ですから、大体７割ぐらいの建物の方たちが準備組合の取り組みに賛同されて、組合に参加しているという状況です。","voiceIndex":42,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"ほかのところにいきますけれども、百反ずい道の工事ですけれども、ここのところすごくゲリラ豪雨が多かったりするので、地域の方が、雨がいっぱい降ったときの排水の対策はどうなっているのかという心配の声が一つ出たのと、あと、Ａ３判の一方通行ですが、前伺ったときは十分、先ほど広町一丁目の工場地帯の方には十分伝わっているので意見を聞いておりますというお答えをいただいたのですが。","respondent":"稲田道路課長、溝口都市開発課長","answer":"私から百反ずい道の豪雨対策ですけれども、あそこは確かにトンネルで地下に低くなっているという状況ですけれども、あそこにポンプの設備を設置しておりまして、水がたまってくればそこで強制的に排水をしていくです。それと、次に一方通行化の周知の件ですが、これも説明会等の中、また戸別配布する中でも個別に説明しながらやってきております。ただ、中には確かに不便になるなというご意見はいただいているものです。","voiceIndex":44,"id":"exchange-015"},{"speaker":"原委員","kind":"意見","question":"私からは、ほかの委員からも出ているのですけれども、大崎三丁目と西口駅前のところで、駅前のほうが気運的には大分、オリンピック前ぐらいまでというような、ほかの大崎のエリアの多分建設関係の流れなのでしょうけれども、気運が上がっていたのですけれども、ここというのは昔の大型マンションが幾つかあろうかと思うのですけれども、それで少し鈍っているというような話が入ってくるのですけれども。","respondent":"溝口都市開発課長","answer":"そういったものを一つ課題を解決していく手法として市街地再開発事業という形を選んで、地域の方たちが今まさに今後それに向けて地区内の方含めていろいろ協議しながら進めていくものと考えているところです。","voiceIndex":47,"id":"exchange-016"},{"speaker":"原委員","kind":"意見","question":"そうしましたら、先ほど私、聞き漏らしたのですけれども、大崎三丁目地区は８９％ということですけれども、組合が立ち上がったばかりですので今後どうなるかわからないけれども、組合に入っていない非会員ですね、この辺に対する対応。具体的に出ていなければそれでいいのですけれども、お教えいただければと思います。","respondent":"溝口都市開発課長","answer":"西口の駅前地区につきましてはまだまだこれから、準備組合が設立したばかりですので、今後マンション、今は１棟一つで考えていますが、その中でもいろいろなご意見をお持ちの方がいると聞いておりますので。","voiceIndex":49,"id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"ここに限ったことではないですけれども、再開発のときというのはお寺だったり、神社だったり、公共施設だけではなくて、そういった地域に密着というか、歴史がつながっている、展開をしている形があるものですから、その辺のところも十分に配慮をお願いしたいなということで、これはお願い事項にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の考え方をひとつ教えていただきたいのと、先ほど聞くのを忘れてしまった百反ずい道のところの降雨対策ですけれども、ほかでも心配されるけれども、モーターで出すという、電気を使う場合の停電の対策とかはきちんととられているのかどうか、その辺も聞かせてください。","respondent":"溝口都市開発課長、稲田道路課長","answer":"ですから、都心の拠点整備地域、拠点の位置づけがあるところを中心にやっていくものですので、やみくもに広げていくという考えはありませんが、ただ、今回。百反ずい道、そのほかのところもそうですけれども、まず、ポンプにおきましては停電で動くというのがなかなか難しいところはありますが、入れなくする。","voiceIndex":52,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"突っ込んでしまった場合はどうにもならないということですか。副都心という意味合いを持つと、せっかくエリアを決めたのに、エリアとはまた関係なく、関係なくと言っては語弊があるかもしれないけれども、さらに広がる可能性を、副都心という位置づけからすると持っているということでしょうか。そういうさらなる開発はやめてほしいという声はどうしたらいいのですか。どんどん広がっていくのですか。","respondent":"溝口都市開発課長、稲田道路課長","answer":"ですから、あくまでも一つは、品川区まちづくりマスタープランの中で示されております広域拠点、そういった拠点を中心に、市街地再開発事業を使ったまちづくりを進めていくと考えているものです。百反ずい道の警報に関する件ですけれども、まず路面より５cmで注意レベル、それから２０cmで危険レベルという水位の設定をしておるのですけれども、警報等が鳴りますと４階の災害対策危機室、それから我々の道路課。","voiceIndex":55,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事故というのは、最悪の事態というのはいろいろ想定外のことが重なって起きる、品川区内ではこれまでないと思いますけれども、降雨の状況で水没して被害が起きたというのは多分ないと思っていますけれども、今後、想像を超えた雨量がこのところ計測されているという意味では、十分な対策をお願いしたいと思います。私の正直な気持ちです。言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-021"}]},{"id":"topic-03","title":"の中央新幹線（東京都・名古屋市間）環境影響評価書の縦覧・閲覧","agenda":"の中央新幹線（東京都・名古屋市間）環境影響評価書の縦覧・閲覧","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ＪＲ東海ですね。すみません。ご説明いただいたのですけれども、環境影響評価書のあらましについての品川区の見解というのはあるのでしょうか。あったらお聞かせいただきたいです。","respondent":"三ツ橋環境課長","answer":"環境影響評価のあらましについての品川区の意見ですが、この全体の準備書について意見を出しております。したがいまして、あらましについての意見集約というのは特に法律上規定がございませんので、そちらについては評価書が出されたです。","voiceIndex":66,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改めて、すみません、前にあったのかもしれません。準備書に対する区の意見を聞かせていただきたいのと、今、品川区がかかわる部分はあるわけですけれども、実際ものすごく大きな事業に対して、自治体も含めて自然の保護団体とかは異論を唱えたり、見直しを求めている声が相次いで、ここのところ新聞でも、テレビでも取り上げられている。","respondent":"三ツ橋環境課長","answer":"しかしながら、東京都がまとめた意見を準備書に対しては出しておりますので、区としては東京都に回答しております。","voiceIndex":68,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"８割がトンネルである。総事業費が何と９兆円かかる。採算面はすごく甘い。運転士が乗っていない。最高時速５５０km、猛スピードで走るといった安全への懸念がすごく言われています。こういった指摘をもちろんご存じだと思うのですが、品川区はこの点をどう受けとめていらっしゃるのでしょうか。もう一点は、品川に与える影響をどう考えているのか、お聞かせください。","respondent":"三ツ橋環境課長","answer":"品川区に与える影響という部分ですけれども、リニア新幹線については国の施策で新幹線鉄道を具体的に実施していこうという考えですので、環境配慮には十分配慮していただきたいという部分はありますけれども、環境配慮を踏まえながら実施していくという形で異論はございません。","voiceIndex":70,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８割強が地下という、トンネルということなので、大問題となっているのが工事で排出される膨大な残土を一体どこに置くのか、東京ドームの５０杯分もあると言われている残土がどこになるのかとか、そういった面でも東京都に対しての影響もある、品川区に対してもあるのではないかと思っていますけれども、そういった面で、残土を移送したり、動かしたりする部分での車両とか、地下の水系、４０ｍ地下を。","respondent":"三ツ橋環境課長","answer":"今言われている発生残土置き場についてはあらましの１６ページにありますように、地域の発生土置き場等のところ、山梨リニア実験線の少し上の部分ですけれども、「なお、地域特性や発生土置き場の改変の規模等によっては」ということで。","voiceIndex":72,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もっと真剣に多方面で検討が必要だと思うのです。国会でほとんど議論されていないのです、これ。国会で議論されていない。なので、こういう大きな問題が事もなげにどんどん右から左に賛成で通っていってしまうこと、意見を述べないで、自治体もそうですけれども、区議会もそうですけれども、意見を述べないままに進んでいくことに対して懸念を感じているのですが、この点に関してはいかがでしょうか。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"意見については準備書の段階で申し上げておりますので、その段階では区長または東京都の意見というものは述べております。こちらの中央新幹線ですけれども、先ほど環境課長から冒頭でも説明させていただきましたとおり、「全国新幹線鉄道整備法」ということで、法律に基づきながら国策として進める鉄道事業ということで。","voiceIndex":74,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"終わりますけれども、自治体からも異論ややり直しを求めるような声が出ているところもあるので、ぜひ、今後のことも、工事の問題とか具体的になっていくことでさまざま問題が出てくると思うので、しっかりと物が言える自治体であっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-027"}]},{"id":"topic-04","title":"の区独自環境マネジメントシステムの概要と試行運用の開始","agenda":"の区独自環境マネジメントシステムの概要と試行運用の開始","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"資料を読ませていただいて、その中で、大きな別紙のところで、赤枠の一番下のところに「ＩＳＯ１４００１を認証返上し、区独自の取り組みとする事が、区の環境対策の後退と取られないよう」、このような記載がありますけれども、そのことについてお伺いしたいのですが、ＩＳＯを返上することについて伺いたいのですが、これは調べると３年ごとに認定の見直しというか、登録の変更に費用がかかったりとか。","respondent":"三ツ橋環境課長","answer":"２３区全体のＩＳＯの運用状況を調べましたところ、７月末現在ですと、今までＩＳＯ運用を実施していた大もと、品川区と同様のころに認証を取得したところが、平成十何年のころに認証したところが２３区中１３区ございまして、今現在。","voiceIndex":83,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"残り少ない区になっているということがわかったのですけれども、ここはお聞きしたいのですけれども、前の委員会でやっているかもしれませんけれども、費用というのは３年ごとのときに大体どれぐらいかかっていたのか、あと、事務的な手続の事務料というのですか、そこら辺の煩雑さというのがあったのかどうか、そこら辺を今回の返上の中で。","respondent":"三ツ橋環境課長","answer":"引き続き、事務の煩雑さという部分で、変更点の２番目にありますＥＭＳにかかる事務手続のスリム化。今までは例えば手順書が８種類ございまして、それが煩雑で、それを４種類に変えました。様式については３６種類もございましたので、そちらを９種類にまとめております。","voiceIndex":85,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"意見","question":"私も企業にいたときは、環境ではないですけれどもＩＳＯの担当をやったこともありまして、お金もかかるし、手間もかかるし、取得するまですごくお金が、逆にお金さえあればというところもあったのですけれども、そういう意味で、企業と自治体は役割が違うと思うのですけれども、一定の役割を終えたのかなという判断を自治体でもかなり多くしているのかなという印象を持っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-030"},{"speaker":"原委員","kind":"意見","question":"私は以前も委員だったので、前にも説明していただいたのですけれども、そのときも多分賛成したと思いますけれども、そのときと今と違って、実質想定値として、これはこれからなのでしょうけれども、節約というか節税というか、どのぐらいを想定しているのか、その辺について。今も数値の問題が出たのですけれども、もう一回お考えをいただければと思います。","respondent":"三ツ橋環境課長","answer":"節税の部分に関しては、外部審査の部分が大きいと考えておりまして、３年ごとの更新の１３０万円については、外部審査を受けないということで、その部分は節税になっております。","voiceIndex":88,"id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"非常に明快なご答弁ありがとうあります。ですから、今、あくつ委員が言われておりましたけれども、それによって逆に、今回こういう形になることによって、独自のものになることによって、区民の方々が心配されないような形での広報とか、広報だけではなくて啓蒙とかもお願いしたいので、その辺のアイデアがもしあれば動いていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"Ａ３の資料の赤枠の中の「ＥＭＳ運用状況の情報開示」ということで、区民への説明のあり方となっていて、赤文字のところで内部監査の報告書を原文でホームページ公開するということと、省エネ等の実績値を広報等へ掲載するということを考えております。","voiceIndex":90,"id":"exchange-032"},{"speaker":"大沢委員","kind":"質問・要望","question":"ＩＳＯ返上ということですけれども、今の情報開示のところで、ホームページ公開云々とか、取り組みはいいと思うのですけれども、ＩＳＯ自体を返上して新しい取り組みをするわけですけれども、ＩＳＯ認証を取得したということ自体も知らない区民の方が多いと思うのです。それに関してどういうふうに考えて、どういうふうに取り組まれて、これを大々的に花火を上げていかれるおつもりなのか教えていただきたい。","respondent":"三ツ橋環境課長","answer":"ＩＳＯの取り組みを区民の皆様自体がご存じないということでは、例えばホームページ上でＩＳＯの取り組みを今までこのように続けてまいりましたと。それから、区独自のＥＭＳへと変更してまいりますということをホームページ上で開示してまいります。","voiceIndex":93,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"知らないんですよ。区の広報等々あるけれども、より区民の方にそれを知ってもらうためにはどのようにすべきであって、どのようにしたいと考えているのか教えていただきたい。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"ＩＳＯを返上するに当たって、職員の意識や区民の皆様への意識が後退されないような形で、ホームページ上で公表していきたいと考えています。環境対策というのは目に見えるようで目に見えないような部分がありますので、非常に難しいところかなと考えています。","voiceIndex":95,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問・要望","question":"ロゴもやめるのであれば、新しいロゴも表現の仕方もあろうかと思うので、そこら辺ご一考いただきたいなと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"ＩＳＯというのは物づくりとか、規格とか、そういうところで始まったので、なじまない部分もいっぱいあると思うので、そういった意味では、保育園などもＩＳＯを導入して、実際どうなったのかというところがかなりあったと思うのですけれども、研修を重ねて拡充をしたり、内部監査をやっていくという意味では、検証していく物差しがわかりやすく、明らかになっていくことが第一だと思うのですが。","respondent":"三ツ橋環境課長","answer":"１０月１日から試行運用を始めますけれども、本日も午前、午後と研修、制度説明会を実施しておりまして、その中で実務担当者に向けては実際にこういう形でこういう書類をつくっていくのですよと、具体的なものをあらわしております。","voiceIndex":99,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"システムに乗っかって規格であらわせているからそれでよしとするのではなくて、一人ひとりの職員の方の意識が上がっていくということもまた区民に対する啓発になっていくと思うのです。なので、わかりやすく、ぜひ区民の方も一緒になって環境負荷を減らしていくところに広がっていきますように、わかりやすい伝え方を工夫していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-037"}]},{"id":"topic-05","title":"の区職員の消防団入団","agenda":"の区職員の消防団入団","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは数字的なところを伺いたいと思います。入団予定の方の内訳を教えていただける範囲で教えていただきたいのですが、居住地は問わないとなっていますけれども、品川区内にはお住まいでないのかどうかというところと、男女問わずとありますけれども男女比、人数、男の方は何人、女性の方は何人、あと大体の年齢、何十代ということでも結構ですけれども、そこのところを教えていただきたいと思います。","respondent":"加藤防災安全担当課長","answer":"男性が３名、女性が２名。男性は５０代と３０代が２名、それから女性は２０代が２名の計５名です。","voiceIndex":107,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"２０代の女性が２名ということで心強いなと思います。最後に伺いたいのは、今後これは増員していく、毎年募集をして増員していくという、毎回というか、毎年というか、機会を捉えて増員していくという方向性なのか、様子を見るという方向性なのか、そこを教えてください。","respondent":"加藤防災安全担当課長","answer":"ただ、入団をずっと継続して募集していますよと言ってもなかなか印象に残りませんので、相談して定期的に募集をかけたりといったことを、今回初めて５人が入りますので、その状況も踏まえて今後また消防団と連携しながら。","voiceIndex":109,"id":"exchange-039"},{"speaker":"大沢委員","kind":"質問・要望","question":"非常時のときにどちらが、消防団活動が優先されるのか、あるいは区の職員としての行動が、どちらが優先されるのかだけ確認させていただきたいと思います。","respondent":"加藤防災安全担当課長","answer":"資料３の入団予定の最後に、募集の際、「水防第１次配備態勢時に参集する職員を除く」という形で今回募集しました。これは水防事象が非常に頻繁的に多いので、それと重なる部分についてはまず除外しようということで除外しています。","voiceIndex":111,"id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"私も大沢委員と似たような、関連したことかもわかりませんけれども、一番下の「区の組織運営に支障がある場合を除き」という、これがほかの法律、今回決まった法律でなくてもほかの、今までにあった形のところで想定があるのかないのか、その辺も含めて教えていただければと思います。","respondent":"加藤防災安全担当課長","answer":"ただ、一個人が消防団活動する際は必ず支障は来しますけれども、その人間の個人的な時間の配分だとか、そういったことを考慮すれば業務は進められるというものに関しては含まないというような解釈を国は示していますので。","voiceIndex":113,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":29171,"voices":118}},{"id":"h26-20140916-9","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"文教委員会","time":"午後１時００分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"あのときの質問では３０万円ということだったはずなんですけれども、６７万円余が増えたその中身というのは、講師が３０万円で、あとは大ざっぱでいいですから構成を。","respondent":"伊崎子育て支援課長","answer":"大体６７万５,０００円のうち、３０万円弱がボランティア謝礼でございまして、その他は記念品を含む消耗品の購入です。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"の品川図書館 秋の講演会","agenda":"の品川図書館 秋の講演会","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"この内容的にどうなのかわからないですけれども、例えば高齢者の方がこのホームページから電子申し込みも可ということなのですけれども、何かごめんなさい、私の理解不足なのかもしれないですけれども、ほかに何かお電話ででも大丈夫なんですか。ちょっと確認させていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-002"},{"speaker":"吉田委員","kind":"意見","question":"お電話でいい。すみません、ありがとうあります。間違いました。申しわけございません。それと対象の年齢が、読書と脳トレということで、高齢者なのか。若いお母さんだったら、例えば育児、要するにお預かりのシステムがあるのかというのを１点お願いしたいと思います。","respondent":"中元品川図書館長","answer":"特に今までそういうお問い合わせがなかったこともありまして、またこの対象のお話が、読書と結びつけて脳の活性化というところですので、今までこの秋の講演会にいらっしゃる方というのはわりと５０代以降の成人された方がご夫婦でいらしたりとか。","voiceIndex":16,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"電話ももちろんいいんですけれども、ホームページから電子申請も可ということで、結構高齢者の方ほど、そういう電子機器を利用されている方というのは多いとは思うので、できない人ももちろんいらっしゃると思いますけれども、しかし、そういう状況でされるというのはどうしてかなと、ちょっとしつこいですけれども、教えてください。","respondent":"中元品川図書館長","answer":"最初に、当日受け入れるかどうかというのは、やはり席の限界が物理的にありますので、２５０人までですので、もちろんそれより下回っている場合は、受付で柔軟な対応はすることはできます。最初からそういうアナウンスはしてございません。あえてしていないところがあります。","voiceIndex":20,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そういう点で開催していただくのはいいと思うし、大いに、私も時間がとれれば伺いたいかなと思って見ていたんですけれども、そういうあれだけに、空きが結構あるというのでは、もったいないと思うので、当日参加も含めて、やっぱりなかなかあまり事前申し込みをしないことがいいのかどうかは、賛否は私はわからないけれども、できるだけ大いに参加して。","respondent":"中元品川図書館長","answer":"すみません、繰り返しのご答弁になってしまいますが、やはり会場の座席の限界もありますので、もちろん空いて、実際の締め切りはそれより前で締め切りますので、当日は目安として、今日は１０席ぐらいあいているという状況であれば、受付にお見えになった時に。","voiceIndex":22,"id":"exchange-005"},{"speaker":"須藤副委員長","kind":"質問","question":"事前申し込み、必要だと思います。川島先生の名前だと、かなり名が通っているので、２５０人以上の応募があると私は想定しています。ですから、きちんとやっぱりその辺は整理しなければいけない。むしろ僕らは遠慮しておくべきだと思っていますので、お願いは、品川区議会として何年か前に川島先生に視察でお邪魔をしました。ですから、「よろしくお伝えください」とお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-006"}]},{"id":"topic-03","title":"の品川区臨時給付金の支給状況","agenda":"の品川区臨時給付金の支給状況","exchanges":[{"speaker":"南委員","kind":"質問","question":"ちょっと所管外のご質問になってしまうかもしれないですけれども、対象者がさっきの説明のとおり、非課税世帯と生活保護世帯と児童手当の該当を除くという、２番の子育て世帯臨時特例給付金の件なんですが、これは生活保護を受けている方が当然対象者ですから、児童１人当たり１万円見当で、子どもの人数分受給できるということになるわけなんですが、そうなると。","respondent":"福島臨時給付金担当課長","answer":"生活保護を受けている方につきましては、基本的には受給者は対象外になりますので、この米印に本人が非課税世帯、あるいは被生活保護者、生活保護を受けている方は対象外、ですから、１万円につきましては支給されません。","voiceIndex":31,"id":"exchange-007"},{"speaker":"南委員","kind":"確認","question":"間違いましたので、訂正したいと思います。それから品川区の場合は申し込み発送が２３区中２番目。いつもというか、あまりこういう事例、給付金があるわけではないんですけれども、何回かこの間あった中での話なんですけれども、他区なんか聞いてみると、秋口以降みたいなところが結構あるみたいなので、ちょっとそのあたりでどうなのかなというのが気になったので、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ。この勧奨通知、１０月１０日に送付されて、その前の申し込み書発送開始が６月１６日からとなっているので、これは申請書を発送して、未達で戻ってきた件数というのがもしあるのであれば、教えていただきたいと思います。","respondent":"福島臨時給付金担当課長","answer":"今現在、未達で戻ってきた数まで、手元には資料がございませんで、ただ何件かはありますが、それは戻ってきた場合、原因を調べてまた再発送するという事務手続をとってあります。","voiceIndex":37,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。未達で返ってきてしまったのは、さまざま理由があるのかと思うので、それこそ子どもの居どころがわからなくなるという、今社会的にもいろいろと課題になっている部分もあるので、その辺はぜひ丁寧に対応していただければと思いますので、要望で終わりますが、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"この３番と４番、申請書の発送ということで１点、これはこの区のほうで少しでも早くということで、要望させていただいていた部分がありますので、この２３区の中に限ってというところで、２番手、１番手というのは非常にありがたいなと思いますので、今後も引き続きお願いします。平均して件数が多いとなかなかという部分はあると思うんですが、大体どのくらいで振り込みがされるものなのかを教えてください。","respondent":"福島臨時給付金担当課長","answer":"実際に振込通知のほうでは、１カ月から２カ月かかるというふうに案内しています。どうしても大体１カ月ぐらいはかかってしまうというのが現状です。","voiceIndex":41,"id":"exchange-011"}]},{"id":"topic-04","title":"の御殿山幼稚園の再移転に伴う北品川地区保育・教育施設","agenda":"の御殿山幼稚園の再移転に伴う北品川地区保育・教育施設","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、現在、すこやか園に通われているお子さんで、新たに御殿山すこやか園に移る中で、子どもたちの移動というのはスムーズに可能なのか、それともまた、多分御殿山に行きたい子と、そのまま北品川に残りたいという２通りのパターンが出てくるのかなと思うんですが、その辺の在園児に関しては全て優先的ではないですけれども、スムーズに移行ができるのかどうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これまでも在園児の方につきましては、平成２７年、来年になったときに、保育園からの幼稚園在園児の方についてはご意向を確認しまして、本来ならば御殿山幼稚園に進んでいただくというご説明でお入りいただいたのですけれども、昨年もそうですが。","voiceIndex":47,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとその辺が前回も１年前に質問をしたんですけれども、もう一回確認したいというのと、それから、北品川五丁目第一地区の竣工が５月末で、１カ月かけて幼稚園の開園準備、保育園のほうは１カ月ちょっとかけて開園準備ということなんですけれども、大体今までも１カ月程度の開園準備期間を置いていたんですけれども、場所は変わるけれども。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに1)の（仮称）認定こども園につきましては、０から３歳児のところが以前は５１人でしたけれども、これが５４名になりますので、ここで３名の定員拡大を予定しております。そこの右の４歳児、５歳児は新設ですので、４０人という形になります。","voiceIndex":50,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"スムーズに移行して保証されるということになってくるので、時間的な空きがない対応をしていただけるので、ちょっとそれは一安心したのですけれども、ごっそりというか、大半が引っ越しをして、年度途中開園ということですから、大体６月過ぎると新年度の大変な混乱状況というのは落ちついてくる時期なんですが、４月に新しい子どもさんが入って進級していく中で。","respondent":"今井制度改革・待機児童対策担当課長","answer":"幼稚園の幼稚園教諭についてはそのままです。幼稚園は移転です。保育士につきましては、この新設の部分につきまして、保育士の確保を来年度の４月に予定しております。","voiceIndex":52,"id":"exchange-014"}]},{"id":"topic-05","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"前回、どこまでどういうふうに質問したか、あまり覚えていないので、確認のために質問させていただきたいんですけれども、７校が武道場がないわけですよね。武道場というスペースはない学校が７校あるということで、現実的にどういうふうな環境設定をして武道の授業をしているのかということを質問したいのですけれども、ちょっとごめんなさい、そのあたり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"だから最初に言ったように、ちょっと覚えていなかったので、もう一回確認したいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":13976,"voices":63}},{"id":"h26-20140916-5","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"総務委員会","time":"午後１時００分～午後２時３７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"のしながわ区民公園クラブハウス改修工事請負契約","agenda":"のしながわ区民公園クラブハウス改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"クラブハウスの改修工事ということですけれども、ここを利用されている方や今回バリアフリー対応ということも含めて、障害がある人を含めて、利用者の意見とか利便性というのはどのように反映されていらっしゃるのか、その仕組みを伺いたいと思います。","respondent":"立川経理課長","answer":"幾つかあります。今までテニス用の更衣室ということでありました。こちらの更衣室のほうを面積的には約２倍にいたしまして、テニス利用者だけではなくて公園でのジョギング等、そういった方も使えるように、また、有料の温水シャワーを設置するです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"小さいことですけれども、ちょっとフックがあるだけで持っているポシェットがかけられるとか、傘が置けるとか、そういったところはわざわざ図面に反映する大きさなのか、その辺の技術的なことがありますけれども、多様な方が使いますので、ぜひそういう障害者がある方の意見を聞いて、反映していただきたいと思うのですけれども、現状を伺いたいと思います。","respondent":"立川経理課長","answer":"既に図面とともに発注も終わり、契約も済んでいるところです。ただ、今、委員ご指摘の部分というのは軽微な修正ですので、こういった意向についてはそういうふうに伝えていきたいと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"１点、辞退が３件あるわけですけれども、その状況をお聞かせください。それと、この図を見ると設計変更は難しいと思うのですが、テニス更衣室側のほうにはトイレはないのでしょうか。外部からの利用、公園利用者とか、ジョギングとか、そういう方々も利用されるようにとなると、外から入りやすいというところも必要になってくると思います。というような状況もあると思うのですが、それはいかがでしょうか。","respondent":"立川経理課長","answer":"入札状況ですけれども、３社辞退ということで、理由といたしましては、まず配置する技術者が不足していることと、また予定価格と事業者のほうの積算が合わない、そういったことで辞退というふうに聞いておるところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"そこはどういうふうに評価をして、辞退がこれだけあるということに対してどう判断をされるのかをお聞かせください。ここは自由に利用できるようになるのですね。今の設置もいったん外に出てということになると不便さを感じるのですね。今後有料化していくというのであれば、その方針にもっと理解を求めていくことになると思いますが、どのぐらいの負担を皆様に強いていくのか、その辺もお聞かせください。","respondent":"立川経理課長","answer":"３社辞退ということで、事業者と予定価格積算に乖離があるということで辞退になってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"先ほど技術者不足ということも要因としてあるという話だったのですが、その差が、３社が辞退されたことにおいては、本当に落札されたところは大丈夫ですかと逆に心配してしまう部分があります。まだまだ落差があるからほかのところの３社が辞退されたと考えるわけで、本当にそれは大丈夫でしょうかと確認をしたいと思います。それはどういうふうに説明していくのでしょうかという質問です。","respondent":"立川経理課長","answer":"３社辞退が出ました経緯ですけれども、最近の工事では、これまで一般競争入札については予定価格を公表しておりますので、そういった意味で事前に積算が合う、合わないということで辞退するかしないかです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"最後にします。不調になる場合はあちこちで問題になっていることですし、やはり動向を見据えて、改定する場合にはかなり緩和をしながら、積算も少し変えながらやっていく必要があると感じております。そういうことからすると、きっちりと理論立てて利用料を設定していかなければならないのではないかと思いますが、その考え方はいかがでしょうか。最後にお聞きします。","respondent":"立川経理課長","answer":"事業の内容につきましては所管が異なりますので、明確なお答えはできないわけですけれども、こういった意見が当委員会においてあったということは所管のほうに伝えていきたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"私はそんなに、３カ月、１カ月、急騰しているような労務単価がどうだとか、資材がそんなに上がっているというようなことは新聞報道でも出ていないと思います。この入札不調ということをこうやってずっと、今こういう状況だから人手も足りないから、では放っておくというのではなくて、思い切って一時的に入札の制限がかかっているのですが、これを解除してもいいのではないですか。できるはずです。","respondent":"立川経理課長","answer":"そういった中で、区としましては実際に不調になった案件につきましては、いわゆる予定価格引き上げを行ったり、また事業者のほうから見積もりを徴したりしまして予定価格のほうを適切に設定し直すということをやっておりますので、今後ともそういった経済社会情勢を鑑みまして。","voiceIndex":17,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと意味合いが違っていて、今の「配慮する」は、人材が足りない、資材労務単価が高騰、それに対してはずっと配慮しているわけですよ。品川区は一生懸命、都単価も、国のほうも単価を上げて積算しているではないですか。だったらもっと門戸を広げて、制限を１回緩めて、ましてやこれは平屋ですから。そういうことも考えたほうがいいのではないかと思いますが、その辺どう思われますか。","respondent":"立川経理課長","answer":"そういったところではこういった条件をつけてやっております。この条件につきましては、当面緩和するということは考えてございませんが、案件によっては区内事業者だけではできないという部分もあります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"ならば、何かそこでやはり品川区としても工夫していただいて、制限の緩和とかそういう方向でもっといろいろな方が中に入って、区で決めた予定価格を、今年はこれで間違いないと思うので、そんなに安いとも思わないし。そういうことのないように、私は区の威信にもかけて、制限を少し緩和してもっと区内業者を使うように努力して、もっと入札者が増えるように頑張ってほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は屋内にすべきだと言ったことがありますけれども、今でも冬はプールを使わないわけですから、そういう意味からも、温水にするから有料にするというのはおかしいと思います。質問は、結局プールの改修は屋外ということですから冬場はプール利用がないわけですね。そういうときは、半分から右側の施設というのは一体どういう利用になるのでしょうか。そこも含めてジョギングの方ということなのでしょうか。","respondent":"立川経理課長","answer":"今後、ロッカーを移動式にするとかそういったことで、プール利用期間以外でも利用者の利便に供するような仕組みにしていきたいと考えているということは所管のほうから聞いているところです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"補足的にもう少しご説明いただきたいと思うのですけれども、工事品質の確保と適正価格の契約の推進のために、どうして電気と機械に拡大をしたのか、その中身をもう少し詳しくご説明いただきたいと思います。","respondent":"立川経理課長","answer":"これまで土木・建築に限定してやっていたところですけれども、土木・建築のほうのこれまでの平均落札率というのが、機械・電気の設備工事と比べて、年度により若干違いますけれども大体１割程度、１０％ぐらいの違いがありました。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"意見","question":"後半のほうのところ、問題がないので拡大するということですけれども、要するにどういうことで拡大したのか、そこをご説明いただけますか。今回のポイントなので。","respondent":"立川経理課長","answer":"いわゆる社会経済情勢の変化というところで、具体的に申し上げますと、やはり工事契約における設計労務単価の大幅な引き上げというのは、国の試算ですが、この２年間でおよそ２３.２％というような引き上げ、また円安による建設資材の高騰。","voiceIndex":30,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、先ほど入札の結果もあって、ダンピング受注の防止というのは将来的に見ればあるのかと思うのだけれども、そこで言うなら、何となくそれはそれでいいのかと。そこだけを言ってしまうと。だから、そこら辺のところは気をつけてほしいという意見だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"今のダンピング防止というのはよくわかります。そういうときに、この芽をつぶされてしまうということもあるのかと思いました。そこら辺は、やはりこれによって、電気・機械を含めて設備すべてですから、そうすると今後は、最低価格は１０分の７から１０分の９の範囲で落札したところがすべてという形になってしまうということですか。まだ違うところもあるのですか。","respondent":"立川経理課長","answer":"そういった意味で、こちらの資料にも案件ごとに定めるということになっておりますので、その辺については案件ごとに見きわめるというふうには考えてあります。","voiceIndex":33,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"１点お聞きします。「国モデルに準拠し」という「国モデル」はそもそもどういう基準をつくられているのか、都市部と地方とはまた違うのですけれども、細かく国モデルというのは決められているものなのでしょうか。","respondent":"立川経理課長","answer":"国モデルの説明をします。国のほうでは中央公共工事契約制度運用連絡協議会という、中央公契連と略しているところなのですけれども、こういった組織をつくっております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"人口であるとか例えば労務費も都市部と地方とでは違いますよね。そういうずれとか違いを補正した上で、品川区はこれで計算するよという形になっているのでしょうか。","respondent":"立川経理課長","answer":"品川区につきましても、国の単価または都の単価、それからまた品川区の単価というのも持っております。その辺を総合的に条件に加えまして、実際の最終価格を決めていくです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"そうすると品川区の単価というのになると、品川区の単価というのはどこから来る単価なのでしょうか。どういう調整をして品川区としての基準をつくっていくのでしょうか。","respondent":"中山総務部長","answer":"中央公契連モデルの算定式の話で、地域差が全国一律ではないかとお受け取りになっているかもしれませんが、この算定式というのが例えば直接工事費の九十何％であるとか共通仮設費何％、こういう割合を国レベルで定めているものに準拠するということで。","voiceIndex":39,"id":"exchange-017"},{"speaker":"塚本副委員長","kind":"質問","question":"私もこの最低制限価格の決定方法のところでいろいろ説明を聞いていたのですけれども、今回もともと１０分の８から３分の２だったのが、１０分の９から１０分の７、少し上がったわけですね。これはなぜかというと、今の説明で国の準拠に沿ったからということだと、今までは沿っていなかったのかというふうに今思ってしまったのですが、そこら辺の説明をお願いします。","respondent":"立川経理課長","answer":"実際に１０分の８の設定ということで大きな問題が何か起こったかというとそういうこともございませんでしたので、１０分の８を使ってきたですけれども、やはり区としましても積極的にダンピング受注の防止であるとか事業者の適正利潤の確保。","voiceIndex":41,"id":"exchange-018"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"ご説明ありがとうございました。まさにこの件は行政視察でも回ってきて、今この場でまた質問するのもと思いつつ、８番の主な課題というか、むしろこれを見るとデメリット的な方向にしか見えません。","respondent":"黒田税務課長","answer":"特にクレジットカードでのメリットとして考えられますのは、資料２ページの項番３の(1)にあります、現在手元に現金がなくても納付可能であるということが他の収納手段にはないということになりますので。","voiceIndex":47,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"まさに手元に現金がなくてもカードを１回切ってしまえば収納率が多少上がるのではないかと思うのですが、どのみち払うべきものですからあれですけれども、利便性を考えたときに、カード決済というのは非常に楽で、パソコンがあればいつでもできるという部分があります。電車に乗るのだって、今まで切符を買っていたのが１枚のカードで全国どこでも乗れるようになっています。","respondent":"黒田税務課長","answer":"いわゆる自治法に規定しております指定代理納付制度と収納のタイミング等々、なかなか現行法では対応できないという課題があるということで、国のほうでは総務省が地方公共団体の財務制度に関する研究会というのを平成２５年度に立ち上げておりまして。","voiceIndex":49,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"いくつか伺いたいと思います。確かにクレジットカードは便利だと思いますが、一方で、カードによるリスクはないのかというところを伺いたいと思います。そこについて伺いたい。伺いたいといっても今、区はやっていないので、知っているところがあればご説明をいただきたいと思うのが一つです。率直な意見になってしまいますが、今の区の現状や考えがあれば、ぜひ伺いたいと思います。","respondent":"黒田税務課長","answer":"現状では、改修費用等々を考えますと、即座の導入はなかなか難しいのではないかというのが私の考えるところです。","voiceIndex":51,"id":"exchange-021"},{"speaker":"中塚委員","kind":"確認","question":"やはり生活状況が急変することもあり得るわけですから、そこを伺えたらと思います。伺いたいのは、実際に支払ったり請求されたり、そのやりとりというのは名前と金額だけなのか、それとも生年月日や住所や性別やその他、この人はこのカードでどういう商品を扱っているか、カードだからいろいろな情報があるわけですけれども、どの情報に限定してのやりとりになるのか。","respondent":"黒田税務課長","answer":"先の説明の中で申し上げましたが、地方公共団体の長が政令に定める要件のものから指定代理納付者を指定する際に、支払い能力等々を含めて厳格な基準がございまして、区として歳入欠損があるような事業者は指定しないということをまず大前提で選ぶということになります。","voiceIndex":53,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"区とのやりとりも、納付情報は特定されているとは思うのですけれども、カード自体には、例えばこの人がその商品を買ったら次にこういうものを買うだろうと、そういうものがデータ化される中で、商品の案内というのは民間の広告とかいろいろ打ったりするわけですけれども、カードにいろいろな情報がある中で、個人情報の取り扱いも厳格にしていく必要があると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これから例えばマイナンバー制度も始まってくるとしたら、情報はそれなりにいろいろなところにあるのだろうけれども、やはり行政側もそういう情報をしっかりと、今度はそういうので我々も自分の番号がついてくるのだろうけれども、そういうことを含めると、あれだって基本的には便利さを皆様にという意味合いもあるわけだから、そう考えると、便利さを求めるのならクレジットもありなのかと思っているので。","respondent":"黒田税務課長","answer":"クレジットカード会社自体がもしも倒産するというような事態がありますと、その会社から納入が見込めないということなので、その辺については公金という性格上、安全なところというのは国のほうから通知が出ているものでもあります。","voiceIndex":56,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"意見","question":"それこそ前は一番最初にやってもいい、何でも一番がいいという品川区もあったわけだから、今、品川区の財政状況を考えたら、単純に納付機会の拡大で利便性を図りましたというぐらいの発想が、他の自治体でまだ導入が少ないからというのはちょっと違うのではないかと、品川区にお住まいになっていて、そういうサービスの中で、納付機会も拡大していってサービス向上しましたぐらいの。","respondent":"中山総務部長","answer":"しかしやはり一定タイミングであるとか、あるいは費用対効果の冷静な分析であるとか、そういうものを行いながら、他の自治体の動向、なかなか先ほどの説明の中でも納付率への寄与という部分が明確に出ない部分はあります。","voiceIndex":58,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"要望だけ。いくら納付機会の拡大をやったからといって、さらに上げていこうという努力はもちろん必要だろうけれども、そんなに簡単に上がるとは思えないので、単純に機会を拡大して「区民サービスを拡大しましたよ、どうぞ品川区に住んでいただいて、こういうこともできるようにしてありますから、皆様よろしく、どうぞ使ってください」というのが私はいいと思っているので、これはお願いだけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"ということは、年齢からいうと若い方か、そこら辺がわかったら教えてほしいのですけれども、コンビニという割合が半分以上ということは、わりかし若い方が利用されていると思うのですが、その辺の分析はどのぐらいできているのでしょうかということが一つ。を使っているというのは、もうちょっとセキュリティについて調べることも重要なのではないかと思いますが、いかがでしょうか。","respondent":"黒田税務課長","answer":"１点目のコンビニ収納の利用の年代はどうかというご質問ですが、明確な統計をとったことはありませんが、区民の方から聞く意見としては、若い人に限らずご高齢の方でもコンビニが近くにあると。","voiceIndex":61,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"広がっていくだろうと思います。それはやはり今課長もおっしゃっていましたけれども、数がある、２４時間営業されているということでやりやすいのだろうと思います。視察の中でも問題はなかったというふうに言っているのでうまく運用されていると思うのですが、ただ、インターネット上でのセキュリティを考えると、そこら辺はちょっとキャッチしていただきたいと思っています。これは意見としておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28488,"voices":66}},{"id":"h26-20140917-14","meetingId":"h26-cm09","date":"2014年9月17日","dateIso":"2014-09-17","committee":"行財政改革特別委員会","time":"午後１時００分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"その前に、いいですか。世田谷区の基金を聞きに行く、何かそれは皆様から要請があったのか。世田谷区に何があるのか。我々、全然わからなくて、今、委員長から世田谷区の基金を聞いて活発な意見を言えというのだけれども、この中で世田谷区の基金、おもしろいから聞きに行こうという話があったのか。なぜ世田谷区へ行くあれをしたのか。そのあたりを教えてください。","respondent":"中塚委員長","answer":"この後、説明しようかと思ったのですけれども、前回の議論の中で、基金についてのあり方や見直し、基金についての創設の議論がありました。","voiceIndex":3,"id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"だけど、世田谷区になぜ聞きに行きますよという話になったのか、その辺が、私ら自民党のメンバーでちょっと話したのだけれども、何もそんな意見は出ていないよねという話で終わっているのだけれども、委員長と副委員長がやろうとしたのか、それとも、この中の委員からそういうところへ行こうという話になったのか、私は委員会の中でそういう話を聞きに行こうというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-002"},{"speaker":"須藤委員","kind":"意見","question":"先ほど来言っているように、２３区がいろいろやっているのは、この間一覧を見せてもらって、それぞれ経緯があるだろう、それはそれでわかるところで、なぜ世田谷区だけにしたのか、では、全部聞いてみましょうという、ほかの区でもみんな違うことをやっているのだから、そのスタートの経緯というのはみんな違うわけだ。品川区にそれを聞けと言っても、それは無理だと思う。もうそれ以上は言いません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"前回の議論では、確かに今回は視察ということは、私も視察に行くのかというふうな受けとめはしたのですけれども、改めて前回の議事録を読んでみると、基金のいわゆるあり方に関することと、創設や有無に関することということで、テーマに分けて議論しましょうというふうに仕切って、あとは正副に一任させていただいていいですかというふうに委員長がおっしゃったときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"なぜ世田谷区を選んだのですかというお話です。だから、そのあたりが違う。そうしたら、「世田谷区がおもしろいこういうものがあるのでどうですか」という話になってきて、ただ、時間的にできるだけ、長時間になるような話だから、もう少し今までの委員会の中で、５時ぐらいまでにきちんと帰ってこられるような仕組みでやってもらわないとということでお願いをしたのです。","respondent":"中塚委員長","answer":"済みません、若干補足しますと、どこの自治体か、品川にあって他の自治体とかはあるので、いろいろな自治体と話をする中で世田谷区になった理由ですけれども、議論の中で挙がった、例えばみどりのトラスト基金に関することや、文化振興にかかわることや、また、災害について。","voiceIndex":9,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。いろいろな仕組みがあるということで、今のお話を伺っていると、なおさらこれは都が建替え用地として買い増すのが一番いいのだろうと、人さまのことですけれども、なので、早く言ったもの負けみたいなところもあるかと思うのですが、都の動きというのは、もう１回、前回も伺いましたが、どんな感じか、もしおわかりでしたら教えてください。","respondent":"柏原行財政改革担当課長","answer":"現段階では、東京都は、この後ろの国有地については取得する意思はないというふうに聞いています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"若林委員","kind":"質問","question":"１つだけ、素人考えで、前面の４ｍ幅だから１５ｍ以下、そこが引っかかる。道路が連続するのですが、ここだけ４ｍ幅ではなくて、６ｍとか８ｍとか、そういうふうにしたら、ほかに何とかできるのですか。","respondent":"柏原行財政改革担当課長","answer":"ご覧いただくと、この土地の左側の図面のほうがよろしいですか、４ｍ道路にはもう１つの細い接道しかしてありませんので、ここは４ｍ未満、要するに、道路幅を６ｍに広げて、それで１０ｍの接道がとれれば、仮定の話ですけれども、建物としては１５ｍ以上の高さというのは。","voiceIndex":22,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"それで、ここのＢのところの一番下に、斜線規制だとか、日影規制だとかが加わっていくのだけれども、それは今の法律の中ではやむを得ないところだし、民間にももちろんそういうことは要求しているところですからやむを得ないと思うのだけれども、都営住宅の現在の４２戸を確保する必要があると、これはだから、住宅はこのまま確保はしていきたいと、建て替えるにしても確保する努力をしたときに。","respondent":"柏原行財政改革担当課長","answer":"都営住宅の部分についての考え方というのでしょうか、仮にここを一緒に一体敷地として活用しようといった場合に、都営住宅ですので、都営住宅、区営住宅もそうですけれども、公営住宅といわれるものは、建替えをするときには。","voiceIndex":24,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"そうすると、逆に品川区が土地を一体的に使うということで購入しなければ、４２戸の確保はできないという、そういうことになるということなのですか。","respondent":"柏原行財政改革担当課長","answer":"東京都がどのように考えているかというのはよくわからない部分はあるのですけれども、現戸数を確保するために何らかの方策をとっていくのだろうというふうには思います。","voiceIndex":26,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、私は、しっかりとその立場に立ってこの問題を、お金がかかっているということがあるかもしれないけれども、そういう立場で捉えていくべきだというふうに思っているのですけれども、改めてその点についての見解を伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"我々検討する中で、区の行政目的のためにどのようなものができるかという視点で検討を行ってきたわけです。その検討する中で、もちろん費用の面というのは大きな１つの視点として考えたところです。この国の土地を取得するだけでも十数億円はかかるだろうということになります。","voiceIndex":28,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"最後に要望だけ。私は住宅確保ということを、さっきから繰り返して申しわけないのですけれども、しっかりとそういう立場に立っていただきたいと思っているのです。ちょっと残念だと思っていますので、そういう点で、ここのところで品川区としての意思というものをしっかり明確に打ち出していただく、再確認していただけるいいチャンスでもあると思いますので、そのことは強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"南委員","kind":"提案","question":"品川区の公有地有効活用プランというのは、これ、あるのですけれども、この委員会で資料をいただいてはいないと思っているのですけれども、そういうものも含めていただけないかというふうには、今、委員長の提案があったので、ちょっと思いついたと言うと失礼ですけれどもよろしいでしょうか。","respondent":"中塚委員長","answer":"７月２日の委員会で概要版をもらっており、そこで一度議論をしたところですけれども、深めていきたいとのご意見を受けて、次回また進めていきたいというふうに思っています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"提案","question":"通常は、特別委員会の運営は、例えば一番最初の１回ぐらいを徹底して議論して、１年間の方向を確認をした上で一つひとつの物事を議論していくものと私たちは感じています。だけれども、次にどうするかということではなくて、むしろ正副委員長のほうからこうしましょうということを提案していただいて進めていったほうがいいのではないでしょうか。そういう指摘はさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-013"}]},{"id":"topic-02","title":"最低制限価格制度の試行運用の拡大","agenda":"最低制限価格制度の試行運用の拡大","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"先日の議論の内容が既に反映された形での試行運用拡大ということで、よかったと考えています。今後これがどのように運用されていくかというのは、これからまた見ながらということなのですけれども、この試行運用という位置づけというのは、大体どのくらいの期間を見ていらっしゃいますか。ちょっと確認させてください。","respondent":"立川経理課長","answer":"ものによるという言葉ですけれども、おおむね１年ぐらいは状況を確認して、それでまた次のステップとか、そういったことを考えているところです。","voiceIndex":42,"id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"これについてはいろいろと制度を少しずつお声を聞きながら、今、動かしている最中ということで、また今回のようなスピーディな対応を今後もいろいろな動きに対応して動くというものを期待します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"提案","question":"先ほど、毎回毎回、委員長のほうから皆様にご意見を、最後、次回の運営についてということは申し上げているところですが、それも今回、運営についてというところを先輩方からもいろいろなご意見を頂戴しながらというところで進めてきたところでありますけれども、私どもでいろいろな設計図をかきながら皆様にご提案させていただければと、そのとおりだと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"今の副委員長のご発言に関連してなのですけれども、私は正副の２人が委員会運営をどうしようかというのでいろいろご苦労されて、次回、用意していただきたい資料があったらという投げかけもしていただいている、そういうことは本当に気がつく、わりと気がつかない場合があるのですけれども、そういう投げかけというのはありがたいというふうに、今までの経験からも私はそういうふうに受けとめています。","respondent":"中塚委員長","answer":"なければ、本件を終了いたします。以上により、予定表３のその他を終了いたします。","voiceIndex":48,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":15339,"voices":50}},{"id":"h26-20140918-18","meetingId":"h26-cm09","date":"2014年9月18日","dateIso":"2014-09-18","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後４時３７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":2233,"voices":10}},{"id":"h26-20141024-4","meetingId":"h26-c-settlement","date":"2014年10月24日","dateIso":"2014-10-24","committee":"決算特別委員会","time":"午後 ３時３９分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"つる副委員長","kind":"意見","question":"ただいま皆様のご推挙によりまして、決算特別委員会の副委員長の大任を拝命いたしました。向副委員長とともに、須藤委員長をしっかりと支え、また、委員各位の皆様に置かれましては、円滑かつ、また実りある委員会としていきたいと思いますので、どうかご協力のほどよろしくお願いを申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":2021,"voices":16}},{"id":"h26-20141027-6","meetingId":"h26-cm10","date":"2014年10月27日","dateIso":"2014-10-27","committee":"区民委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５６号議案、平成２６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５６号議案、平成２６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"本多委員","kind":"確認","question":"２８ページ、２９ページの東京オリンピック・パラリンピック５０周年記念の件なのですけれども、６２区市町村に対して予算が１００万円ずつつくとか、その辺のちょっと確認をさせてください。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"６２区市町村が合意をして、東京都で今、強く取り組んでおります５０周年記念事業と一緒に頑張っていこうということで、６２区市町村にそれぞれ１００万円が配当されるという内容です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"はい、ありがとうあります。それで、品川区は１２月９日にスクエア荏原で行うということなのですが、何人規模なのか、その規模をちょっと概数で教えてください。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"こちらのひらつかホールの定員が３６２名ですので、３５０名ほどの方を、区民の方をご招待したいというふうに考えてあります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"今の区市町村の金額のところでお伺いしたいのですが、原資は、品川区の場合には歳入が宝くじ等助成金収入ということなのですけれども、全てこのトータルがそうなのか、都の予算がそこにあるのか、その辺の内訳を教えてください。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"東京都区市町村振興協会は、そもそも６２区市町村を支援する事業を行っているところなのですけれども、そこから一旦、品川区の場合は特別区長会にお金が入りまして、特別区長会から品川区のほうに直接お金が入るという内容です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"公益財団法人東京都区市町村振興協会から、この１００万円が入るという、区長会に入って、品川区にも、各６２区市町村に入るということなのですが、公益財団法人の振興協会ですか、ここのところの役割というか、そういうところからのお金の来方というのは、これからオリンピックの気運醸成というふうなことで、例えば来年度予算とか何かにも。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"こういった東京都の動きを踏まえまして、６２区市町村のほうでも、２０２０年に向けたキックオフということで、一緒に東京都とともに頑張りましょうということの合意ができまして、６２区市町村のほうでこの協会のほうと対応を協議し。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、この東京都区市町村振興協会に対して、区長会として、こういうふうにオリンピック気運醸成に向けて、各区市町村で取り組んでいこうではないかと、それにあたって、財源としてこういうふうに、何とか財源を出してほしいということでの交渉でそういう形になるということで、この財団法人というのは、これは区市町村の振興のためにつくられている、宝くじの収益をもとにして。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"委員ご指摘のとおりです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"プレミアム付商品券のことについてなのですが、この不況の中で増額というのは本当に大賛成というところなのですけれども、ここのところでも、消費税の引き上げなどで区内商店街を構成する中小企業等の景況は依然として厳しいということで書かれているわけなのですが、この厳しいというふうな判断をした。","respondent":"米田商業・観光課長","answer":"その他、卸売業も比較的厳しい状況ではあるが、今後に向けては少し明るい兆しもあるだろうというような見方をしている方も結構います。それから、サービス業については、その２つの業種に比べると、もう少し景況感としては、そこまで深刻ではないというような状況です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"小売業が厳しいということなのですけれども、具体的に、数字的なもので、それが示されるようなものがあったら、ちょっと教えていただけたらと思います。","respondent":"米田商業・観光課長","answer":"数字といいますと、いわゆる景況調査の数字等をもとにというようなことになるかと思いますが、そちらのほうでは、依然として厳しい状況にあるというようなことを結果としていただいているものです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に、商店街の方とかにお聞きすると、いや、本当に厳しいというお話が多くて、もう消費税を払え払えと言われても払うお金がないと、本当に８％になって大変で、これが１０％になったら、もう一体どうなるのかという、そういう悲鳴のような声をすごく、直接伺っているのですけれども、本当にやめたくてもやめられない、やめたとしてもほかに仕事があるわけではない、本当にそういうふうなところでは。","respondent":"米田商業・観光課長","answer":"やはり消費税８％、これはいろいろ目的があって導入されているわけですが、区内の商業には、売り上げ等にある程度影響があるだろうというようなことで、４月につきましてはプレミアム分の増額を図って、売り上げの減少に対応したものです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"それにおいて、こういうふうに補正でぽんと、こういう形で入ってくるのかというところのお答えをいただきたいのと、あとプレミアム付商品券なのですけれども、今回の定例会の一般質問でさせていただいて、私は、地域振興事業部長に答弁いただきたかったのですけれども、企画部長からご理解くださいというような答弁が、再質問を含めて２回あったのですが、理解できないので、改めてここで伺いますけれども。","respondent":"小川オリンピック・パラリンピック推進担当課長、米田商業・観光課長","answer":"その一環で、今回の補正かというご質問ですが、今回の補正は、あくまでも今年が１９６４年東京大会から５０周年という記念すべき年であったということで、この年を東京都としては大変重く受けとめておりまして。やはり消費税率の改定は、いわゆる商店街を取り巻く環境としては非常に大きな環境の変化であろうということで、ある程度売り上げの落ち込みも見込まれるということで、何とかしてその辺の下支えをしたいということで。","voiceIndex":23,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"逆算しての計画はないのかという質問に対する課長の答弁で、具体的な計画はありませんというお答えだったのですけれども、文化スポーツ振興課の中に担当課長、担当ができて、なおかつ、オリンピック・パラリンピック推進特別委員会も議会として設置したわけなので、やっぱり難しい面もあるかもしれないのですが、年度ごとの計画というのは。","respondent":"小川オリンピック・パラリンピック推進担当課長、米田商業・観光課長","answer":"そういった事業を検証しながら、毎年度、毎年度ごと考えていきたいところではありますが、タイミングを見て、おそらく２０２０年に向けての計画を策定すべき時期も来ようかと思います。この秋については、当初の予算額の残額から、そのままでいいのか、それともどれぐらい積み増しておいたほうが妥当なのかというようなことをこちらとしても考えた上で、１,０００万円を積み増しとしたものですので。","voiceIndex":28,"id":"exchange-010"},{"speaker":"浅野委員","kind":"提案","question":"オリンピック・パラリンピックの５０周年記念事業の件ですけれども、今回はスペシャルトークショーという形で提案がされておりますが、トークショー以外のイベントとか、そういうのは複数考えられているのかどうか、それについて１つお伺いしたいと思います。そこら辺の分析を１つお聞かせいただければと思います。","respondent":"小川オリンピック・パラリンピック推進担当課長、米田商業・観光課長","answer":"品川区といたしましては、昨年に招致が決定して以来、いち早く子どもたちを日本体育大学に連れていったりですとか、今年度につきましても、区内の予定競技種目のブラインドサッカーのフェスタをやったりですとか。そういった中では、どちらかというと、買おうと思っていたのだけれども買えなかったというようなお声も今まで多々あったのですけれども、今回については、お買い求めになりたい。","voiceIndex":31,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"区民の方から、たまにこの商品券の話が出るときに言われるのは、やっぱり買えないというのがどうしてもあります。これは、すぐやれとか、そういうことではなくして、先ほど答弁にもありましたとおり、幅広く多くの方に利用していただくという観点で研究しながら、これからも品川区の活性化のために努めていただければと思いますので、これは要望になりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"},{"speaker":"木村委員","kind":"質問","question":"５口から４口に下げたということで、大体２カ月ぐらいかかるということでしたけれども、これを４口までということではなくて、例えば、暮れであればこれをお歳暮に使えたりとかという形で、何かいろいろとこう、使いよう、用途があろうかと思うのですが、それを多く買うことは絶対にできないということなのでしょうか。","respondent":"米田商業・観光課長","answer":"販売所でお申し込みしていただくときには、１口か２口か３口か４口か、ご自身で選んで購入していただくようになっておりますので、４口までの購入制限となります。","voiceIndex":37,"id":"exchange-013"},{"speaker":"木村委員","kind":"質問","question":"これは、１回につき４口ということですか。そうではなく、例えば、僕が買えば、木村けんごは前回４口買ったという何かが残っているということですか。","respondent":"米田商業・観光課長","answer":"販売所におきまして、４口までお１人が買えるようになっているということです。当然、そこにいろいろ書いていただくことがありますので、データとしては、最終的に商店街連合会のほうで把握するような形になります。","voiceIndex":39,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"オリンピック・パラリンピックの事業なのですけれども、この事業で３５０名ぐらいの方の入場をということで、ここでやはり私が求めたいのは、佐藤さんがそういう経験をしてパラリンピックに、治療とリハビリを経てというような方であれば、療養中の方とか、そういう治療中の子どもさんとか、あるいは障害者当事者の方たちへ、３５０名の中に枠をとって、そういう方たちへ供すべきだというふうに思うのですが。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"今後、そういった特別枠については検討していきたいとは思うのですけれども、今回につきましては、初めての講演会ということもありますので、とりあえず皆様平等にということで、往復はがきでのご応募をということにしたいというふうに考えてあります。","voiceIndex":41,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問・要望","question":"それが、これからのオリンピック事業にもすごく有効に広がっていくと思うので、そこはぜひにということで、検討いただきたいということで、お願いしたいと思います。そこをちゃんと把握をする必要があると思うので、どこで消費をされているのかということは、そろそろ連合会のほうにもデータを上げていただくようにすべきだというふうに思うのですが、それについての検討状況はいかがでしょうか。","respondent":"米田商業・観光課長","answer":"いわゆる使途、どこでどう使われているかということについても、毎回ですと、かなり容量的に膨大になりますので、こちらは機を捉まえて、どこでどう使われているかということの調査を、その１回分について、また行ってまいりたいというふうに考えております。","voiceIndex":43,"id":"exchange-016"},{"speaker":"井上委員","kind":"確認","question":"今、最後に機を捉まえてとおっしゃられたのですけれども、商店街が販売している商品券は、商店街が独自でいろいろな努力をしていただくということなのですが、プレミアム付商品券の場合には、区が税金でそこを支援しているということであるので、区として、どれだけの振興が図られているのかということは、評価として当然しなければいけないというふうに思いますので、まだまだ当分。","respondent":"米田商業・観光課長","answer":"出口の調査についても、たしか記憶しているところでは、おととし、出口の調査をいたしましたので、これは毎回、毎回というわけではなく、定期的にやって、そういうものの使われ方、全体の数字は出ておりますので、一定程度の評価はできると思いますが。","voiceIndex":45,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"もう一点、先ほど固定化をしたのではないかというお話もあって、そういったところも危惧されていて、このチラシのところでお伺いしたいのが、以前に、平日からスタートすると働いている方は買えないという要望に対して、多分、土曜日にこの下のほうの購入場所のところで、区商店街連合会事務局では、８日については一定数確保して販売しますというような工夫もしていただいているのかと思うのですけれども。","respondent":"米田商業・観光課長","answer":"販売場所ですけれども、先ほど来ありますように、お勤めの方でもお買い求めやすくというようなことでは、金曜日あたりに発売して土曜日、日曜日、やっているところもありますので、一定数を確保というような形で、区商店街連合会のほうではやっておりますので。","voiceIndex":47,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"これをどういうふうに使われているのか。集めただけだったら、複数の場所で同じ人が買わないとか、そういうことも含めているものなのだけれども、広く使われているのか、日にちなんかを、これは土日とか、申込日があるので、働いている方たちがなかなか難しいとか、そういったところも何か分析としては使えるのではないかと思うのですけれども、あまりそういう意図はないですか。","respondent":"米田商業・観光課長","answer":"こちらについても、せっかくのデータですから、有効活用については、当然考えていかなければならない、このように考えてあります。","voiceIndex":49,"id":"exchange-019"},{"speaker":"沢田副委員長","kind":"質問","question":"１点だけ、すみません。オリンピック・パラリンピックの５０周年記念事業で、歳出の講師謝礼、会場費ほか１００万円になっていますけれども、この内容だけ教えてください。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"こちらの内訳ですが、報償費が謝礼関係で、需用費につきましては記念品ですとか講演会当日の花束ですとか、そういったことがあります。それから、使用料および賃借料につきましては、会場費の分が計上されているものです。","voiceIndex":51,"id":"exchange-020"}]},{"id":"topic-02","title":"平成２６年度協働事業提案制度の審査結果","agenda":"平成２６年度協働事業提案制度の審査結果","exchanges":[{"speaker":"井上委員","kind":"意見","question":"区課題提起型の事業についてなのですけれども、この内容について、今回、この２項目が出てきているわけですけれども、どういった基準で、この課題について誰がどこで決定をしているのか。過去に、区の課題として提起をされたものなんかを紹介していただきながら説明をいただけたらと思います。","respondent":"河内協働・国際担当課長","answer":"その前、平成２３年度につきましては、生活習慣病予防の知識に関する普及・啓発および健診受診率向上、高齢者などが安心して生活を継続するための支援メニューの拡充などというふうになってあります。","voiceIndex":67,"id":"exchange-021"},{"speaker":"井上委員","kind":"提案","question":"もう少し、ちょっとスケジュールを、いつごろ各所管に投げて、提案があって、今お聞きすると、割と所管を順番に、防災があったり健康があったりと、網羅していこうとしているのか、それとも、区との協働というところで、何かの基準を持って判断をしているのか、そこについてもう少し詳しくお願いしたいと思います。","respondent":"河内協働・国際担当課長","answer":"１２月から１月にかけて、そちらの募集をかけまして、その後、私どもの所管のほうで審査をさせていただきまして、新年度事業として、そちらを提案するという段取りで進めてまいります。それから、こちらのテーマの取り扱い等につきましてのご質問です。","voiceIndex":69,"id":"exchange-022"},{"speaker":"井上委員","kind":"提案","question":"要望になるかと思うんですけれども、やっぱり施策として、区が独自でやるよりも、そういう柔軟な発想ということで、予算も正式につけてやるという意味で、以前には発達障害の方たちの事業が、当事者の方たちの理解がどのぐらい得られているかよくわからない、そこは疑問のあるところなのですが、それを発展的に区の施策としてきちんと位置づけるというような、１つのメリットもあったというふうに思うので。","respondent":"河内協働・国際担当課長","answer":"そういった中で、区民の中でタイムリーに取り扱われているテーマなどをいろいろ議論の中でできないかというところで、そういった側面の中で進めている状況がありますが、委員おっしゃったとおり、要望につきまして。","voiceIndex":71,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問・要望","question":"区課題提起型のところで、すぐ区が導入することは難しいという事業もあって、そこにアイデアをいただくというのも、すごい協働の制度だというふうに思いますので、区課題提起型というところでは、そういう意味で進めていただければなということで、要望をしておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"目的が、区が直面する行政課題に対してですね。いろいろ直面する行政課題はありますけれども、提起型で２つ挙がってきて、ひきこもりなどの若者の自立について、多くの区民の理解と、あともう一つが外国の方と接する機会や英語を話す必要性を実感するという、この２つが挙がっていますが、これが区が直面する行政課題だったのですかという、まず、そもそもをお伺いします。","respondent":"河内協働・国際担当課長","answer":"そういった側面で、所管課のほうから、課題の提案を求めた結果として、このようなものが挙がっておりますが、これが全てとは認識しておりません。そういった中の１つのテーマとして、こちらを提案させていただいたというふうに解釈しています。","voiceIndex":74,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、こういう意味で、所管から挙げてしまうのかという思いはすごくあるのですけれども、その辺において、もうちょっとわかりやすく説明していただきたいのと、それともう一つの思いは、これはストレートな質問をしますので、ストレートに返していただきたいと思うのですけれども、区の直面する行政課題、いわゆる区民と区行政の間に入って、いろいろなことを審議し、いろんな要望をして。","respondent":"河内協働・国際担当課長","answer":"議員の皆様の果たされている役割等につきまして、いささかも不足があるというものではございませんで、そういったところを踏まえて、全体として、区として、よりよいまちづくり、安心な心地よい品川区のまちづくりをしっかりと進めてまいりたいというふうに考えております。","voiceIndex":76,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"ストレートに答えてくださいまして、ありがとうあります。このひきこもりなのですけれども、結果的にはゼロではないですか。この辺について、担当の課長としては、この課題が大きすぎてしまったのかもしれませんけれども、その辺についてはどういうふうに思っていますか。","respondent":"河内協働・国際担当課長","answer":"ひきこもり等の問題については、引き続き、区の重要なテーマとして認識しております。","voiceIndex":78,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この事業について、ちょっといろいろとわからないことが多いので、教えていただきたいのですが、まず、この目的のところに、「区民と区との協働で『私たちのまち』品川区をつくる」と、こう書いてあるわけなのですが、この公募をして、応募できる対象というのは、区民ということではなくて、もっと幅広いところで活動している人が、区民と区の協働の事業を提案するという。","respondent":"河内協働・国際担当課長","answer":"そういったところの定例ミーティングなどでも、こういった課題でやりますのでというところで、皆様にご案内いたしながら、先ほど申しました支援員がございまして、例えばＡという団体がいたとすると、そのＡさんはこういった分野が、このテーマについて活用できないかなとか。","voiceIndex":80,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちなみに、この平成２５年度の予算と活動の中身について、具体的にちょっと教えていただきたいのと、あと今回３件が採択されたわけですけれども、この３件についても、多分もう予算についても、予算要求ということになっていくと思うのですけれども、どれぐらいの予算で委託をしていくのか、そのところについても教えていただきたいと思います。","respondent":"河内協働・国際担当課長","answer":"採択されました３件についての予算です。これは、所管と私どものほうで、今、予算審議の最中ですので、あくまで第２次審査の部分で提案された予算ということでご回答しますので、ご了承いただきたいと思います。","voiceIndex":82,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今年度も１件やっていると思うのですけれども、予算というのは、単年度というところなのでしょうか。そこら辺のところが、１年限りのそういう事業で終わってしまうのか、今までのこの９件についても、それがどのようにその後に継続をされていくのか、そこら辺のところはどうなっているのか教えてください。","respondent":"河内協働・国際担当課長","answer":"ご提案いただきました内容につきましては、単年度として行うものですが、このテーマに付随いたしまして、こういう切り口があるということでご提案いただきました折には、複数年度でしっかりと検討をし、対応するという姿勢で進めております。","voiceIndex":84,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"すみません、大体わかりかけてきたのですけれども、具体的なところをちょっと教えていただきたいのですが、区民提案型の「生涯現役社会の実現に向けた環境整備事業」というところで、シービー・シナガワというところがされるものなのですけれども、これは、「高齢者が支えられるだけの存在から支える側にもなれる好循環型の新しい社会基盤を構築するために。","respondent":"河内協働・国際担当課長","answer":"ただ、中身を吟味していきますと、要支援者などの取り扱いが変わってまいりますので、なるべく健康でいていただくように、そういったノウハウを持つ方が健康な高齢者の方に対しまして、どのような支援ができるのかというようなところを実感を持って進めていただくために。","voiceIndex":86,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一点だけ、すみません。今、予算をお聞きしたのですが、３番目の「品川夢都市プロジェクト」のところが２,３００万円ですか、このところだけがちょっと桁が違う感じなのですけれども、これを見ると、何かコラボイベントの開催を行うという、そういう感じの中身にしか、ちょっとなかなか見えないのですけれども、２,３００万円の予算がかかる、どんな事業なのかということもちょっと教えていただきたい。","respondent":"河内協働・国際担当課長","answer":"品川夢都市プロジェクトの件です。初期提案がございました２,３００万円ですが、この事業提案の内容ですが、主にダンスなどにつきまして、子どもたちがそういうことに取り組むことによって、まずは自分に自信をつけて生き生きとする。","voiceIndex":88,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと、何かその税金の使い方として、２,３００万円という、そういうのがどうなのかということも含めて、この中身をなぜ選んだのかというのが、本当にこれだとすごく簡単にしか出ていなくて、だけれども、すごく重要な、一つ一つが来年度の予算の中でこういう事業をやりますよというふうなことも報告されていくのだろうとは思うのですが、もうちょっと私は、詳しい説明資料で。","respondent":"河内協働・国際担当課長、中川原地域振興事業部長","answer":"つまり、内容と成果、あるいは実現性に向けて、本当にできるのか、適切か、税金の使い方について妥当かというところを、本来、協働というのは対等の立場で結ぶものなのですが、この事業に関して言えば、契約行為ということなので。それで、先ほどご質問がありました単年度の事業なのかということも、やはりそういう反省がありまして、大事なテーマの場合は３年間は継続してやろうとか、今までやってきた中でわかりづらかったこと等々を、今、実際に見直しています。","voiceIndex":90,"id":"exchange-033"}]},{"id":"topic-03","title":"区立総合区民会館・区立荏原平塚総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","agenda":"区立総合区民会館・区立荏原平塚総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","exchanges":[{"speaker":"井上委員","kind":"質問","question":"総合区民会館のところでお伺いをしたいと思います。対策としては、駐輪場の改修をしないと無理なのかもしれないのですけれども、そういうふうに断わられた人たちがどういうふうに進んでいくのかということ。総合体育館について、それをお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、クレームの中身についてもいろいろありますが、幅のことだとか、１台ずつ入れるだとか、そういうのは知っていますけれども、高さのことは初めて聞きましたので、またきゅりあんのほうと情報共有しながら進めていきたいと思います。","voiceIndex":97,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"高さのところでは、アトレのほうを紹介するとか、こちらの駐輪場をとか、入れませんではなくて、私が伺ったのは、アトレのほうのあそこに入れてくださいというようなご案内をしてくださったようなのですけれども、もし、そういうクレームがたくさんあるようでしたら対策も必要ですし、そういうフォローをしていただけたらなというふうに思っています。","respondent":"安藤文化スポーツ振興課長","answer":"それと、あとは施設の維持運営の中で、１年を経過してきまして、やはり場所によってはちょっと不都合なところはありますので、そこは順次、改修をしていこうというふうに考えています。","voiceIndex":99,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"だけれども、あの施設は、この広場のところは公園という位置づけではないという説明があって、だけれども、一体化の広場になっているので、子どもたちは公園として使っているので、地面のところの、転んでしまうとけがをする、すり傷があるという状況で、当事者意見が全然反映されていないので、公園部分は配慮がしてあっても、一体化されている公園と利用者側は捉えるというようなところで。","respondent":"安藤文化スポーツ振興課長","answer":"計画の段階から、広場も含めまして、住民説明会、町会の方々のご意見、いろんな団体の方から意見を聞きながら進めてまいりました。今の広場のところも、あそこの平塚公園のところは遊具がありますので、これは安全の配慮かと認識しています。","voiceIndex":101,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"承知の上で、すみません、少し入り込みすぎたかもしれませんけれども、やっぱり設計段階で、そこはそういう行政の意図的な思いはあっても、結果的に公園というような、利用者側からはそういうふうな捉え方が当然だというふうに思いますので、そこについて対応されている方たちが、禁止、禁止ではなく、やりとりをしながら解決に向かっていただきたいということを、ぜひ要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば、エレベーターまでの点字ブロックがなかったのが敷設されたりとかということはあるのですけれども、まだまだ全然、ずっともう何年も前から要望しているにもかかわらず、黄色ではなくて、小ホール側の床の色と同じ灰色になっていて、この凹凸の出っ張りの部分が基準よりすごく低いために、足の裏に感じにくい、点字ブロックを感じにくいというふうな問題だったりとか。","respondent":"安藤文化スポーツ振興課長","answer":"それで、これまでやってきましたけれども、全国区のきゅりあんということで、人気が高うあります。しかし、まだまだ、こうやって見ますと、ここには全体で９０.５％となっていますけれども、講習室があったりだとか、ホールもあったり、いろいろなイベントなどもあります。","voiceIndex":105,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"きゅりあんにしても、本当にとるのが大変というのがあるので、そういうところからすると、私は、区民が利用しやすいための施設計画というのもぜひ持っていただきたいということで、１００％を目指すということと同時に、それだけの要望があるということの裏には、利用できないという実態もあるというふうなところから、区民の要望に応える施設計画というのも、ぜひしていただきたいというふうに思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな形で、区民の優先度を第一に考えてやっているところです。それから、荏原文化センターは今、改修工事に入っていますが、荏原文化センターの利用団体の説明会のときにも、中延小学校を初め、スクエア荏原の皆様のほうにご説明をして、ご案内をしてきたところです。","voiceIndex":107,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めまして、ほかの地域センターですとかと比べても、本当にかなり高い利用料になっていますので、それを引き下げていただきたいということで、要望は改めてさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-040"},{"speaker":"本多委員","kind":"質問","question":"きゅりあんの利用率が上がるようにと思うのですが、それで、ちょっと個別の使用ケースなのですけれども、太鼓とか鳴り物を使うときに、ほかの部屋への振動や音で、使う制限が今までは大きかったと思うのですが、これはいろいろ、この修繕とか改修をやっていく中で、改善等はされていくのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"今後、先ほどちょっとご説明をさせていただきましたけれども、天井の改修工事等も予定していますが、できる、できないかはちょっとわかりませんけれども、今回の改修工事において、それを重要な議題には出していきたいというふうに考えています。","voiceIndex":110,"id":"exchange-041"},{"speaker":"浅野委員","kind":"質問","question":"１点だけお願いしたいのですが、このスクエア荏原のほうですけれども、今話に出ましたけれども、利用率が６２.６％とありますが、全体だと思うのですが、高いところ、低いところ、特徴的なところを端的に教えていただければと思います。","respondent":"安藤文化スポーツ振興課長","answer":"低いところは、４階に和室があるのですが、和室については、やはりちょっと低いかなという程度です。これは４３.８％です。","voiceIndex":112,"id":"exchange-042"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"これ、私は初めて伺ったので、すみません。内容なのですけれども、地域センターごとに、毎年毎年、３地区ぐらいが順番で報告をしていって、毎年行われるもので、全部回ったらまた初めからとか、そういう企画でしょうか。","respondent":"河内協働・国際担当課長","answer":"当会につきましては、隔年実施です。その中で、主に発表するべき事項といたしまして、調整した結果、今回は３地区のものについて発表するというものです。","voiceIndex":124,"id":"exchange-043"},{"speaker":"井上委員","kind":"意見","question":"活動が活発なところだけの紹介なのか、ふれあいサポート活動というのは、各地域センターを拠点にやっているので、順番に全部の地域の方たちが発表する機会を設けているのかどうか。","respondent":"河内協働・国際担当課長","answer":"もちろん、順繰りという場合もありますが、あくまで自主的にこういった発表をすべきというようなところで、自主的なもので意向が示されたところからやるのが原則になります。","voiceIndex":126,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2708#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":45909,"voices":132}}]);
